function defaultTeamSharedBuffs() {
  return {
    buffs: [],
    globalBuffActive: {},
    globalBuffStacks: {},
    activeBuffTab: 'elementBonus',
    activeBuffGroup: 'bonus',
    expanded: true,
  };
}

let sharedBuffsCache = null;   // { sbRef, buffsRef } 指纹；写入口显式失效

function invalidateSharedBuffsCache() {
  sharedBuffsCache = null;
}

function ensureTeamSharedBuffs() {
  if (!state.team) {
    state.team = {
      axisDuration: 20,
      monsterRes: 20,
      monsterLevel: 100,
      activeIndex: 0,
      viewMode: 'member',
      sharedBuffs: defaultTeamSharedBuffs(),
    };
  }
  if (!state.team.sharedBuffs) state.team.sharedBuffs = defaultTeamSharedBuffs();
  const sb = state.team.sharedBuffs;
  const buffsRef = sb.buffs;
  // 读路径纯读取：sb 与 buffs 引用均未变时返回同一对象（filter+map 已规范化结果）
  if (sharedBuffsCache && sharedBuffsCache.sbRef === sb && sharedBuffsCache.buffsRef === buffsRef) {
    return sb;
  }
  sb.buffs = (buffsRef || [])
    .filter((b) => b?.category !== 'convergence')
    .map((b) =>
      normalizeBuff({
        ...b,
        damageType: b.damageType || '',
        defenseKind: b.defenseKind || (DEFENSE_BUFF_CATS.has(b.category) ? 'pen' : ''),
      })
    );
  if (!sb.globalBuffActive) sb.globalBuffActive = {};
  if (!sb.globalBuffStacks) sb.globalBuffStacks = {};
  syncMemberBuffTabs(sb, TEAM_BUFF_TAB_GROUPS);
  sharedBuffsCache = { sbRef: sb, buffsRef: sb.buffs };
  return sb;
}

/** 全队 Buff 在角色侧的镜像 ID：由 teamSourceId 推导，避免导入/重同步后 genId 导致技能勾选失效 */
function makeTeamMirrorBuffId(teamBuffId) {
  const id = String(teamBuffId || '').trim();
  if (!id) return genId();
  return id.startsWith('tm_') ? id : `tm_${id}`;
}

function mirrorTeamBuffPayload(teamBuff) {
  const payload = {
    category: teamBuff.category,
    name: teamBuff.name,
    mode: teamBuff.mode,
    value: teamBuff.value,
    perStack: teamBuff.perStack,
    maxStacks: teamBuff.maxStacks,
    damageType: teamBuff.damageType || '',
    effectType:
      teamBuff.damageType === '效应' ? normalizeBuffEffectType(teamBuff.effectType) : undefined,
    element: teamBuff.element || '',
    defenseKind: teamBuff.defenseKind || (DEFENSE_BUFF_CATS.has(teamBuff.category) ? 'pen' : ''),
    convergenceVuln: Number.isFinite(Number(teamBuff.convergenceVuln))
      ? Number(teamBuff.convergenceVuln)
      : CONVERGENCE_DEFAULT_VULN,
    teamSourceId: teamBuff.id,
  };
  if (teamBuff.category === 'matrixFinal') {
    payload.clampStacks = !!teamBuff.clampStacks;
    if (teamBuff.matrixSource) payload.matrixSource = { ...teamBuff.matrixSource };
  }
  if (payload.effectType === undefined) delete payload.effectType;
  if (teamBuff.sourceTag) payload.sourceTag = teamBuff.sourceTag;
  if (teamBuff.templateKey) payload.templateKey = teamBuff.templateKey;
  if (teamBuff.sourceCharacterId) payload.sourceCharacterId = teamBuff.sourceCharacterId;
  if (teamBuff.weaponId) payload.weaponId = teamBuff.weaponId;
  if (teamBuff.weaponGenerated) payload.weaponGenerated = true;
  if (teamBuff.weaponTeamBuff) payload.weaponTeamBuff = true;
  if (teamBuff.echoSetTeamBuff) payload.echoSetTeamBuff = true;
  if (teamBuff.echoMainTeamBuff) payload.echoMainTeamBuff = true;
  if (teamBuff.echoSetSourceId) payload.echoSetSourceId = teamBuff.echoSetSourceId;
  if (teamBuff.echoMainSourceId) payload.echoMainSourceId = teamBuff.echoMainSourceId;
  if (teamBuff.echoSetTier != null) payload.echoSetTier = teamBuff.echoSetTier;
  if (teamBuff.stackSync) payload.stackSync = teamBuff.stackSync;
  if (teamBuff.activeSync) payload.activeSync = teamBuff.activeSync;
  if (teamBuff.tongzouSharedKey) payload.tongzouSharedKey = teamBuff.tongzouSharedKey;
  if (teamBuff.tongzouStackScope) payload.tongzouStackScope = teamBuff.tongzouStackScope;
  if (teamBuff.tongzouStackOwner) payload.tongzouStackOwner = teamBuff.tongzouStackOwner;
  if (teamBuff.tongzouLinkedStack) payload.tongzouLinkedStack = true;
  if (teamBuff.combatModeKey) payload.combatModeKey = teamBuff.combatModeKey;
  if (typeof normalizeBuffGameText === 'function') {
    const gt = normalizeBuffGameText(teamBuff.gameText);
    if (gt) payload.gameText = gt;
  }
  if (Array.isArray(teamBuff.effects)) {
    payload.effects = teamBuff.effects.map((fx) => normalizeCompositeEffect({ ...fx, id: genId() }));
  }
  return payload;
}

function isAutoGeneratedTeamBuff(buff) {
  return !!(buff?.weaponTeamBuff || buff?.echoSetTeamBuff || buff?.echoMainTeamBuff);
}

/** 展示用前缀：【声骸】【本体】【武器】【全队·角色】 */
const MANAGED_BUFF_SOURCE_PREFIX_RE =
  /^(?:【(?:声骸|本体|武器|全队·[^】]*)】|\[(?:声骸|本体|武器(?:被动)?)\])\s*/u;

function stripManagedBuffSourcePrefixes(name) {
  let s = String(name || '').trim();
  for (let i = 0; i < 4 && MANAGED_BUFF_SOURCE_PREFIX_RE.test(s); i += 1) {
    s = s.replace(MANAGED_BUFF_SOURCE_PREFIX_RE, '').trim();
  }
  return s;
}

function withManagedBuffSourcePrefix(name, prefix) {
  const base = stripManagedBuffSourcePrefixes(name);
  if (!prefix) return base;
  return `${prefix}${base}`;
}

function resolveTeamBuffSourceCharacterName(buff) {
  let src = buff;
  if (buff?.teamSourceId && state?.team?.sharedBuffs?.buffs) {
    const found = state.team.sharedBuffs.buffs.find((x) => x.id === buff.teamSourceId);
    if (found) src = found;
  }
  const idx = typeof getTeamBuffSourceMemberIndex === 'function' ? getTeamBuffSourceMemberIndex(src) : null;
  if (Number.isInteger(idx) && state.members?.[idx]) {
    const m = state.members[idx];
    const charName =
      m.characterId && typeof findCharSkillDef === 'function'
        ? findCharSkillDef(m.characterId)?.name
        : '';
    return String(m.name || charName || `角色${idx + 1}`).trim() || `角色${idx + 1}`;
  }
  if (src?.sourceCharacterId && typeof findCharSkillDef === 'function') {
    return findCharSkillDef(src.sourceCharacterId)?.name || '角色';
  }
  return '未指定';
}

/**
 * Buff 来源前缀（展示用）。
 * 全队（含镜像 / 武器·声骸队Buff）→【全队·角色】；声骸个人→【声骸】；武器个人→【武器】；角色本体/模板→【本体】。
 */
function getBuffSourcePrefix(buff, opts = {}) {
  if (!buff) return '';
  const teamLike =
    opts.scope === 'team' ||
    !!buff.teamSourceId ||
    !!buff.weaponTeamBuff ||
    !!buff.echoSetTeamBuff ||
    !!buff.echoMainTeamBuff;
  if (teamLike) return `【全队·${resolveTeamBuffSourceCharacterName(buff)}】`;
  if (
    (typeof isEchoSetGeneratedBuff === 'function' && isEchoSetGeneratedBuff(buff)) ||
    (typeof isEchoMainGeneratedBuff === 'function' && isEchoMainGeneratedBuff(buff))
  ) {
    return '【声骸】';
  }
  if (typeof isWeaponGeneratedBuff === 'function' && isWeaponGeneratedBuff(buff)) {
    return '【武器】';
  }
  if (
    (typeof isCharacterTemplateBuff === 'function' && isCharacterTemplateBuff(buff)) ||
    (typeof isProtectedSystemBuff === 'function' && isProtectedSystemBuff(buff))
  ) {
    return '【本体】';
  }
  return '';
}

function formatBuffDisplayName(buff, opts = {}) {
  if (!buff) return '';
  const prefix = getBuffSourcePrefix(buff, opts);
  const body = formatBuffNameBody(buff, opts);
  if (!prefix) return body;
  return `${prefix}${body}`;
}

/**
 * 声骸 Buff 展示用简称：
 * - 套装 → 套装名（详情见 gameText）
 * - 主位 → 保持「个体名 · 首位」
 */
function getEchoBuffSimplifiedBody(buff) {
  if (!buff) return '';
  let src = buff;
  if (buff.teamSourceId && typeof ensureTeamSharedBuffs === 'function') {
    const found = ensureTeamSharedBuffs().buffs.find((b) => b.id === buff.teamSourceId);
    if (found) src = found;
  }
  const isMain =
    !!src.echoMainTeamBuff ||
    !!src.echoMainGenerated ||
    !!src.echoMainSourceId ||
    (typeof isEchoMainTeamBuff === 'function' && isEchoMainTeamBuff(src)) ||
    (typeof isEchoMainGeneratedBuff === 'function' && isEchoMainGeneratedBuff(src));
  if (isMain) {
    const specimenId = String(src.echoMainSourceId || '').trim();
    const sp =
      specimenId && typeof findEchoSpecimen === 'function' ? findEchoSpecimen(specimenId) : null;
    if (sp && typeof buildEchoMainSlotLabel === 'function') {
      return buildEchoMainSlotLabel(sp);
    }
    return stripManagedBuffSourcePrefixes(src.name || buff.name);
  }
  const isSet =
    !!src.echoSetTeamBuff ||
    !!src.echoSetGenerated ||
    !!src.echoSetSourceId ||
    (typeof isEchoSetTeamBuff === 'function' && isEchoSetTeamBuff(src)) ||
    (typeof isEchoSetGeneratedBuff === 'function' && isEchoSetGeneratedBuff(src));
  if (isSet) {
    let setId = String(src.echoSetSourceId || '').trim();
    if (!setId && typeof resolveEchoGameTextSource === 'function') {
      const echoSrc = resolveEchoGameTextSource(src);
      if (echoSrc?.kind === 'echoSet') setId = echoSrc.id;
    }
    const setDef = setId && typeof findEchoSetDef === 'function' ? findEchoSetDef(setId) : null;
    if (setDef?.name) return String(setDef.name).trim();
  }
  return stripManagedBuffSourcePrefixes(buff.name);
}

function isEchoManagedBuff(buff) {
  if (!buff) return false;
  return (
    !!buff.echoSetTeamBuff ||
    !!buff.echoMainTeamBuff ||
    !!buff.echoSetGenerated ||
    !!buff.echoMainGenerated ||
    !!buff.echoSetSourceId ||
    !!buff.echoMainSourceId ||
    (typeof isEchoSetTeamBuff === 'function' && isEchoSetTeamBuff(buff)) ||
    (typeof isEchoMainTeamBuff === 'function' && isEchoMainTeamBuff(buff)) ||
    (typeof isEchoSetGeneratedBuff === 'function' && isEchoSetGeneratedBuff(buff)) ||
    (typeof isEchoMainGeneratedBuff === 'function' && isEchoMainGeneratedBuff(buff))
  );
}

/** 名称输入框内容：去掉一级来源前缀；全队条目保留【声骸】【本体】[武器] 次级标记 */
function formatBuffNameBody(buff, opts = {}) {
  if (!buff) return '';
  const prefix = getBuffSourcePrefix(buff, opts);
  const raw = String(buff.name || '').trim();
  if (!prefix) return raw;
  let base = isEchoManagedBuff(buff)
    ? getEchoBuffSimplifiedBody(buff)
    : stripManagedBuffSourcePrefixes(raw);
  // 全队条目保留武器/声骸/本体次级标记，避免只剩角色名看不出装备来源
  if (prefix.startsWith('【全队·')) {
    if (
      buff.weaponTeamBuff ||
      (typeof isWeaponGeneratedBuff === 'function' && isWeaponGeneratedBuff(buff)) ||
      /^\[武器\]/.test(raw) ||
      /^【武器】/.test(raw)
    ) {
      base = base.replace(/^\[武器(?:被动)?\]\s*/, '').replace(/^【武器】\s*/, '');
      base = `【武器】${base}`;
    } else if (
      isEchoManagedBuff(buff) ||
      /^【声骸】/.test(raw) ||
      /^\[声骸\]/.test(raw)
    ) {
      base = `【声骸】${base}`;
    } else if (
      (typeof isCharacterTemplateBuff === 'function' && isCharacterTemplateBuff(buff)) ||
      /^【本体】/.test(raw)
    ) {
      base = `【本体】${base}`;
    }
  }
  return base;
}

/** 编辑行：来源蓝标签 + 名称输入（可编辑/只读统一） */
function renderBuffNameFieldHtml(buff, opts = {}) {
  const { scope, nameAttr, buffId, readonly = false } = opts;
  const srcPrefix = getBuffSourcePrefix(buff, { scope });
  const nameDisplay = srcPrefix
    ? formatBuffNameBody(buff, { scope })
    : String(buff?.name || '');
  const prefixHtml = srcPrefix
    ? `<span class="buff-source-prefix" title="来源">${escapeHtml(srcPrefix)}</span>`
    : '';
  const roAttr = readonly ? ' readonly' : '';
  return `<span class="buff-name-field">${prefixHtml}<input type="text" ${nameAttr}="${buffId}" value="${escapeHtml(
    nameDisplay
  )}" placeholder="来源名称"${roAttr} /></span>`;
}

function getTeamBuffSourceMemberIndex(buff) {
  if (!buff) return null;
  if (Number.isInteger(buff.sourceMemberIndex) && buff.sourceMemberIndex >= 0 && buff.sourceMemberIndex <= 2) {
    return buff.sourceMemberIndex;
  }
  if (buff.weaponTeamBuff && Number.isInteger(buff.weaponSourceMemberIndex)) {
    return Math.max(0, Math.min(2, buff.weaponSourceMemberIndex));
  }
  if (buff.echoSetTeamBuff && Number.isInteger(buff.echoSetSourceMember)) {
    return Math.max(0, Math.min(2, buff.echoSetSourceMember));
  }
  if (buff.echoMainTeamBuff && Number.isInteger(buff.echoMainSourceMember)) {
    return Math.max(0, Math.min(2, buff.echoMainSourceMember));
  }
  return null;
}

/** 兼容已保存的心、锁暝旧模板：这些延奏增益对来源角色本人不生效。 */
function isNextMemberOnlyBuff(buff) {
  const key = String(buff?.templateKey || '');
  return key === 'xin_tz_outro_deep' ||
    key === 'suoming_innate2_xieqi_base' ||
    key === 'suoming_innate2_xieqi_stack' ||
    key === 'suoming_outro_elec_deep' ||
    key === 'suoming_outro_reso_deep' ||
    key === 'suoming_c2_outro_critdmg_base' ||
    key === 'suoming_c2_outro_critdmg_stack';
}

function renderTeamBuffAutoTag(b) {
  if (b.weaponTeamBuff) {
    return `<span class="team-buff-tag team-buff-tag--weapon" title="武器自动生成">武器</span>`;
  }
  if (b.echoSetTeamBuff) {
    return `<span class="team-buff-tag team-buff-tag--set" title="声骸套装自动生成">套装</span>`;
  }
  if (b.echoMainTeamBuff) {
    return `<span class="team-buff-tag team-buff-tag--echo" title="主位声骸自动生成">声骸</span>`;
  }
  return '';
}

/** Buff 来源卡片左侧色条分类 */
function getTeamBuffEntrySourceKind(b) {
  if (!b) return '自定义';
  if (b.weaponTeamBuff) return '武器';
  if (b.echoSetTeamBuff) return '套装';
  if (b.echoMainTeamBuff) return '声骸';
  return '自定义';
}

/** Buff 来源条目分类色：优先走统计大类标签 */
function getTeamBuffEntryTypeLabel(b) {
  if (typeof getBuffStatTypeLabel === 'function') {
    const label = getBuffStatTypeLabel(b);
    if (label) return label;
  }
  if (!b) return '';
  if (typeof isCompositeBuff === 'function' && isCompositeBuff(b)) return '复合';
  if (b.category === 'composite') return '复合';
  const cat = String(b.category || '');
  if (/Attack|flatAtk|DefPct|HpPct/i.test(cat)) return '攻击力';
  if (/mult/i.test(cat)) return '倍率';
  if (/Deep/i.test(cat)) return '加深';
  if (/Bonus/i.test(cat)) return '增伤';
  if (/CritDmg|CritRate|critRate/i.test(cat)) return /CritRate|critRate/i.test(cat) ? '双暴' : '暴伤';
  if (/Defense|ResReduce/i.test(cat)) return '防御';
  if (/Vulnerability|convergence/i.test(cat)) return '易伤';
  if (/harmony|Harmony|offsetHarmony/i.test(cat)) return '谐幅';
  return '';
}

/** 来源面板打开叠层设置时默认作用的接收角色 */
function resolveTeamBuffSourceStackMemberIndex(buff) {
  const src = typeof getTeamBuffSourceMemberIndex === 'function' ? getTeamBuffSourceMemberIndex(buff) : null;
  if (Number.isInteger(src) && src >= 0 && src <= 2) return src;
  const active = Number.isInteger(state?.team?.activeIndex) ? state.team.activeIndex : null;
  if (Number.isInteger(active) && active >= 0 && active <= 2) {
    const cell = resolveTeamBuffAssignCellState(buff, active);
    if (cell && cell.kind !== 'empty' && cell.kind !== 'locked') return active;
  }
  for (let i = 0; i < 3; i += 1) {
    const cell = resolveTeamBuffAssignCellState(buff, i);
    if (cell && cell.kind !== 'empty' && cell.kind !== 'locked') return i;
  }
  return Number.isInteger(active) ? Math.max(0, Math.min(2, active)) : 0;
}

const STACK_INDICATOR_ICON = `<svg class="stack-indicator__icon" width="12" height="12" viewBox="0 0 14 14" aria-hidden="true" focusable="false"><path d="M2 4.2h10M2 7h10M2 9.8h10" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>`;

/** 来源面板：叠层 badge（点击打开与分配页相同的叠层设置） */
function renderTeamBuffStackIndicator(b) {
  if (!b || !isStackBuff(b)) return '';
  const mi = resolveTeamBuffSourceStackMemberIndex(b);
  const cell = resolveTeamBuffAssignCellState(b, mi);
  const stacks = cell?.stacks ?? readTeamBuffAssignStackCount(b, mi);
  const maxStacks = Math.max(1, Number(cell?.maxStacks) || Number(b.maxStacks) || 5);
  const autoStack = !!cell?.autoStack;
  const tip = autoStack
    ? '自动同步层数（只读）'
    : stacks > 0
      ? `点击调整叠层（当前 x${stacks}，作用于角色${mi + 1}）`
      : `点击设置叠层（作用于角色${mi + 1}）`;
  const autoAttr = autoStack ? ' data-tba-auto-stack="1"' : '';
  return `<button type="button" class="stack-indicator" data-tba-stack-open="${escapeHtml(String(b.id))}" data-member-index="${mi}" data-tba-max-stacks="${maxStacks}"${autoAttr} title="${escapeHtml(tip)}" aria-label="${escapeHtml(tip)}">
            ${STACK_INDICATOR_ICON}
            <span>叠层</span>
            <span class="stack-indicator__count" data-stack-count>x${stacks}</span>
          </button>`;
}

function renderTeamBuffDeleteButton(b) {
  if (!b || isAutoGeneratedTeamBuff(b)) return '';
  if (typeof isProtectedSystemBuff === 'function' && isProtectedSystemBuff(b)) {
    return `<button type="button" class="delete-btn buff-entry-delete" data-del-team-buff="${b.id}" disabled title="角色固有，不可删除" aria-label="删除">×</button>`;
  }
  return `<button type="button" class="delete-btn buff-entry-delete" data-del-team-buff="${b.id}" title="删除" aria-label="删除">×</button>`;
}

function renderTeamBuffActionCell(b) {
  // 归属已由左侧【全队·角色】蓝标签展示，不再重复下来源下拉
  const autoTag = renderTeamBuffAutoTag(b);
  if (autoTag) return `<span class="team-buff-actions">${autoTag}</span>`;
  return `<span class="team-buff-actions">${renderTeamBuffDeleteButton(b)}</span>`;
}

/** Buff 来源卡片左侧色条分类（成员/抽屉） */
function getMemberBuffEntrySourceKind(b, scope = 'member') {
  if (!b) return '';
  const prefix = typeof getBuffSourcePrefix === 'function' ? getBuffSourcePrefix(b, { scope }) : '';
  if (prefix.startsWith('【全队')) return '全队';
  if (prefix === '【武器】') return '武器';
  if (prefix === '【本体】') return '本体';
  if (prefix === '【声骸】') {
    if (
      b.echoSetTeamBuff ||
      b.echoSetGenerated ||
      (typeof isEchoSetGeneratedBuff === 'function' && isEchoSetGeneratedBuff(b))
    ) {
      return '套装';
    }
    return '声骸';
  }
  if (b.teamSourceId || b.weaponTeamBuff || b.echoSetTeamBuff || b.echoMainTeamBuff) return '全队';
  if (
    b.echoSetTeamBuff ||
    b.echoSetGenerated ||
    (typeof isEchoSetGeneratedBuff === 'function' && isEchoSetGeneratedBuff(b))
  ) {
    return '套装';
  }
  if (
    b.echoMainTeamBuff ||
    b.echoMainGenerated ||
    (typeof isEchoMainGeneratedBuff === 'function' && isEchoMainGeneratedBuff(b))
  ) {
    return '声骸';
  }
  if (typeof isWeaponGeneratedBuff === 'function' && isWeaponGeneratedBuff(b)) return '武器';
  if (
    (typeof isCharacterTemplateBuff === 'function' && isCharacterTemplateBuff(b)) ||
    (typeof isProtectedSystemBuff === 'function' && isProtectedSystemBuff(b))
  ) {
    return '本体';
  }
  return '';
}

function renderMemberBuffDeleteButton(b, { isProtected = false, isTeamMirror = false } = {}) {
  if (!b) return '';
  if (isProtected) {
    return `<button type="button" class="delete-btn buff-entry-delete" data-del-buff="${b.id}" disabled title="角色固有，不可删除" aria-label="删除">×</button>`;
  }
  if (isTeamMirror) {
    return `<button type="button" class="delete-btn buff-entry-delete" data-del-buff="${b.id}" title="仅从本角色移除" aria-label="删除">×</button>`;
  }
  return `<button type="button" class="delete-btn buff-entry-delete" data-del-buff="${b.id}" title="删除" aria-label="删除">×</button>`;
}

/** Buff 来源面板：卡片头部（来源标签 + 名称 + 删除） */
function renderBuffEntryHeaderHtml(b, opts = {}) {
  const {
    scope,
    nameAttr,
    buffId,
    readonly = false,
    isProtected = false,
    isTeamMirror = false,
    catTagHtml = '',
  } = opts;
  const srcPrefix = getBuffSourcePrefix(b, { scope });
  const nameDisplay = srcPrefix
    ? formatBuffNameBody(b, { scope })
    : String(b?.name || '');
  const prefixHtml = srcPrefix
    ? `<span class="source-tag buff-source-tag buff-source-prefix" title="来源">${escapeHtml(srcPrefix)}</span>`
    : '';
  const roAttr = readonly ? ' readonly' : '';
  const deleteHtml =
    scope === 'team'
      ? renderTeamBuffDeleteButton(b)
      : renderMemberBuffDeleteButton(b, { isProtected, isTeamMirror });
  return `<div class="buff-entry-header">
            <div class="buff-entry-title">
              ${prefixHtml}
              ${catTagHtml}
              <input type="text" class="buff-entry-name buff-name" ${nameAttr}="${buffId}" value="${escapeHtml(
                nameDisplay
              )}" placeholder="来源名称"${roAttr} />
            </div>
            ${deleteHtml}
          </div>`;
}

function ensureExcludedTeamBuffIds(target) {
  if (!Array.isArray(target.excludedTeamBuffIds)) target.excludedTeamBuffIds = [];
  return target.excludedTeamBuffIds;
}

function ensureManuallyExcludedTeamBuffIds(target) {
  if (!Array.isArray(target.manuallyExcludedTeamBuffIds)) target.manuallyExcludedTeamBuffIds = [];
  return target.manuallyExcludedTeamBuffIds;
}

function excludeTeamBuffFromTarget(target, teamBuffSourceId) {
  if (!target || !teamBuffSourceId) return;
  const shared = ensureTeamSharedBuffs();
  const teamBuff = (shared.buffs || []).find((b) => b.id === teamBuffSourceId);
  const isSpecialChar =
    Array.isArray(state.specialSkills?.characters) &&
    state.specialSkills.characters.includes(target);
  // 特殊技能库：易伤/穿防等默认同步乘区不可排除（否则「Buff角色=来源角色」会丢全队镜像）
  if (
    isSpecialChar &&
    teamBuff &&
    typeof isSpecialDefaultSyncBuffSource === 'function' &&
    isSpecialDefaultSyncBuffSource(teamBuff) &&
    !(typeof isUserToggleableTeamSyncBuff === 'function' && isUserToggleableTeamSyncBuff(teamBuff))
  ) {
    return;
  }
  const excluded = ensureExcludedTeamBuffIds(target);
  if (!excluded.includes(teamBuffSourceId)) excluded.push(teamBuffSourceId);
  const manual = ensureManuallyExcludedTeamBuffIds(target);
  if (!manual.includes(teamBuffSourceId)) manual.push(teamBuffSourceId);
  const mirror = target.buffs.find((b) => b.teamSourceId === teamBuffSourceId);
  const mirrorId = makeTeamMirrorBuffId(teamBuffSourceId);
  if (!target.globalBuffStacks) target.globalBuffStacks = {};
  if (!shared.globalBuffStacks) shared.globalBuffStacks = {};
  // 取消覆盖前固化层数（镜像 id / 稳定 id / shared），反复勾选不丢层
  const keptStacks = normalizeStackInput(
    (mirror && target.globalBuffStacks[mirror.id] !== undefined
      ? target.globalBuffStacks[mirror.id]
      : undefined) ??
      target.globalBuffStacks[mirrorId] ??
      shared.globalBuffStacks[teamBuffSourceId] ??
      0
  );
  target.globalBuffStacks[mirrorId] = keptStacks;
  if (shared.globalBuffStacks[teamBuffSourceId] === undefined) {
    shared.globalBuffStacks[teamBuffSourceId] = keptStacks;
  }
  if (mirror) {
    target.buffs = target.buffs.filter((b) => b.id !== mirror.id);
    purgeMemberBuffReferences(target, mirror.id);
  } else {
    target.buffs = target.buffs.filter((b) => b.teamSourceId !== teamBuffSourceId);
  }
  normalizeMemberBuffKeys(target);
  // 取消覆盖后也要刷新：莫宁偏谐→面板→达妮娅谐幅等
  if (typeof refreshRuntimeConvertedTeamBuffs === 'function') {
    refreshRuntimeConvertedTeamBuffs();
  }
}

function ensureExcludedPersonalBuffIds(target) {
  if (!Array.isArray(target.excludedPersonalBuffIds)) target.excludedPersonalBuffIds = [];
  return target.excludedPersonalBuffIds;
}

function excludePersonalBuffFromTarget(target, personalBuffSourceId, specialCharIndex) {
  if (!target || !personalBuffSourceId) return;
  const excluded = ensureExcludedPersonalBuffIds(target);
  if (!excluded.includes(personalBuffSourceId)) excluded.push(personalBuffSourceId);
  const mirror = target.buffs.find((b) => b.personalSourceId === personalBuffSourceId);
  if (mirror) {
    target.buffs = target.buffs.filter((b) => b.id !== mirror.id);
    purgeMemberBuffReferences(target, mirror.id);
    if (Number.isFinite(specialCharIndex) && specialCharIndex >= 0) {
      purgeSpecialSkillItemBuffReferences(mirror.id, specialCharIndex);
    }
  } else {
    target.buffs = target.buffs.filter((b) => b.personalSourceId !== personalBuffSourceId);
  }
  normalizeMemberBuffKeys(target);
}

function isSpecialVulnerabilityBuffSource(buff) {
  if (!buff) return false;
  if (
    buff.category === 'generalVulnerability' ||
    buff.category === 'elementVulnerability' ||
    buff.category === 'typeVulnerability' ||
    buff.category === 'extraVulnerability'
  ) {
    return true;
  }
  if (isCompositeBuff(buff)) {
    return (buff.effects || []).some(
      (fx) =>
        fx?.zone === 'generalVulnerability' ||
        fx?.zone === 'elementVulnerability' ||
        fx?.zone === 'typeVulnerability' ||
        fx?.zone === 'extraVulnerability'
    );
  }
  return false;
}

/** 全队/个人防御（穿防/无视）：默认同步到特殊技能板块 */
function isSpecialDefenseBuffSource(buff) {
  if (!buff) return false;
  if (DEFENSE_BUFF_CATS.has(buff.category)) return true;
  if (isCompositeBuff(buff)) {
    return (buff.effects || []).some((fx) => DEFENSE_BUFF_CATS.has(fx?.zone));
  }
  return false;
}

/** 减抗（泛用/类型/属性）：特殊技能默认同步（不要求伤害类型=效应） */
function isSpecialResReduceBuffSource(buff) {
  if (!buff) return false;
  if (
    buff.category === 'generalResReduce' ||
    buff.category === 'typeResReduce' ||
    buff.category === 'elementResReduce'
  ) {
    return true;
  }
  if (isCompositeBuff(buff)) {
    return (buff.effects || []).some(
      (fx) =>
        fx?.zone === 'generalResReduce' ||
        fx?.zone === 'typeResReduce' ||
        fx?.zone === 'elementResReduce'
    );
  }
  return false;
}

/** 易伤 / 防御 / 减抗：特殊技能默认同步（不要求伤害类型=效应） */
function isSpecialDefaultSyncBuffSource(buff) {
  return (
    isSpecialVulnerabilityBuffSource(buff) ||
    isSpecialDefenseBuffSource(buff) ||
    isSpecialResReduceBuffSource(buff)
  );
}
/** 用户要求可手动取消覆盖的全队默认同步 Buff（雪锈 / 洛瑟菈·全队·霜渐）：
 *  默认仍自动同步进全队与特殊技能库，但允许按角色取消勾选覆盖，且不被同步强制重开。 */
function isUserToggleableTeamSyncBuff(buff) {
  if (!buff) return false;
  if (isHarmonyBreakAmpBuff(buff) || (isCompositeBuff(buff) &&
    (buff.effects || []).some(fx => fx?.zone === 'harmonyBreakAmp'))) return true;
  const key = String(buff.templateKey || '');
  if (
    key === FEIXUE_XUEXIU_TEAM_KEY ||
    key === LOSERA_TEAM_RES_REDUCE_KEY ||
    key === QIANXIAO_XUWUWENHEN_KEY ||
    key === QIANXIAO_ANYINGXIAO_KEY
  ) {
    return true;
  }
  // 旧存档可能丢 templateKey：按精确同名兜底（个人/全队同名均按用户要求可手动开关；不含「千被动」）
  const name = String(buff.name || '').trim();
  return (
    name === '雪锈' ||
    name === '虚无纹痕' ||
    name === '虚湮之线' ||
    name === '暗效应' ||
    name === '虚湮效应'
  );
}

function isSpecialEffectBuffSource(buff) {
  if (!buff) return false;
  if (buff.category === 'matrixFinal' || isHarmonyBreakAmpBuff(buff)) return true;
  // 全队/个人易伤、穿防/无视防御：默认同步到特殊技能板块（不要求伤害类型=效应）
  if (isSpecialDefaultSyncBuffSource(buff)) return true;
  if (buff.damageType === '效应' && SPECIAL_ALLOWED_BUFF_CATS.has(buff.category)) return true;
  if (isCompositeBuff(buff)) {
    return (buff.effects || []).some(
      (fx) => fx?.zone === 'harmonyBreakAmp' ||
        (fx?.damageType === '效应' && SPECIAL_ALLOWED_BUFF_CATS.has(fx.zone))
    );
  }
  return false;
}

/** 特殊角色库允许保留的 Buff（含带效应/特判乘区的复合；含集谐模态系统易伤） */
function isSpecialAllowedBuff(buff) {
  if (!buff) return false;
  // 右键手动加入特殊技能计算的个人 Buff：即使不满足自动分类也保留
  if (buff?.manualSpecialAdd) return true;
  if (isSystemConvergenceBuff(buff)) return true;
  // 全队/个人易伤、穿防：即使落在 element* 分类也必须保留，避免同步后被洗掉
  if (typeof isSpecialDefaultSyncBuffSource === 'function' && isSpecialDefaultSyncBuffSource(buff)) {
    return true;
  }
  if (SPECIAL_ALLOWED_BUFF_CATS.has(buff.category)) return true;
  if (isCompositeBuff(buff)) {
    return (buff.effects || []).some((fx) => SPECIAL_ALLOWED_BUFF_CATS.has(fx?.zone));
  }
  return false;
}

function shouldSyncPersonalBuffToSpecial(memberBuff) {
  if (!memberBuff || memberBuff.teamSourceId || memberBuff.personalSourceId) return false;
  // 集谐模态系统 Buff：同步到特殊技能来源库，参与易伤计算
  if (isSystemConvergenceBuff(memberBuff)) return true;
  if (isProtectedSystemBuff(memberBuff)) return false;
  if (memberBuff.category === 'harmonyBreakAmp') return false;
  if (isConvergenceBuffCategory(memberBuff.category)) return false;
  // 效应类个人 Buff
  if (isSpecialEffectBuffSource(memberBuff)) return true;
  // 指定特殊技能库技能的个人复合 Buff（如露西【后门】→骇破响应）需同步到特殊角色库
  if (personalBuffTargetsSpecialSkillLibrary(memberBuff)) return true;
  // 绯雪个人【雪锈】（暴伤）：仅在绯雪槽由 sync 侧再放行（见 strip / 条件同步）
  return false;
}

/** 个人复合 Buff 是否点名特殊技能库中的技能（需同步到特殊技能来源库才生效） */
function personalBuffTargetsSpecialSkillLibrary(buff) {
  if (!isCompositeBuff(buff)) return false;
  const specialNames = [];
  Object.values(SPECIAL_SKILL_LIBRARIES || {}).forEach((entries) => {
    (entries || []).forEach((e) => {
      const n = String(e?.name || '').trim();
      if (n) specialNames.push(n);
    });
  });
  if (!specialNames.length) return false;
  return (buff.effects || []).some((fx) => {
    if (!SPECIAL_ALLOWED_BUFF_CATS.has(fx?.zone)) return false;
    if ((fx?.skillScope || 'all') !== 'names') return false;
    const named = [...(fx.librarySkillNames || []), ...(fx.skillNames || [])]
      .map((n) => String(n || '').trim())
      .filter(Boolean);
    if (!named.length) return false;
    return named.some((n) =>
      specialNames.some(
        (sn) => skillNamesLooselyMatch(n, sn) || skillNamesLooselyMatch(sn, n)
      )
    );
  });
}

/** 绯雪专属【雪锈】（个人/全队/落单同名），非绯雪特殊槽不应出现 */
function isFeixueBoundSpecialBuff(buff) {
  if (!buff) return false;
  const key = String(buff.templateKey || '');
  if (key === FEIXUE_XUEXIU_KEY || key === FEIXUE_XUEXIU_TEAM_KEY) return true;
  if (FEIXUE_XUEXIU_LEGACY_SPLIT_KEYS.has(key)) return true;
  if (buff.stackSync === FEIXUE_XUEXIU_STACK_SYNC) return true;
  if (isFeixueXuexiuStackSyncBuff(buff)) return true;
  // 旧存档可能丢掉 templateKey / 源 id，只剩同名复合
  if (
    isCompositeBuff(buff) &&
    String(buff.name || '').trim() === '雪锈' &&
    (buff.effects || []).some((fx) => fx?.zone === 'generalCritDmg')
  ) {
    return true;
  }
  return false;
}

function stripFeixueBoundBuffsFromSpecialChar(target, memberIndex, rosterMember) {
  if (!target) return;
  const charId = String(rosterMember?.characterId || '');
  const allowPersonal = charId === FEIXUE_CHAR_ID;
  const allowTeam =
    typeof isFeixueXuexiuTeamRecipientCharId === 'function'
      ? isFeixueXuexiuTeamRecipientCharId(charId)
      : allowPersonal;
  if (allowPersonal && allowTeam) return;
  const shouldDrop = (b) => {
    if (!isFeixueBoundSpecialBuff(b)) return false;
    const key = String(b?.templateKey || '');
    const isTeamXuexiu =
      key === FEIXUE_XUEXIU_TEAM_KEY ||
      (!!b.teamSourceId && (key === FEIXUE_XUEXIU_TEAM_KEY || isFeixueXuexiuStackSyncBuff(b)));
    if (isTeamXuexiu) return !allowTeam;
    return !allowPersonal;
  };
  const drop = (target.buffs || []).filter(shouldDrop);
  if (!drop.length) return;
  drop.forEach((b) => {
    purgeMemberBuffReferences(target, b.id);
    if (memberIndex != null && memberIndex >= 0) {
      purgeSpecialSkillItemBuffReferences(b.id, memberIndex);
    }
  });
  target.buffs = (target.buffs || []).filter((b) => !shouldDrop(b));
}

function mirrorPersonalBuffPayload(memberBuff) {
  const payload = {
    category: memberBuff.category,
    name: memberBuff.name,
    mode: memberBuff.mode,
    value: memberBuff.value,
    perStack: memberBuff.perStack,
    maxStacks: memberBuff.maxStacks,
    damageType: memberBuff.damageType || '',
    effectType:
      memberBuff.damageType === '效应' ? normalizeBuffEffectType(memberBuff.effectType) : undefined,
    element: memberBuff.element || '',
    defenseKind:
      memberBuff.defenseKind || (DEFENSE_BUFF_CATS.has(memberBuff.category) ? 'pen' : ''),
    personalSourceId: memberBuff.id,
  };
  if (payload.effectType === undefined) delete payload.effectType;
  if (memberBuff.sourceTag) payload.sourceTag = memberBuff.sourceTag;
  if (memberBuff.templateKey) payload.templateKey = memberBuff.templateKey;
  if (memberBuff.sourceCharacterId) payload.sourceCharacterId = memberBuff.sourceCharacterId;
  if (memberBuff.stackSync) payload.stackSync = memberBuff.stackSync;
  if (typeof normalizeBuffGameText === 'function') {
    const gt = normalizeBuffGameText(memberBuff.gameText);
    if (gt) payload.gameText = gt;
  }
  if (isSystemConvergenceBuff(memberBuff) || isConvergenceBuffCategory(memberBuff.category)) {
    payload.convergenceVuln = Number.isFinite(Number(memberBuff.convergenceVuln))
      ? Number(memberBuff.convergenceVuln)
      : CONVERGENCE_DEFAULT_VULN;
  }
  if (Array.isArray(memberBuff.effects)) {
    payload.effects = memberBuff.effects.map((fx) => normalizeCompositeEffect({ ...fx, id: genId() }));
  }
  return payload;
}

function syncPersonalEffectBuffsToSpecialChar(memberIndex) {
  ensureSpecialSkillsState();
  const member = state.members[memberIndex];
  let target = state.specialSkills.characters[memberIndex];
  if (!member || !target) return;
  if (!Array.isArray(target.buffs)) target.buffs = [];
  if (!target.globalBuffActive) target.globalBuffActive = {};
  if (!target.globalBuffStacks) target.globalBuffStacks = {};

  // 先清掉非绯雪槽上的雪锈残留（含无 personalSourceId 的旧镜像）
  stripFeixueBoundBuffsFromSpecialChar(target, memberIndex, member);

  const personalSourceBuffs = (member.buffs || []).filter((b) => {
    if (!shouldSyncPersonalBuffToSpecial(b)) {
      // 仅绯雪槽同步个人【雪锈】暴伤复合
      if (
        String(member.characterId) === FEIXUE_CHAR_ID &&
        String(b?.templateKey || '') === FEIXUE_XUEXIU_KEY &&
        !b.teamSourceId &&
        !b.personalSourceId
      ) {
        return true;
      }
      return false;
    }
    return true;
  });
  const personalIds = new Set(personalSourceBuffs.map((b) => b.id));
  ensureExcludedPersonalBuffIds(target);
  target.excludedPersonalBuffIds = target.excludedPersonalBuffIds.filter((id) => personalIds.has(id));
  const excluded = new Set(target.excludedPersonalBuffIds);

  const orphans = target.buffs.filter((b) => {
    // 无来源标识的模板残留（旧版数据丢失去向）：角色库无匹配则清理
    if (!b.personalSourceId && !b.teamSourceId) {
      const looksTemplate =
        String(b.sourceTag || '') === CHAR_BUFF_TEMPLATE_SOURCE_TAG || !!String(b.templateKey || '');
      if (!looksTemplate) return false;
      if (typeof buffContentSignature === 'function') {
        const sig = buffContentSignature(b);
        return !(member.buffs || []).some((pb) => buffContentSignature(pb) === sig);
      }
      return true;
    }
    if (!b.personalSourceId || personalIds.has(b.personalSourceId)) return false;
    // 手动加入条目：来源 id 已不在（角色清空/武器更换/模态切换/模板重建 id 变化）时，
    // 按内容签名判断来源是否仍存在——存在则保留（重建换 id 不丢），不存在则视为残留清理
    if (b.manualSpecialAdd) {
      if (typeof buffContentSignature === 'function') {
        const sig = buffContentSignature(b);
        return !(member.buffs || []).some((pb) => buffContentSignature(pb) === sig);
      }
      return true;
    }
    return true;
  });
  const orphanIds = new Set(orphans.map((b) => b.id));
  // 先删除条目再清理引用：purge* 内部会触发 ensureSpecialSkillsState 重建角色对象，
  // 若先 purge 后删，会删到旧对象上，重建又把残留带回来
  target.buffs = target.buffs.filter((b) => !orphanIds.has(b.id));
  orphans.forEach((b) => {
    purgeMemberBuffReferences(target, b.id);
    purgeSpecialSkillItemBuffReferences(b.id, memberIndex);
  });
  target = state.specialSkills.characters[memberIndex];

  const badMirrors = (target?.buffs || []).filter((b) => {
    if (!b.personalSourceId) return false;
    if (b.manualSpecialAdd) return false;
    const source = (member.buffs || []).find((pb) => pb.id === b.personalSourceId);
    return !shouldSyncPersonalBuffToSpecial(source);
  });
  const badMirrorIds = new Set(badMirrors.map((b) => b.id));
  target.buffs = target.buffs.filter((b) => !badMirrorIds.has(b.id));
  badMirrors.forEach((b) => {
    purgeMemberBuffReferences(target, b.id);
    purgeSpecialSkillItemBuffReferences(b.id, memberIndex);
  });
  target = state.specialSkills.characters[memberIndex];

  personalSourceBuffs.forEach((memberBuff) => {
    if (excluded.has(memberBuff.id)) return;
    let mirror = target.buffs.find((b) => b.personalSourceId === memberBuff.id);
    const payload = mirrorPersonalBuffPayload(memberBuff);
    if (!mirror) {
      mirror = { id: genId(), ...payload };
    }
    const duplicates = target.buffs.filter((b) => isSameBuffSourceAsPersonal(b, memberBuff));
    duplicates.forEach((dup) => {
      remapMemberBuffReferences(target, dup.id, mirror.id, { specialCharIndex: memberIndex });
    });
    target.buffs = target.buffs.filter(
      (b) => !isSameBuffSourceAsPersonal(b, memberBuff) || b.personalSourceId === memberBuff.id
    );
    const existingMirror = target.buffs.find((b) => b.personalSourceId === memberBuff.id);
    if (!existingMirror) {
      target.buffs.push(mirror);
    } else {
      mirror = existingMirror;
      Object.assign(mirror, payload, { id: mirror.id });
    }
    if (isSystemConvergenceBuff(memberBuff)) {
      // 集谐层数/开关跟随队内角色，特殊技能侧只读同步
      target.globalBuffActive[mirror.id] =
        member.globalBuffActive?.[memberBuff.id] !== undefined
          ? !!member.globalBuffActive[memberBuff.id]
          : true;
      target.globalBuffStacks[mirror.id] = normalizeStackInput(
        member.globalBuffStacks?.[memberBuff.id] ?? 0
      );
    } else {
      if (target.globalBuffActive[mirror.id] === undefined) {
        const active = member.globalBuffActive?.[memberBuff.id];
        target.globalBuffActive[mirror.id] = active !== undefined ? active : true;
      }
      // 自动同步叠层（露帕荣光 / 声骸套装谐幅）：始终跟随来源层数；雪锈已改为各角色独立
      const stackAutoSync =
        typeof isAutoSyncedTeamStackBuff === 'function' &&
        isAutoSyncedTeamStackBuff(memberBuff);
      if (
        stackAutoSync ||
        (isStackBuff(memberBuff) && target.globalBuffStacks[mirror.id] === undefined)
      ) {
        target.globalBuffStacks[mirror.id] = normalizeStackInput(
          member.globalBuffStacks?.[memberBuff.id] ?? 0
        );
      }
    }
  });
  normalizeMemberBuffKeys(target);
}

function syncAllPersonalEffectBuffsToSpecial() {
  ensureSpecialSkillsState();
  state.specialSkills.characters.forEach((_, i) => syncPersonalEffectBuffsToSpecialChar(i));
  normalizeAllSpecialSkillItemBuffMaps();
}

/** 个人 Buff 是否已在特殊技能库：'manual' 右键手动加入；'auto' 自动同步镜像 */
function getPersonalBuffSpecialState(memberIndex, buffId) {
  const target = state.specialSkills?.characters?.[memberIndex];
  if (!target || !Array.isArray(target.buffs)) return null;
  const id = String(buffId || '');
  const found = target.buffs.find((b) => String(b.personalSourceId || '') === id);
  if (!found) return null;
  return found.manualSpecialAdd ? 'manual' : 'auto';
}

function isPersonalBuffInSpecialSkill(memberIndex, buffId) {
  return getPersonalBuffSpecialState(memberIndex, buffId) !== null;
}

/** 右键手动把个人 Buff 加入特殊技能计算（保留来源；同步清理时跳过 manualSpecialAdd） */
function addPersonalBuffToSpecialSkill(memberIndex, buffId) {
  if (!Number.isInteger(memberIndex) || memberIndex < 0) return false;
  ensureSpecialSkillsState();
  const member = state.members[memberIndex];
  const target = state.specialSkills.characters[memberIndex];
  if (!member || !target) return false;
  const source = (member.buffs || []).find((b) => b.id === buffId);
  if (!source) return false;
  if (getPersonalBuffSpecialState(memberIndex, buffId) === 'manual') return true;
  if (!Array.isArray(target.buffs)) target.buffs = [];
  if (!target.globalBuffActive) target.globalBuffActive = {};
  if (!target.globalBuffStacks) target.globalBuffStacks = {};
  const payload =
    typeof mirrorPersonalBuffPayload === 'function'
      ? mirrorPersonalBuffPayload(source)
      : { ...source };
  const entry = {
    id: genId(),
    ...payload,
    personalSourceId: String(source.id),
    manualSpecialAdd: true,
  };
  if (!entry.name) entry.name = source.name || 'Buff';
  target.buffs.push(entry);
  target.globalBuffActive[entry.id] = true;
  if (isStackBuff(source)) {
    target.globalBuffStacks[entry.id] = normalizeStackInput(
      member.globalBuffStacks?.[source.id] ?? 0
    );
  }
  if (typeof normalizeMemberBuffKeys === 'function') normalizeMemberBuffKeys(target);
  if (typeof scheduleSave === 'function') scheduleSave();
  return true;
}

/** 移出右键手动加入的条目（自动同步镜像由同步逻辑管理） */
function removePersonalBuffFromSpecialSkill(memberIndex, buffId) {
  if (!Number.isInteger(memberIndex) || memberIndex < 0) return false;
  ensureSpecialSkillsState();
  const target = state.specialSkills?.characters?.[memberIndex];
  if (!target || !Array.isArray(target.buffs)) return false;
  const id = String(buffId || '');
  const matches = target.buffs.filter(
    (b) => b.manualSpecialAdd && String(b.personalSourceId || '') === id
  );
  if (!matches.length) return false;
  const drop = new Set(matches.map((b) => b.id));
  target.buffs = target.buffs.filter((b) => !drop.has(b.id));
  matches.forEach((b) => {
    if (typeof purgeMemberBuffReferences === 'function') purgeMemberBuffReferences(target, b.id);
    if (typeof purgeSpecialSkillItemBuffReferences === 'function') {
      purgeSpecialSkillItemBuffReferences(b.id, memberIndex);
    }
  });
  if (typeof normalizeMemberBuffKeys === 'function') normalizeMemberBuffKeys(target);
  if (typeof scheduleSave === 'function') scheduleSave();
  return true;
}

function syncPersonalEffectBuffsAfterMemberChange(member) {
  if (!member || isSpecialView() || isTemplateBuffEditMode()) return;
  const idx = getMemberIndex(member);
  if (idx < 0) return;
  syncPersonalEffectBuffsToSpecialChar(idx);
  normalizeAllSpecialSkillItemBuffMaps();
}

function isSyncedBuffMirror(buff) {
  return !!(buff?.teamSourceId || buff?.personalSourceId);
}

function includeTeamBuffOnTarget(target, teamBuffSourceId) {
  if (!target || !teamBuffSourceId) return;
  const excluded = ensureExcludedTeamBuffIds(target);
  const idx = excluded.indexOf(teamBuffSourceId);
  if (idx >= 0) excluded.splice(idx, 1);
  const manual = ensureManuallyExcludedTeamBuffIds(target);
  const manualIdx = manual.indexOf(teamBuffSourceId);
  if (manualIdx >= 0) manual.splice(manualIdx, 1);
  const specialIdx = (state.specialSkills?.characters || []).indexOf(target);
  if (specialIdx >= 0) {
    syncTeamBuffsToMemberTarget(target, { specialCharIndex: specialIdx });
  } else {
    syncTeamBuffsToMemberTarget(target);
  }
  // 显式重新覆盖：强制打开该镜像勾选
  const mirror = (target.buffs || []).find((b) => b.teamSourceId === teamBuffSourceId);
  if (mirror) {
    if (!target.globalBuffActive) target.globalBuffActive = {};
    target.globalBuffActive[mirror.id] = true;
  }
  // 刷新运行时转模（达妮娅谐幅 / 穗穗延奏2·3 / 守岸人星域 / 莫宁2链 / 仇远万钧等）
  if (typeof refreshRuntimeConvertedTeamBuffs === 'function') {
    refreshRuntimeConvertedTeamBuffs();
  } else if (typeof syncDaniaInnateOffsetHarmonyAmp === 'function') {
    syncDaniaInnateOffsetHarmonyAmp(target);
  }
  // 仅把「自动同步层数」类 Buff 从共享库写回；手工层数以各角色为准，禁止整队重置
  if (typeof syncTargetTeamMirrorStacksFromShared === 'function') {
    syncTargetTeamMirrorStacksFromShared(target);
  }
}

/** 成员级全队 Buff「覆盖/勾选」变更后，同步到该成员所有轮次快照：
 *  1) 已排除的镜像从各轮 buffs 移除（避免切轮回弹）；
 *  2) 镜像勾选状态按当前成员 globalBuffActive 同步（新轮次直接生效）。
 *  仅处理 teamSourceId 镜像，个人 Buff 仍按轮独立。 */
function syncMemberTeamBuffStateToRounds(member) {
  if (!member?.cycleConfig?.enabled || !Array.isArray(member.cycleConfig.rounds)) return;
  // 新覆盖的镜像须先建入各轮，再同步成员级开关；保留原轮次及技能层数。
  syncTeamBuffsIntoMemberCycleRounds(member);
  const excluded = new Set((member.excludedTeamBuffIds || []).map(String));
  const liveMirrors = new Map();
  (member.buffs || []).forEach((b) => {
    if (b?.teamSourceId) liveMirrors.set(String(b.teamSourceId), b);
  });
  const act = member.globalBuffActive || {};
  member.cycleConfig.rounds.forEach((round) => {
    if (!Array.isArray(round.buffs)) return;
    if (!round.globalBuffActive) round.globalBuffActive = {};
    const kept = [];
    round.buffs.forEach((b) => {
      const srcId = b?.teamSourceId ? String(b.teamSourceId) : '';
      if (!srcId) { kept.push(b); return; }
      if (excluded.has(srcId)) {
        delete round.globalBuffActive[b.id];
        if (round.globalBuffStacks) delete round.globalBuffStacks[b.id];
        return;
      }
      const live = liveMirrors.get(srcId);
      if (live && act[live.id] !== undefined) {
        round.globalBuffActive[b.id] = !!act[live.id];
      }
      kept.push(b);
    });
    round.buffs = kept;
  });
}

function transferBoolMapEntry(map, fromId, toId) {
  if (!map || fromId === toId || map[fromId] === undefined) return;
  // 显式 false（取消勾选）优先写入，避免合并镜像时把取消勾选丢掉导致「又勾上」
  if (map[toId] === undefined || map[fromId] === false) {
    map[toId] = map[fromId];
  }
  delete map[fromId];
}

function transferStackMapEntry(map, fromId, toId) {
  if (!map || fromId === toId || map[fromId] === undefined) return;
  const fromVal = normalizeStackInput(map[fromId], fromId);
  if (map[toId] === undefined) {
    map[toId] = fromVal;
  } else if (normalizeStackInput(map[toId], toId) === 0 && fromVal > 0) {
    // 新 id 已被误写成 0 时，用旧层数覆盖（刷新重套常见）
    map[toId] = fromVal;
  }
  delete map[fromId];
}

/** 全队镜像合并本地同名 Buff 时，把旧 id 的勾选与叠层迁移到新 id */
function remapMemberBuffReferences(target, fromId, toId, opts) {
  if (!target || !fromId || !toId || fromId === toId) return;

  transferBoolMapEntry(target.globalBuffActive, fromId, toId);
  transferStackMapEntry(target.globalBuffStacks, fromId, toId);

  (target.rotationCatalog || []).forEach((c) => {
    transferStackMapEntry(c.stackLayers, fromId, toId);
  });

  if (target.cycleConfig?.rounds) {
    const activeIdx = readActiveCycleRoundIndex(target);
    const allRounds = !!opts?.allRounds;
    target.cycleConfig.rounds.forEach((round, ri) => {
      if (!allRounds && ri !== activeIdx) return;
      Object.values(round.catalogStacks || {}).forEach((layers) => {
        transferStackMapEntry(layers, fromId, toId);
      });
      transferBoolMapEntry(round.globalBuffActive, fromId, toId);
      transferStackMapEntry(round.globalBuffStacks, fromId, toId);
      (round.buffs || []).forEach((b) => {
        if (b && b.id === fromId) b.id = toId;
      });
      if (ri !== activeIdx && round.phases) {
        (round.phases || []).forEach((p) => {
          transferBoolMapEntry(p.buffActive, fromId, toId);
          transferStackMapEntry(p.buffStacks, fromId, toId);
          (p.skills || []).forEach((s) => {
            transferBoolMapEntry(s.buffActive, fromId, toId);
            transferStackMapEntry(s.buffStacks, fromId, toId);
            transferBoolMapEntry(s.frozenBuffActive, fromId, toId);
            transferStackMapEntry(s.frozenBuffStacks, fromId, toId);
            (s.hits || []).forEach((h) => {
              transferBoolMapEntry(h.buffActive, fromId, toId);
              transferStackMapEntry(h.buffStacks, fromId, toId);
              transferBoolMapEntry(h.frozenBuffActive, fromId, toId);
              transferStackMapEntry(h.frozenBuffStacks, fromId, toId);
            });
          });
        });
      }
    });
  }

  (target.phases || []).forEach((p) => {
    transferBoolMapEntry(p.buffActive, fromId, toId);
    transferStackMapEntry(p.buffStacks, fromId, toId);
    (p.skills || []).forEach((s) => {
      transferBoolMapEntry(s.buffActive, fromId, toId);
      transferStackMapEntry(s.buffStacks, fromId, toId);
      transferBoolMapEntry(s.frozenBuffActive, fromId, toId);
      transferStackMapEntry(s.frozenBuffStacks, fromId, toId);
      (s.hits || []).forEach((h) => {
        transferBoolMapEntry(h.buffActive, fromId, toId);
        transferStackMapEntry(h.buffStacks, fromId, toId);
        transferBoolMapEntry(h.frozenBuffActive, fromId, toId);
        transferStackMapEntry(h.frozenBuffStacks, fromId, toId);
      });
    });
  });

  const specialCharIndex = opts?.specialCharIndex;
  if (Number.isFinite(specialCharIndex) && specialCharIndex >= 0) {
    ensureSpecialSkillsState();
    (state.specialSkills?.items || []).forEach((item) => {
      if (getSpecialSkillRosterIndex(item) !== specialCharIndex) return;
      transferBoolMapEntry(item.buffActive, fromId, toId);
      transferStackMapEntry(item.buffStacks, fromId, toId);
      transferBoolMapEntry(item.frozenBuffActive, fromId, toId);
      transferStackMapEntry(item.frozenBuffStacks, fromId, toId);
    });
  }
}

function purgeSpecialSkillItemBuffReferences(buffId, specialCharIndex) {
  if (!buffId || !Number.isFinite(specialCharIndex) || specialCharIndex < 0) return;
  ensureSpecialSkillsState();
  (state.specialSkills?.items || []).forEach((item) => {
    if (getSpecialSkillRosterIndex(item) !== specialCharIndex) return;
    if (item.buffActive) delete item.buffActive[buffId];
    if (item.buffStacks) delete item.buffStacks[buffId];
    if (item.frozenBuffActive) delete item.frozenBuffActive[buffId];
    if (item.frozenBuffStacks) delete item.frozenBuffStacks[buffId];
  });
}

function purgePhasesBuffReferences(phases, buffId) {
  (phases || []).forEach((p) => {
    if (p.buffActive) delete p.buffActive[buffId];
    if (p.buffStacks) delete p.buffStacks[buffId];
    (p.skills || []).forEach((s) => {
      if (s.buffActive) delete s.buffActive[buffId];
      if (s.buffStacks) delete s.buffStacks[buffId];
      if (s.frozenBuffActive) delete s.frozenBuffActive[buffId];
      if (s.frozenBuffStacks) delete s.frozenBuffStacks[buffId];
      (s.hits || []).forEach((h) => {
        if (h.buffActive) delete h.buffActive[buffId];
        if (h.buffStacks) delete h.buffStacks[buffId];
        if (h.frozenBuffActive) delete h.frozenBuffActive[buffId];
        if (h.frozenBuffStacks) delete h.frozenBuffStacks[buffId];
      });
    });
  });
}

function purgeMemberBuffReferences(member, buffId, opts) {
  if (!member) return;
  const allRounds = !!opts?.allRounds;
  if (member.globalBuffActive) delete member.globalBuffActive[buffId];
  if (member.globalBuffStacks) delete member.globalBuffStacks[buffId];
  (member.rotationCatalog || []).forEach((c) => {
    if (c.stackLayers) delete c.stackLayers[buffId];
  });
  if (member.cycleConfig?.rounds) {
    const activeIdx = readActiveCycleRoundIndex(member);
    member.cycleConfig.rounds.forEach((round, ri) => {
      if (!allRounds && ri !== activeIdx) return;
      Object.keys(round.catalogStacks || {}).forEach((catalogId) => {
        if (round.catalogStacks[catalogId]) delete round.catalogStacks[catalogId][buffId];
      });
      if (round.globalBuffActive) delete round.globalBuffActive[buffId];
      if (round.globalBuffStacks) delete round.globalBuffStacks[buffId];
      if (Array.isArray(round.buffs)) {
        round.buffs = round.buffs.filter((b) => b.id !== buffId);
      }
      if (ri !== activeIdx && round.phases) {
        purgePhasesBuffReferences(round.phases, buffId);
      }
    });
  }
  purgePhasesBuffReferences(member.phases, buffId);
}

function syncTeamBuffsToMemberTarget(target, opts) {
  if (!target) return;
  if (!Array.isArray(target.buffs)) target.buffs = [];
  if (!target.globalBuffActive) target.globalBuffActive = {};
  if (!target.globalBuffStacks) target.globalBuffStacks = {};
  const shared = ensureTeamSharedBuffs();
  const teamIds = new Set(shared.buffs.map((b) => b.id));
  ensureExcludedTeamBuffIds(target);
  target.excludedTeamBuffIds = target.excludedTeamBuffIds.filter((id) => teamIds.has(id));
  const manualSet = new Set(ensureManuallyExcludedTeamBuffIds(target));
  // 易伤/穿防等默认同步乘区：不因「对来源不生效」或旧排除而丢掉（雪锈 / 洛瑟菈·全队·霜渐 除外，尊重手动取消覆盖）
  target.excludedTeamBuffIds = target.excludedTeamBuffIds.filter((id) => {
    const tb = shared.buffs.find((b) => b.id === id);
    if (!tb) return false;
    if (
      typeof isSpecialDefaultSyncBuffSource === 'function' &&
      isSpecialDefaultSyncBuffSource(tb) &&
      !(typeof isUserToggleableTeamSyncBuff === 'function' && isUserToggleableTeamSyncBuff(tb))
    ) {
      return manualSet.has(id);
    }
    return true;
  });
  const isSpecialTarget = Number.isFinite(opts?.specialCharIndex);
  const specialIdx = isSpecialTarget ? opts.specialCharIndex : undefined;
  // 特殊技能库：不继承「对来源不生效」
  if (isSpecialTarget) {
    target.excludedTeamBuffIds = target.excludedTeamBuffIds.filter((id) => {
      const tb = shared.buffs.find((b) => b.id === id);
      if (!tb) return false;
      if (tb.excludeSource && getTeamBuffSourceMemberIndex(tb) === specialIdx) {
        return manualSet.has(id);
      }
      return true;
    });
  }
  const excluded = new Set(target.excludedTeamBuffIds);
  // 武器/声骸全队 Buff 会短暂从 shared 摘掉再按稳定 id 加回。
  // 若此处 purge 镜像引用，会清掉技能时间线 / 轮次 catalogStacks 的叠层覆盖。
  // 真正删除全队 Buff 应走 deleteTeamSharedBuff（会显式 purge）。
  const orphans = target.buffs.filter((b) => b.teamSourceId && !teamIds.has(b.teamSourceId));
  orphans.forEach((b) => {
    if (target.globalBuffActive) delete target.globalBuffActive[b.id];
  });
  target.buffs = target.buffs.filter((b) => !b.teamSourceId || teamIds.has(b.teamSourceId));

  if (isSpecialTarget) {
    const badMirrors = target.buffs.filter((b) => {
      if (!b.teamSourceId) return false;
      const source = shared.buffs.find((tb) => tb.id === b.teamSourceId);
      return !isSpecialTeamBuffMirror(source, specialIdx);
    });
    badMirrors.forEach((b) => {
      purgeMemberBuffReferences(target, b.id, opts);
      purgeSpecialSkillItemBuffReferences(b.id, opts.specialCharIndex);
    });
    target.buffs = target.buffs.filter((b) => {
      if (!b.teamSourceId) return true;
      const source = shared.buffs.find((tb) => tb.id === b.teamSourceId);
      return isSpecialTeamBuffMirror(source, specialIdx);
    });
  }

  shared.buffs.forEach((teamBuff) => {
    if (isSpecialTarget && !isSpecialTeamBuffMirror(teamBuff, specialIdx)) return;
    // 全队易伤/穿防：来源角色本人也必须吃到（特殊库与队内均不因 excludeSource 排除）
    const isDefaultSync =
      typeof isSpecialDefaultSyncBuffSource === 'function' &&
      isSpecialDefaultSyncBuffSource(teamBuff);
    if ((teamBuff.excludeSource || isNextMemberOnlyBuff(teamBuff)) && !isDefaultSync && !isSpecialTarget && !(typeof isRococoFlatAtkBuff === 'function' && isRococoFlatAtkBuff(teamBuff))) {
      const srcIdx = getTeamBuffSourceMemberIndex(teamBuff);
      const targetIdx = getMemberIndex(target);
      if (srcIdx != null && targetIdx === srcIdx) {
        const excl = ensureExcludedTeamBuffIds(target);
        if (!excl.includes(teamBuff.id)) excl.push(teamBuff.id);
        excluded.add(teamBuff.id);
        if (isNextMemberOnlyBuff(teamBuff)) {
          const stale = (target.buffs || []).filter((b) => b.teamSourceId === teamBuff.id);
          stale.forEach((b) => purgeMemberBuffReferences(target, b.id, opts));
          target.buffs = (target.buffs || []).filter((b) => b.teamSourceId !== teamBuff.id);
        }
      }
    }
    // Buff 级 / 全效果限定角色：非名单成员强制不分配（矩阵显示 ×），并清掉已有镜像
    if (!isSpecialTarget) {
      const onlyIds = getTeamBuffOnlyCharacterIds(teamBuff);
      if (onlyIds.length) {
        const charId = String(target?.characterId || '').trim();
        if (!charId || !onlyIds.includes(charId)) {
          const excl = ensureExcludedTeamBuffIds(target);
          if (!excl.includes(teamBuff.id)) excl.push(teamBuff.id);
          excluded.add(teamBuff.id);
          const stale = (target.buffs || []).filter((b) => b.teamSourceId === teamBuff.id);
          stale.forEach((b) => purgeMemberBuffReferences(target, b.id, opts));
          target.buffs = (target.buffs || []).filter((b) => b.teamSourceId !== teamBuff.id);
        }
      }
    }
    // 特殊库：默认同步/效应类全队 Buff 即使仍在排除列表也强制写入镜像
    if (
      excluded.has(teamBuff.id) &&
      !(
        isSpecialTarget &&
        typeof isSpecialEffectBuffSource === 'function' &&
        isSpecialEffectBuffSource(teamBuff) &&
        !(typeof isUserToggleableTeamSyncBuff === 'function' && isUserToggleableTeamSyncBuff(teamBuff))
      )
    ) {
      // PROBE_FIX_EXCLUSION_CLOSURE：排除判据必须闭环 —— 「不新建镜像」之外还必须「删掉已存在的镜像」。
      // 原来只 return；而伤害引擎只读 member.buffs / round.buffs，于是 excludedTeamBuffIds 形同虚设：
      // 锚点/快照里一旦带着旧镜像，排除就完全不生效（实测 MC-9DTQL7：⑤ 排除表含目标条、镜像仍在，
      // 每轮多 25% 冷凝增伤，14.77w → 15.37w）。且全量重建消不掉，必须在此出口删除。
      // 本出口同时覆盖成员级与轮次级：syncTeamBuffsIntoMemberCycleRounds 用 proxy 走的就是这里。
      const staleMirrors = (target.buffs || []).filter((b) => b.teamSourceId === teamBuff.id);
      staleMirrors.forEach((b) => purgeMemberBuffReferences(target, b.id, opts));
      target.buffs = (target.buffs || []).filter((b) => b.teamSourceId !== teamBuff.id);
      return;
    }
    const stableId = makeTeamMirrorBuffId(teamBuff.id);
    let mirror = target.buffs.find((b) => b.teamSourceId === teamBuff.id);
    const payload = mirrorTeamBuffPayload(teamBuff);
    if (isTongzouSharedGainBuff(teamBuff)) delete payload.stackSync;
    if (!mirror) {
      mirror = { id: stableId, ...payload };
    } else if (mirror.id !== stableId) {
      remapMemberBuffReferences(target, mirror.id, stableId, opts);
      mirror.id = stableId;
    }
    const duplicates = target.buffs.filter((b) => isSameBuffSourceAsTeam(b, teamBuff));
    duplicates.forEach((dup) => {
      remapMemberBuffReferences(target, dup.id, mirror.id, opts);
    });
    target.buffs = target.buffs.filter((b) => !isSameBuffSourceAsTeam(b, teamBuff));
    const existingMirror = target.buffs.find((b) => b.teamSourceId === teamBuff.id);
    if (!existingMirror) {
      target.buffs.push(mirror);
    } else {
      mirror = existingMirror;
      if (mirror.id !== stableId) {
        remapMemberBuffReferences(target, mirror.id, stableId, opts);
        mirror.id = stableId;
      }
      Object.assign(mirror, payload, { id: stableId });
    }
    if (target.globalBuffActive[mirror.id] === undefined) {
      const active = shared.globalBuffActive[teamBuff.id];
      target.globalBuffActive[mirror.id] = active !== undefined ? active : true;
    }
    // 特殊库中的全队易伤/穿防：若曾被误关，随同步重新打开（避免来源槽「选露西不生效」）
    if (
      isSpecialTarget &&
      isDefaultSync &&
      !(typeof isUserToggleableTeamSyncBuff === 'function' && isUserToggleableTeamSyncBuff(teamBuff)) &&
      target.globalBuffActive[mirror.id] === false
    ) {
      const sharedOn = shared.globalBuffActive[teamBuff.id];
      if (sharedOn !== false) target.globalBuffActive[mirror.id] = true;
    }
    // 自动同步层数仍以共享库为准；手工层数优先保留角色侧（含稳定 tm_*），禁止被 shared 默认 0 冲掉
    if (isStackBuff(teamBuff)) {
      const sharedTongzou = isTongzouSharedGainBuff(teamBuff);
      const autoStack = !sharedTongzou && isAutoSyncedTeamStackBuff(teamBuff);
      const stableId = makeTeamMirrorBuffId(teamBuff.id);
      const existing =
        target.globalBuffStacks[mirror.id] !== undefined
          ? target.globalBuffStacks[mirror.id]
          : target.globalBuffStacks[stableId];
      if (sharedTongzou) {
        target.globalBuffStacks[mirror.id] = normalizeStackInput(existing ?? 0);
        target.globalBuffStacks[stableId] = target.globalBuffStacks[mirror.id];
      } else if (autoStack) {
        target.globalBuffStacks[mirror.id] = normalizeStackInput(
          shared.globalBuffStacks[teamBuff.id] ?? 0
        );
      } else if (existing !== undefined && existing !== '') {
        const kept = normalizeStackInput(existing);
        target.globalBuffStacks[mirror.id] = kept;
        target.globalBuffStacks[stableId] = kept;
        if (!isTongzouLayerLinkedBuff(teamBuff) && shared.globalBuffStacks[teamBuff.id] === undefined) {
          shared.globalBuffStacks[teamBuff.id] = kept;
        }
      } else {
        const seed = isTongzouLayerLinkedBuff(teamBuff)
          ? getTongzouLinkedStacks(teamBuff, target)
          : shared.globalBuffStacks[teamBuff.id] ?? 0;
        target.globalBuffStacks[mirror.id] = normalizeStackInput(seed);
      }
    }
  });
  normalizeMemberBuffKeys(target);
  // 镜像 payload 会把达妮娅谐幅写回共享库的 0；队内成员需立刻按偏谐效率重算
  if (
    typeof syncDaniaInnateOffsetHarmonyAmp === 'function' &&
    Array.isArray(state.members) &&
    state.members.includes(target)
  ) {
    syncDaniaInnateOffsetHarmonyAmp(target);
  }
}

function syncTeamBuffsIntoMemberCycleRounds(member) {
  if (!member?.cycleConfig?.enabled || !Array.isArray(member.cycleConfig.rounds)) return;
  const activeIdx = readActiveCycleRoundIndex(member);
  member.cycleConfig.rounds.forEach((round, ri) => {
    // 各轮只对账全队镜像，禁止用 member 实况整轮覆盖（否则加载其它轮时会串轮）
    if (!Array.isArray(round.buffs)) {
      if (ri === activeIdx) seedRoundBuffsFromMember(round, member);
      else {
        round.buffs = [];
        round.globalBuffActive = {};
        round.globalBuffStacks = {};
      }
    }
    const proxy = {
      characterId: member.characterId,
      buffs: round.buffs,
      globalBuffActive: round.globalBuffActive || {},
      globalBuffStacks: round.globalBuffStacks || {},
      excludedTeamBuffIds: [...(member.excludedTeamBuffIds || [])],
      manuallyExcludedTeamBuffIds: [...(member.manuallyExcludedTeamBuffIds || [])],
      phases: round.phases || [],
      rotationCatalog: round.rotationCatalog || [],
    };
    syncTeamBuffsToMemberTarget(proxy);
    round.buffs = proxy.buffs;
    round.globalBuffActive = proxy.globalBuffActive;
    round.globalBuffStacks = proxy.globalBuffStacks;
  });
}

function syncTeamBuffsToMembers() {
  const shared = ensureTeamSharedBuffs();
  syncSuomingC6GainBoost(shared);
  reconcileTongzouSharedGain();
  // 全队同步前先校正成员模态状态：修复旧存档 combatMode 与 convergenceMode 不一致
  // （如 combatMode=聚爆 但 convergenceMode 仍为 true，导致「集谐模态」系统 Buff 残留）
  (state.members || []).forEach((m) => {
    if (!m || typeof isConvergenceLikeCombatMode !== 'function') return;
    const desired = isConvergenceLikeCombatMode(m.combatMode);
    if (!!m.convergenceMode !== desired && typeof ensureConvergenceModeBuff === 'function') {
      m.convergenceMode = desired;
      ensureConvergenceModeBuff(m);
    }
  });
  // 清理空槽位残留的全队 Buff：清空角色后共享库未清的旧数据，加载/同步时自动消失
  (state.members || []).forEach((m, i) => {
    if (!m || m.characterId) return;
    const shared0 = ensureTeamSharedBuffs();
    (shared0.buffs || [])
      .filter(
        (b) =>
          typeof getTeamBuffSourceMemberIndex === 'function' &&
          getTeamBuffSourceMemberIndex(b) === i
      )
      .slice()
      .forEach((b) => deleteTeamSharedBuff(b.id));
  });
  // 空槽位对应特殊技能角色整体重置（含之前右键手动加入的条目），避免旧角色 Buff 残留
  if (typeof createSpecialCharacterDefaults === 'function' && state.specialSkills?.characters) {
    (state.members || []).forEach((m, i) => {
      if (!m || m.characterId || !state.specialSkills.characters[i]) return;
      state.specialSkills.characters[i] = createSpecialCharacterDefaults(i);
    });
  }
  // 校验武器全队 Buff：来源槽位当前未装备该武器时清理（清空/换装残留，如旧角色武器被动）
  (state.members || []).forEach((m, i) => {
    if (!m) return;
    const curWeaponId = String(m.weaponSelection?.id || '');
    const sharedW = ensureTeamSharedBuffs();
    (sharedW.buffs || [])
      .filter((b) => {
        if (typeof isWeaponTeamGeneratedBuff !== 'function' || !isWeaponTeamGeneratedBuff(b)) return false;
        if (typeof getTeamBuffSourceMemberIndex !== 'function' || getTeamBuffSourceMemberIndex(b) !== i) return false;
        if (!m.characterId) return true;
        const buffWeaponId = String(
          b.weaponId || (typeof resolveWeaponIdFromBuff === 'function' ? resolveWeaponIdFromBuff(b) : '') || ''
        );
        return !!buffWeaponId && buffWeaponId !== curWeaponId;
      })
      .slice()
      .forEach((b) => deleteTeamSharedBuff(b.id));
  });
  if (typeof migrateAmisOutroSharedBuffs === 'function') {
    migrateAmisOutroSharedBuffs();
  }
  if (typeof migrateChangliOutroSharedBuffs === 'function') {
    migrateChangliOutroSharedBuffs();
  }
  if (typeof purgeBranchPanelDuplicateTalentBuffs === 'function') {
    (state.members || []).forEach((m) => purgeBranchPanelDuplicateTalentBuffs(m));
  } else if (typeof purgeXiangliYaoLegacyDuplicateTalentBuffs === 'function') {
    (state.members || []).forEach((m) => purgeXiangliYaoLegacyDuplicateTalentBuffs(m));
  }
  if (typeof dedupeDaniaInnateOffsetHarmonyAmpShared === 'function') {
    dedupeDaniaInnateOffsetHarmonyAmpShared();
  }
  if (typeof dedupeMoningOffsetHarmonyEffShared === 'function') {
    dedupeMoningOffsetHarmonyEffShared();
  }
  (shared.buffs || []).forEach((b) => {
    if (isYunoBlessingBuff(b)) ensureYunoBlessingEffects(b);
    if (typeof isAmisOutroBuff === 'function' && isAmisOutroBuff(b)) ensureAmisOutroEffects(b);
    if (typeof isDaniaOutroBuff === 'function' && isDaniaOutroBuff(b)) patchDaniaOutroBuff(b);
    if (String(b?.templateKey || '') === FEIXUE_XUEXIU_TEAM_KEY) {
      b.onlyCharacterIds = [...FEIXUE_XUEXIU_TEAM_ONLY_CHAR_IDS];
    }
    if (
      typeof isCartethyiaXianhuaShenquanBuff === 'function' &&
      isCartethyiaXianhuaShenquanBuff(b)
    ) {
      b.templateKey = CARTETHYIA_XIANHUA_SHENQUAN_KEY;
      b.onlyCharacterIds = [CARTETHYIA_CHAR_ID];
      b.category = 'typeDeep';
      b.damageType = '效应';
      b.effectType = '风蚀';
      if (!Number.isFinite(Number(b.value)) || Number(b.value) <= 0) {
        b.value = CARTETHYIA_XIANHUA_SHENQUAN_PCT;
      }
    }
    if (
      typeof isXiakongOutroWindErosionBuff === 'function' &&
      isXiakongOutroWindErosionBuff(b)
    ) {
      b.templateKey = XIAKONG_OUTRO_WIND_EROSION_KEY;
      b.onlyCharacterIds = [CARTETHYIA_CHAR_ID];
      b.category = 'typeDeep';
      b.damageType = '效应';
      b.effectType = '风蚀';
      if (!Number.isFinite(Number(b.value)) || Number(b.value) <= 0) {
        b.value = XIAKONG_OUTRO_WIND_EROSION_PCT;
      }
    }
    if (
      typeof isSigrikaC4TeamAtkBuff === 'function' &&
      isSigrikaC4TeamAtkBuff(b)
    ) {
      renameSigrikaC4TeamAtkBuff(b, { runtime: true });
    }
    if (String(b?.templateKey || '') === SUISUI_CONSUME_XUYAN_KEY) {
      b.onlyCharacterIds = [...SUISUI_CONSUME_XUYAN_ONLY_CHAR_IDS];
      b.excludeSource = true;
    }
    if (isDaniaInnateOffsetHarmonyAmpBuff(b)) {
      // 共享库条目只保留结构；各角色镜像 = 基础10 + 自身偏谐效率转化
      b.mode = 'fixed';
      b.perStack = 0;
      b.name = '达妮娅·固有';
      b.templateKey = DANIA_INNATE_OFFSET_HARMONY_AMP_KEY;
      b._daniaOffsetHarmonyHint =
        `基础${DANIA_INNATE_BASE_HARMONY_AMP}点 + 按各覆盖角色【偏谐值累积效率】转化（超过100%时每满10%+8，转化上限${DANIA_INNATE_OFFSET_HARMONY_AMP_CAP}）`;
    }
  });
  state.members.forEach((m) => {
    syncTeamBuffsToMemberTarget(m);
    syncTeamBuffsIntoMemberCycleRounds(m);
    if (__deferMemberRebind) __deferMemberRebindSet.add(m); else rebindMemberBuffCoverageMaps(m); // PROBE_FIX_DEFER_MEMBER_REBIND
    syncDaniaInnateOffsetHarmonyAmp(m);
  });
  if (typeof syncMoningOffsetHarmonyEffToAllPanels === 'function') {
    syncMoningOffsetHarmonyEffToAllPanels();
  }
  if (typeof syncRococoFlatAtkToAllPanels === 'function') {
    syncRococoFlatAtkToAllPanels();
  }
  state.members.forEach((m) => {
    // 面板偏谐效率可能刚被覆盖勾选改写，再刷一次达妮娅谐幅
    syncDaniaInnateOffsetHarmonyAmp(m);
  });
  if (typeof syncAllDaniaOutroDeep === 'function') syncAllDaniaOutroDeep();
  ensureSpecialSkillsState();
  state.specialSkills.characters.forEach((c, i) => {
    dedupeSpecialCharacterDefenseBuffList(c);
    syncTeamBuffsToMemberTarget(c, { specialCharIndex: i });
    syncPersonalEffectBuffsToSpecialChar(i);
    syncSpecialCharHarmonyBreakAmpFromRoster(i, c);
  });
  syncTongzouLinkedStacksToMembers();
  normalizeAllSpecialSkillItemBuffMaps();
}

/** 6 链已并入同奏本体；清除旧方案里独立的易伤 Buff，防止重复计算。 */
function syncSuomingC6GainBoost(shared = ensureTeamSharedBuffs()) {
  (shared.buffs || []).filter((b) => b?.templateKey === 'suoming_c6_gain_boost')
    .forEach((b) => deleteTeamSharedBuff(b.id));
}

function deleteTeamSharedBuff(teamBuffId) {
  const shared = ensureTeamSharedBuffs();
  shared.buffs = shared.buffs.filter((b) => b.id !== teamBuffId);
  invalidateSharedBuffsCache();
  delete shared.globalBuffActive[teamBuffId];
  delete shared.globalBuffStacks[teamBuffId];
  state.members.forEach((member) => {
    const mirrors = new Set();
    (member.buffs || [])
      .filter((b) => b.teamSourceId === teamBuffId)
      .forEach((b) => mirrors.add(b.id));
    (member.cycleConfig?.rounds || []).forEach((round) => {
      (round.buffs || [])
        .filter((b) => b.teamSourceId === teamBuffId)
        .forEach((b) => mirrors.add(b.id));
    });
    mirrors.forEach((id) => {
      member.buffs = (member.buffs || []).filter((b) => b.id !== id);
      purgeMemberBuffReferences(member, id, { allRounds: true });
    });
  });
  ensureSpecialSkillsState();
  state.specialSkills.characters.forEach((c, i) => {
    const mirror = c.buffs.find((b) => b.teamSourceId === teamBuffId);
    if (!mirror) return;
    c.buffs = c.buffs.filter((b) => b.id !== mirror.id);
    purgeMemberBuffReferences(c, mirror.id);
    purgeSpecialSkillItemBuffReferences(mirror.id, i);
  });
}

function renderCompositeZoneOptions(selected) {
  return COMPOSITE_EFFECT_ZONES.map(
    (zone) =>
      `<option value="${zone}" ${selected === zone ? 'selected' : ''}>${BUFF_CATS[zone]?.label || zone}</option>`
  ).join('');
}

function renderCompositeBuffEditor(b) {
  if (isAmisModeBuff(b)) {
    const effect = (b.effects || [])[0];
    const zone = BUFF_CATS[effect?.zone]?.label || effect?.zone || '加深';
    const skillHint =
      effect?.skillScope === 'names' && effect.skillNames?.length
        ? effect.skillNames[0]
        : '指定技能';
    const val = Number(effect?.value) || 0;
    return `
          <div class="buff-item composite-buff-editor" data-buff-row="${b.id}">
            <div class="composite-buff-main">
              <input type="text" value="${escapeHtml(formatBuffDisplayName(b) || b.name || '固有2')}" readonly title="爱弥斯固有，随战斗模态同步" />
              <span class="hint">${escapeHtml(zone)} ${val}% · ${escapeHtml(skillHint)}</span>
              <button class="btn sm danger" data-del-buff="${b.id}" disabled title="角色固有，不可删除">删</button>
            </div>
            <p class="hint composite-hint">爱弥斯固有2（随震谐/聚爆模态自动同步，数值不可改）。悬停 Buff 名可查看游戏原文。</p>
          </div>`;
  }
  if (isMoningCriticalProtocolErBuff(b)) {
    const rateFx = (b.effects || []).find(
      (fx) => String(fx?.effectKey || '') === MONING_CRITICAL_PROTOCOL_CRIT_RATE_EFFECT_KEY
    );
    const dmgFx = (b.effects || []).find(
      (fx) => String(fx?.effectKey || '') === MONING_CRITICAL_PROTOCOL_CRIT_DMG_EFFECT_KEY
    );
    const rate = Number(rateFx?.value) || 0;
    const dmg = Number(dmgFx?.value) || 0;
    const hint = b._moningCriticalProtocolHint
      ? escapeHtml(b._moningCriticalProtocolHint)
      : `共鸣效率超额转模：暴击+${rate.toFixed(1)}% / 暴伤+${dmg.toFixed(1)}%（仅【临界协议】）`;
    return `
          <div class="buff-item composite-buff-editor" data-buff-row="${b.id}">
            <div class="composite-buff-main">
              <input type="text" value="${escapeHtml(formatBuffDisplayName(b) || b.name || '临界协议·共鸣效率')}" readonly title="随共鸣效率面板同步，不可手改" />
              <span class="hint">暴击 ${formatBuffPct(rate)} · 暴伤 ${formatBuffPct(dmg)} · 临界协议</span>
              <button class="btn sm danger" data-del-buff="${b.id}" disabled title="角色固有，不可删除">删</button>
            </div>
            <p class="hint composite-hint">${hint}</p>
          </div>`;
  }
  if (isJingranMinghuoBuff(b)) {
    const jiepoFx = (b.effects || []).find(
      (fx) => String(fx?.effectKey || '') === JINGRAN_MINGHUO_JIEPO_EFFECT_KEY
    );
    const tagangFx = (b.effects || []).find(
      (fx) => String(fx?.effectKey || '') === JINGRAN_MINGHUO_TAGANG_EFFECT_KEY
    );
    const jiepo = Number(jiepoFx?.value) || 0;
    const tagang = Number(tagangFx?.value) || 0;
    const hint = b._jingranMinghuoHint
      ? escapeHtml(b._jingranMinghuoHint)
      : `每${JINGRAN_HP_FLAT_ATK_HP_CHUNK}生命：劫魄倍率增加+${JINGRAN_MINGHUO_JIEPO_PER_CHUNK}%、踏罡+${JINGRAN_MINGHUO_TAGANG_PER_CHUNK}%（最多计入${JINGRAN_MINGHUO_HP_CAP}生命）`;
    return `
          <div class="buff-item composite-buff-editor" data-buff-row="${b.id}">
            <div class="composite-buff-main">
              <input type="text" value="${escapeHtml(formatBuffDisplayName(b) || b.name || '命火')}" readonly title="随生命面板同步，不可手改" />
              <span class="hint">劫魄 ${formatBuffPct(jiepo)} · 踏罡 ${formatBuffPct(tagang)}</span>
              <button class="btn sm danger" data-del-buff="${b.id}" disabled title="角色固有，不可删除">删</button>
            </div>
            <p class="hint composite-hint">${hint}</p>
          </div>`;
  }
  const charId = getCompositeEditorCharId();
  const effects = b.effects || [];
  const effectsHtml = effects
    .map((effect, ei) => {
      const isFixed = effect.valueMode === 'fixed';
      const segs = effect.segments || [{ upTo: null, perStack: 0 }];
      const segHtml = segs
        .map((seg, si) => {
          const upToVal = seg.upTo == null ? '' : seg.upTo;
          const prevUpTo = si === 0 ? 0 : segs[si - 1]?.upTo;
          // 计算区间为 (prevUpTo, upTo]：第 1 段从 0 起；后续段从 prevUpTo+1 起（第 7 层只属上段）
          const fromLabel =
            si === 0
              ? '0'
              : prevUpTo == null || prevUpTo === ''
                ? '上段'
                : String(Number(prevUpTo) + 1);
          const toLabel = upToVal === '' ? '∞' : String(upToVal);
          return `
            <div class="composite-seg-row" data-composite-seg-row>
              <span class="hint" style="min-width:4.5rem">${fromLabel}层~${toLabel}层</span>
              <label class="composite-inline">至
                <input type="number" data-composite-seg-upto="${b.id}" data-effect-index="${ei}" data-seg-index="${si}" value="${upToVal}" min="0" step="1" placeholder="∞" title="该段层数上限，留空表示无上限" />
                层
              </label>
              <label class="composite-inline">每层
                <input type="number" data-composite-seg-per="${b.id}" data-effect-index="${ei}" data-seg-index="${si}" value="${seg.perStack}" step="0.01" title="每层数值 (%)" />
                %
              </label>
              <button class="btn sm danger" type="button" data-del-composite-seg="${b.id}" data-effect-index="${ei}" data-seg-index="${si}" ${segs.length <= 1 ? 'disabled' : ''} title="删除分段">删段</button>
            </div>`;
        })
        .join('');
      const typedExtra =
        TYPED_BUFF_CATS.has(effect.zone)
          ? `<select class="dmg-type-select" data-composite-effect-dmgtype="${b.id}" data-effect-index="${ei}" title="伤害类型">${renderDamageTypeOptions(effect.damageType, true)}</select>${
              effect.damageType === '效应'
                ? `<select class="dmg-type-select" data-composite-effect-effecttype="${b.id}" data-effect-index="${ei}" title="效应类型">${renderEffectTypeOptions(effect.effectType)}</select>`
                : ''
            }`
          : '';
      const elementExtra =
        ELEMENT_TYPED_BUFF_CATS.has(effect.zone)
          ? `<select class="dmg-type-select" data-composite-effect-element="${b.id}" data-effect-index="${ei}" title="伤害属性">${renderElementOptions(effect.element || BUFF_ELEMENT_GENERAL, false)}</select>`
          : '';
      const defenseExtra = DEFENSE_BUFF_CATS.has(effect.zone)
        ? `<select class="dmg-type-select" data-composite-effect-defkind="${b.id}" data-effect-index="${ei}" title="防御类型">${renderDefenseKindOptions(effect.defenseKind || 'pen')}</select>`
        : '';
      const scopeNamesVisible = effect.skillScope === 'names' ? '' : ' style="display:none"';
      const fixedValueField = isFixed
        ? `<label class="composite-inline">数值
                <input type="number" data-composite-effect-fixed-value="${b.id}" data-effect-index="${ei}" value="${Number(effect.value) || 0}" step="0.01" title="固定数值 (%)" />
                %</label>`
        : '';
      const segBlock = isFixed
        ? ''
        : `<div class="composite-segs">${segHtml}</div>
          <button class="btn sm" type="button" data-add-composite-seg="${b.id}" data-effect-index="${ei}">+ 分段</button>`;
      return `
        <div class="composite-effect-card" data-composite-effect="${b.id}" data-effect-index="${ei}">
          <div class="composite-effect-head">
            <select data-composite-effect-zone="${b.id}" data-effect-index="${ei}" title="计入乘区">${renderCompositeZoneOptions(effect.zone)}</select>
            ${typedExtra}${elementExtra}${defenseExtra}
            <select data-composite-effect-valuemode="${b.id}" data-effect-index="${ei}" title="固定或叠层">
              <option value="fixed" ${isFixed ? 'selected' : ''}>固定</option>
              <option value="stack" ${!isFixed ? 'selected' : ''}>叠层</option>
            </select>
            ${fixedValueField}
            <label class="composite-inline" title="当前层数达到该值才计入本条效果；0=始终（叠满额外效果可填 3）">≥
              <input type="number" data-composite-effect-minstacks="${b.id}" data-effect-index="${ei}" value="${Math.max(0, Number(effect.minStacks) || 0)}" min="0" step="1" style="width:3.2rem" />
              层
            </label>
            <label class="composite-inline" title="共鸣链达到该值才计入本条效果；0=不限">≥
              <input type="number" data-composite-effect-minresonance="${b.id}" data-effect-index="${ei}" value="${Math.max(0, Math.min(6, Math.round(Number(effect.minResonance) || 0)))}" min="0" max="6" step="1" style="width:3.2rem" />
              链
            </label>
            <select data-composite-effect-scope="${b.id}" data-effect-index="${ei}" title="技能范围" ${
              JIABEILINA_YUHUO_AUTO_EFFECT_KEYS.has(String(effect.effectKey || '')) ||
              SIGRIKA_TALENT_AUTO_EFFECT_KEYS.has(String(effect.effectKey || '')) ||
              ZANNI_YANGUANG_AUTO_EFFECT_KEYS.has(String(effect.effectKey || ''))
                ? 'disabled'
                : ''
            }>
              <option value="all" ${effect.skillScope === 'all' ? 'selected' : ''}>全部技能</option>
              <option value="names" ${effect.skillScope === 'names' ? 'selected' : ''}>指定技能名</option>
            </select>
            <button class="btn sm danger" type="button" data-del-composite-effect="${b.id}" data-effect-index="${ei}" ${
              effects.length <= 1 ||
              JIABEILINA_YUHUO_AUTO_EFFECT_KEYS.has(String(effect.effectKey || '')) ||
              SIGRIKA_TALENT_AUTO_EFFECT_KEYS.has(String(effect.effectKey || '')) ||
              ZANNI_YANGUANG_AUTO_EFFECT_KEYS.has(String(effect.effectKey || ''))
                ? 'disabled'
                : ''
            }>删效果</button>
          </div>
          ${
            String(effect.effectKey || '') === JIABEILINA_YUHUO_C1_CRIT_EFFECT_KEY
              ? '<p class="hint" style="margin:0.25rem 0">【余火·1链】技能跟随其它效果的指定技能；需 ≥1 链才计入暴伤。</p>'
              : String(effect.effectKey || '') === JIABEILINA_YUHUO_C6_DEEP_EFFECT_KEY
                ? '<p class="hint" style="margin:0.25rem 0">【余火·6链】技能跟随其它效果的指定技能；需 ≥6 链才计入热熔加深。</p>'
                : String(effect.effectKey || '') === SIGRIKA_TALENT_C6_DEEP_EFFECT_KEY
                  ? '<p class="hint" style="margin:0.25rem 0">【天赋·6链】技能跟随其它效果的指定技能；需 ≥6 链才计入伤害加深+15%/层。</p>'
                  : String(effect.effectKey || '') === SIGRIKA_TALENT_C6_DEF_IGNORE_EFFECT_KEY
                    ? '<p class="hint" style="margin:0.25rem 0">【天赋·6链】技能跟随其它效果的指定技能；需 ≥6 链才计入无视防御+7.5%/层。</p>'
                    : String(effect.effectKey || '') === ZANNI_YANGUANG_C3_MULT_EFFECT_KEY
                      ? `<p class="hint" style="margin:0.25rem 0">【焰光·3链】指定【终绝将至之刻】倍率增加+${ZANNI_YANGUANG_C3_MULT_PER_STACK}%/层；需 ≥${ZANNI_YANGUANG_C3_MIN_RESONANCE} 链才计入。</p>`
                    : ''
          }
          <div class="composite-skill-names-wrap"${
            JIABEILINA_YUHUO_AUTO_EFFECT_KEYS.has(String(effect.effectKey || '')) ||
            SIGRIKA_TALENT_AUTO_EFFECT_KEYS.has(String(effect.effectKey || '')) ||
            ZANNI_YANGUANG_AUTO_EFFECT_KEYS.has(String(effect.effectKey || ''))
              ? ' style="display:none"'
              : scopeNamesVisible
          }>
            ${renderCompositeSkillNamesSection(b, effect, ei, charId)}
          </div>
          ${segBlock}
        </div>`;
    })
    .join('');
  return `
          <div class="buff-item composite-buff-editor" data-buff-row="${b.id}">
            <div class="composite-buff-main">
              ${renderBuffNameFieldHtml(b, {
                nameAttr: 'data-buff-name',
                buffId: b.id,
                readonly:
                  isProtectedSystemBuff(b) ||
                  isCharacterTemplateBuff(b) ||
                  isSyncedBuffMirror(b),
              })}
              <span class="hint" title="由各效果自动推断">${b.mode === 'fixed' ? '固定·勾选即生效' : '叠层·需填层数'}</span>
              ${
                b.mode === 'fixed'
                  ? ''
                  : `<label class="composite-inline">层数上限
                <input type="number" data-buff-max-stacks="${b.id}" value="${b.maxStacks}" min="1" step="1" title="叠层输入提示上限，可超过填写" />
              </label>`
              }
              <button class="btn sm danger" data-del-buff="${b.id}">删</button>
            </div>
            <p class="hint composite-hint">一条 Buff 可挂多条效果。每条可选<strong>固定</strong>/<strong>叠层</strong>，并设<strong>≥N层</strong>与<strong>≥N链</strong>门槛。全部效果为固定且门槛为 0 时，本体自动为<strong>固定</strong>（编辑轴只勾选、不填层数）；含叠层或 ≥N 门槛时需填层数。指定技能时从技能库点选。</p>
            <div class="composite-effects">${effectsHtml}</div>
            <button class="btn sm primary" type="button" data-add-composite-effect="${b.id}">+ 添加效果</button>
          </div>`;
}

function renderBuffEditorRow(b, opts) {
  const {
    scope = 'member',
    showBuffType = false,
    showDefenseKind = false,
    readonly = false,
    showCategoryTag = false,
    forceCompactRows = false,
  } = opts || {};
  const isTeamMirror = isSyncedBuffMirror(b);
  const isAutoTeamSource = scope === 'team' && isAutoGeneratedTeamBuff(b);
  const isProtected = isProtectedSystemBuff(b);
  const isPanelSyncedValue =
    isLuhesiInnate2DeepBuff(b) ||
    isSigrikaInnate2EchoBonusBuff(b) ||
    isChouyuanLiberationCritDmgBuff(b) ||
    isRococoFlatAtkBuff(b) ||
    isMoningCriticalProtocolErBuff(b) ||
    isMoningC2ErCritDmgBuff(b) ||
    !!b._moningInterferenceMarkHint ||
    isSuisuiOutro2ErBonusBuff(b) ||
    isSuisuiOutro3ErAtkBuff(b) ||
    isShorekeeperStarPurpleBuff(b) ||
    isShorekeeperStarGoldBuff(b) ||
    isDaniaInnateOffsetHarmonyAmpBuff(b) ||
    isJingranHuoxiFuxiBuff(b);
  const ro = readonly || isTeamMirror || isAutoTeamSource || isProtected || isPanelSyncedValue;
  const roAttr = ro ? ' readonly' : '';
  const disAttr = ro ? ' disabled' : '';
  if (scope === 'member' && isJiabeilinaYuhuoBuff(b)) ensureJiabeilinaYuhuoC1Effect(b);
  if (scope === 'member' && isSigrikaTalentBuff(b)) ensureSigrikaTalentEffects(b);
  if (scope === 'member' && isZanniYanguangBuff(b)) ensureZanniYanguangEffects(b);
  if (isYunoBlessingBuff(b)) ensureYunoBlessingEffects(b);
  if (isCompositeBuff(b)) {
    if (scope === 'team') return renderTeamCompositeBuffEditor(b);
    return renderCompositeBuffEditor(b);
  }
  if (isConvergenceBuffCategory(b.category)) {
    // 集谐已迁出编辑区；系统/旧条目不在此展示
    return '';
  }
  let extraField = '';
  const rowShowType = isTypedBuffCategory(b.category);
  // 属性* 页签合并了泛用*：对应 general* 也显示属性下拉（含「泛用」）；特殊技能库仅保留泛用则不显示
  const rowShowElement =
    isElementTypedBuffCategory(b.category) ||
    (!!GENERAL_TO_ELEMENT_BUFF_TAB[b.category] && !isSpecialView());
  const rowShowDefense = isDefenseBuffCategory(b.category);
  const extraParts = [];
  if (rowShowDefense) {
    const attr = scope === 'team' ? 'data-team-buff-defkind' : 'data-buff-defkind';
    extraParts.push(
      `<select class="dmg-type-select" ${attr}="${b.id}"${disAttr}>${renderDefenseKindOptions(b.defenseKind || 'pen')}</select>`
    );
  }
  if (rowShowElement) {
    const attr = scope === 'team' ? 'data-team-buff-element' : 'data-buff-element';
    extraParts.push(
      `<select class="dmg-type-select" ${attr}="${b.id}" title="伤害属性"${disAttr}>${renderElementOptions(getBuffElementSelectValue(b), false)}</select>`
    );
  }
  if (rowShowType) {
    const attr = scope === 'team' ? 'data-team-buff-dmgtype' : 'data-buff-dmgtype';
    extraParts.push(
      `<select class="dmg-type-select" ${attr}="${b.id}"${disAttr}>${renderDamageTypeOptions(b.damageType, false)}</select>`
    );
    if (b.damageType === '效应') {
      const etAttr = scope === 'team' ? 'data-team-buff-effecttype' : 'data-buff-effecttype';
      extraParts.push(
        `<select class="dmg-type-select" ${etAttr}="${b.id}" title="效应类型（泛用=全部效应）"${disAttr}>${renderEffectTypeOptions(b.effectType)}</select>`
      );
    }
  }
  if (extraParts.length) {
    extraField = `<span class="buff-extra-fields">${extraParts.join('')}</span>`;
  }
  const stackMode = isStackBuff(b);
  // 多字段（如类型+效应子类型）或类型防御：改两行紧凑布局，避免窄栏溢出无法编辑
  // Tab 抽屉等窄栏可 forceCompactRows，避免名称前缀与下拉叠在同一行
  const isCompactRow =
    forceCompactRows ||
    (rowShowDefense && rowShowType) ||
    extraParts.length >= 2 ||
    (rowShowType && b.damageType === '效应');
  const modeAttr = scope === 'team' ? 'data-team-buff-mode' : 'data-buff-mode';
  const modeSelect = `<select class="buff-mode-select" ${modeAttr}="${b.id}" title="数值模式"${disAttr}>
              <option value="fixed" ${b.mode === 'fixed' ? 'selected' : ''}>固定</option>
              <option value="stack" ${b.mode === 'stack' ? 'selected' : ''}>叠层</option>
            </select>`;
  const nameAttr = scope === 'team' ? 'data-team-buff-name' : 'data-buff-name';
  const valueUnitHint =
    isHarmonyBreakAmpBuff(b) || BUFF_CATS[b.category]?.unit === '' ? '点数' : '%';
  const valueTitle = isLuhesiInnate2DeepBuff(b)
    ? String(
        b._luhesiDeepHint ||
          '陆·赫斯固有2：按谐幅每满10点转化加深（默认+5%/上限30%；2链翻倍为+10%/上限60%；只读同步）'
      )
    : isSigrikaInnate2EchoBonusBuff(b)
      ? String(
          b._sigrikaEchoBonusHint ||
            '西格莉卡固有2：消耗【日灵能量】少于30点时，每消耗10点使符语爆破/符语链刃/符语日灵伤害加深15%'
        )
    : typeof isLupaZhuilieBuff === 'function' && isLupaZhuilieBuff(b)
      ? String(
          b._lupaZhuilieHint ||
            '露帕·追猎：层数仅影响攻击力（基础+6%攻击；每层额外+6%，上限3层）；10%热熔伤害加成由系统按队伍热熔角色数自动判定（3名热熔角色或露帕≥3链时生效），不随层数变化'
        )
    : isChouyuanLiberationCritDmgBuff(b)
      ? String(
          b._chouyuanCritDmgHint ||
            '仇远·万钧一断：暴击>50%时每多出1%暴击→全队暴伤+2%，上限30%（按仇远面板暴击只读同步）'
        )
    : isRococoFlatAtkBuff(b)
      ? String(
          b._rococoFlatAtkHint ||
            '洛可可·大招：暴击>50%时每满0.1%→全队固定攻击+1，上限200（按洛可可最终暴击只读同步：面板+对其生效的暴击类Buff，如守岸人深潜星域；写入覆盖角色固定攻）'
        )
    : b._moningInterferenceMarkHint
      ? String(b._moningInterferenceMarkHint)
    : isMoningC2ErCritDmgBuff(b)
      ? String(
          b._moningC2CritDmgHint ||
            '莫宁2链：共鸣效率>100%时每超过1%→全队暴伤+0.2%，上限32%（按莫宁面板只读同步）'
        )
    : isSuisuiOutro2ErBonusBuff(b)
      ? String(
          b._suisuiOutro2Hint ||
            '穗穗延奏2：共鸣效率>200%时每满1%→全队增伤+0.2%，不足1%不转化，上限12%（按穗穗面板只读同步）'
        )
    : isSuisuiOutro3ErAtkBuff(b)
      ? String(
          b._suisuiOutro3Hint ||
            '穗穗·延奏3·烟岚：共鸣效率>200%时每满0.12%→全队攻击+0.1%，不足不转化，上限50%（穗穗本人不生效；按穗穗面板只读同步）'
        )
    : isShorekeeperStarPurpleBuff(b)
      ? String(
          b._shorekeeperStarPurpleHint ||
            '深潜星域(紫)：每满0.2%共鸣效率→全队暴击+0.01%，不足不转化，上限12.5%（按守岸人面板只读同步）'
        )
    : isShorekeeperStarGoldBuff(b)
      ? String(
          b._shorekeeperStarGoldHint ||
            '解限星域(金)：每满0.1%共鸣效率→全队暴伤+0.01%，不足不转化，上限25%（按守岸人面板只读同步）'
        )
    : isDaniaInnateOffsetHarmonyAmpBuff(b)
      ? String(
          b._daniaOffsetHarmonyHint ||
            `达妮娅·固有：基础${DANIA_INNATE_BASE_HARMONY_AMP}点 + 按本角色偏谐值累积效率转化（超过100%时每满10%+8点，转化上限${DANIA_INNATE_OFFSET_HARMONY_AMP_CAP}；只读同步）`
        )
    : isJingranHuoxiFuxiBuff(b)
      ? String(
          b._jingranHuoxiFuxiHint ||
            `祸兮福兮：每层按生命转化热熔增伤（每${JINGRAN_HP_FLAT_ATK_HP_CHUNK}生命+${JINGRAN_HUOXI_FUXI_PER_CHUNK}%，单层上限${JINGRAN_HUOXI_FUXI_PER_STACK_CAP}%）；层数上限${JINGRAN_HUOXI_FUXI_MAX_STACKS}（只读同步每层数值）`
        )
    : stackMode
      ? `每层数值 (${valueUnitHint})`
      : `固定数值 (${valueUnitHint})`;
  const valueField = stackMode
    ? `<input type="number" class="buff-entry-value value-input" ${scope === 'team' ? 'data-team-buff-per-stack' : 'data-buff-per-stack'}="${b.id}" value="${b.perStack}" step="0.1" min="0" title="${escapeTooltip(valueTitle)}"${roAttr} />`
    : `<input type="number" class="buff-entry-value value-input" ${scope === 'team' ? 'data-team-buff-value' : 'data-buff-value'}="${b.id}" value="${b.value}" step="0.1" title="${escapeTooltip(valueTitle)}"${roAttr} />`;
  let actionCell = '';
  if (scope === 'team') {
    actionCell = renderTeamBuffActionCell(b);
  } else if (isProtected) {
    actionCell = `<button class="btn sm danger" data-del-buff="${b.id}" disabled title="角色固有，不可删除">删</button>`;
  } else if (isTeamMirror) {
    actionCell = `<button class="btn sm danger" data-del-buff="${b.id}" title="仅从本角色移除">删</button>`;
  } else {
    actionCell = `<button class="btn sm danger" data-del-buff="${b.id}">删</button>`;
  }

  // Buff 来源面板：紧凑卡片（头栏名称 + 下行控件）
  if (scope === 'team') {
    const controlParts = [valueField];
    if (rowShowDefense) {
      controlParts.push(
        `<select class="dmg-type-select buff-entry-select type-select" data-team-buff-defkind="${b.id}" title="防御类型"${disAttr}>${renderDefenseKindOptions(b.defenseKind || 'pen')}</select>`
      );
    }
    if (rowShowElement) {
      controlParts.push(
        `<select class="dmg-type-select buff-entry-select type-select" data-team-buff-element="${b.id}" title="伤害属性"${disAttr}>${renderElementOptions(getBuffElementSelectValue(b), false)}</select>`
      );
    }
    if (rowShowType) {
      controlParts.push(
        `<select class="dmg-type-select buff-entry-select type-select" data-team-buff-dmgtype="${b.id}" title="伤害类型"${disAttr}>${renderDamageTypeOptions(b.damageType, false)}</select>`
      );
      if (b.damageType === '效应') {
        controlParts.push(
          `<select class="dmg-type-select buff-entry-select type-select" data-team-buff-effecttype="${b.id}" title="效应类型（泛用=全部效应）"${disAttr}>${renderEffectTypeOptions(b.effectType)}</select>`
        );
      }
    }
    if (stackMode) {
      controlParts.push(renderTeamBuffStackIndicator(b));
      // 可编辑时仍保留模式切换；自动来源只读则仅显示叠层 badge
      if (!ro) {
        controlParts.push(
          `<select class="buff-mode-select buff-entry-select type-select" data-team-buff-mode="${b.id}" title="数值模式">
              <option value="fixed" ${b.mode === 'fixed' ? 'selected' : ''}>固定</option>
              <option value="stack" ${b.mode === 'stack' ? 'selected' : ''}>叠层</option>
            </select>`
        );
      }
    } else {
      controlParts.push(
        `<select class="buff-mode-select buff-entry-select type-select" data-team-buff-mode="${b.id}" title="数值模式"${disAttr}>
              <option value="fixed" ${b.mode === 'fixed' ? 'selected' : ''}>固定</option>
              <option value="stack" ${b.mode === 'stack' ? 'selected' : ''}>叠层</option>
            </select>`
      );
    }
    const kindTag = renderTeamBuffAutoTag(b);
    const catTag = showCategoryTag
      ? `<span class="buff-cat-tag" title="乘区">${escapeHtml(BUFF_CATS[b.category]?.label || b.category || '')}</span>`
      : '';
    const sourceKind = getTeamBuffEntrySourceKind(b);
    return `
          <div class="buff-item buff-entry${stackMode ? ' stack-def is-stack' : ''}" data-buff-row="${b.id}" data-source="${escapeHtml(sourceKind)}">
            ${renderBuffEntryHeaderHtml(b, {
              scope,
              nameAttr,
              buffId: b.id,
              readonly: ro,
              catTagHtml: catTag,
            })}
            <div class="buff-entry-controls">
              ${controlParts.join('')}
              ${kindTag ? `<span class="buff-entry-kind">${kindTag}</span>` : ''}
            </div>
          </div>`;
  }

  // 抽屉窄栏：紧凑卡片（名称头栏 + 控件行）
  if (forceCompactRows) {
    const controlParts = [];
    if (rowShowDefense) {
      controlParts.push(
        `<select class="dmg-type-select type-select" data-buff-defkind="${b.id}" title="防御类型"${disAttr}>${renderDefenseKindOptions(b.defenseKind || 'pen')}</select>`
      );
    }
    if (rowShowElement) {
      controlParts.push(
        `<select class="dmg-type-select type-select" data-buff-element="${b.id}" title="伤害属性"${disAttr}>${renderElementOptions(getBuffElementSelectValue(b), false)}</select>`
      );
    }
    if (rowShowType) {
      controlParts.push(
        `<select class="dmg-type-select type-select" data-buff-dmgtype="${b.id}" title="伤害类型"${disAttr}>${renderDamageTypeOptions(b.damageType, false)}</select>`
      );
      if (b.damageType === '效应') {
        controlParts.push(
          `<select class="dmg-type-select type-select" data-buff-effecttype="${b.id}" title="效应类型（泛用=全部效应）"${disAttr}>${renderEffectTypeOptions(b.effectType)}</select>`
        );
      }
    }
    controlParts.push(
      `<select class="buff-mode-select type-select" data-buff-mode="${b.id}" title="数值模式"${disAttr}>
              <option value="fixed" ${b.mode === 'fixed' ? 'selected' : ''}>固定</option>
              <option value="stack" ${b.mode === 'stack' ? 'selected' : ''}>叠层</option>
            </select>`
    );
    controlParts.push(valueField);
    const catTag = showCategoryTag
      ? `<span class="buff-category-tag" title="乘区">${escapeHtml(BUFF_CATS[b.category]?.label || b.category || '')}</span>`
      : '';
    const sourceKind = getMemberBuffEntrySourceKind(b, scope);
    const sourceAttr = sourceKind ? ` data-source="${escapeHtml(sourceKind)}"` : '';
    const sourceFilter = String(state?.buffDrawer?.sourceFilter || '');
    const filterCls =
      sourceFilter && sourceKind
        ? sourceKind === sourceFilter
          ? ' is-highlighted'
          : ' is-dimmed'
        : '';
    return `
          <div class="buff-item buff-entry${stackMode ? ' stack-def is-stack' : ''}${isTeamMirror ? ' team-mirror' : ''}${filterCls}" data-buff-row="${b.id}"${sourceAttr}>
            ${renderBuffEntryHeaderHtml(b, {
              scope,
              nameAttr,
              buffId: b.id,
              readonly: ro,
              isProtected,
              isTeamMirror,
              catTagHtml: catTag,
            })}
            <div class="buff-entry-controls">${controlParts.join('')}</div>
          </div>`;
  }

  if (isCompactRow) {
    const metaParts = [];
    if (rowShowDefense) {
      const attr = scope === 'team' ? 'data-team-buff-defkind' : 'data-buff-defkind';
      metaParts.push(
        `<select class="dmg-type-select" ${attr}="${b.id}" title="防御类型"${disAttr}>${renderDefenseKindOptions(b.defenseKind || 'pen')}</select>`
      );
    }
    if (rowShowElement) {
      const attr = scope === 'team' ? 'data-team-buff-element' : 'data-buff-element';
      metaParts.push(
        `<select class="dmg-type-select" ${attr}="${b.id}" title="伤害属性"${disAttr}>${renderElementOptions(getBuffElementSelectValue(b), false)}</select>`
      );
    }
    if (rowShowType) {
      const attr = scope === 'team' ? 'data-team-buff-dmgtype' : 'data-buff-dmgtype';
      metaParts.push(
        `<select class="dmg-type-select" ${attr}="${b.id}" title="伤害类型"${disAttr}>${renderDamageTypeOptions(b.damageType, false)}</select>`
      );
      if (b.damageType === '效应') {
        const etAttr = scope === 'team' ? 'data-team-buff-effecttype' : 'data-buff-effecttype';
        metaParts.push(
          `<select class="dmg-type-select" ${etAttr}="${b.id}" title="效应类型（泛用=全部效应）"${disAttr}>${renderEffectTypeOptions(b.effectType)}</select>`
        );
      }
    }
    metaParts.push(modeSelect, valueField);
    const catTag = showCategoryTag
      ? `<span class="buff-cat-tag" title="乘区">${escapeHtml(BUFF_CATS[b.category]?.label || b.category || '')}</span>`
      : '';
    return `
          <div class="buff-item buff-item-compact${stackMode ? ' stack-def' : ''}${isTeamMirror ? ' team-mirror' : ''}" data-buff-row="${b.id}">
            ${catTag}
            ${renderBuffNameFieldHtml(b, { scope, nameAttr, buffId: b.id, readonly: ro })}
            ${actionCell}
            <div class="buff-meta-row">${metaParts.join('')}</div>
          </div>`;
  }
  const layoutClass = `${extraParts.length ? (extraParts.length > 1 ? 'has-extra has-extra-duo' : 'has-extra') : 'no-type'}${stackMode ? ' stack-def' : ''}${isTeamMirror ? ' team-mirror' : ''}`;
  const catTag = showCategoryTag
    ? `<span class="buff-cat-tag" title="乘区">${escapeHtml(BUFF_CATS[b.category]?.label || b.category || '')}</span>`
    : '';
  return `
          <div class="buff-item ${layoutClass}" data-buff-row="${b.id}">
            ${catTag}
            ${renderBuffNameFieldHtml(b, { scope, nameAttr, buffId: b.id, readonly: ro })}
            ${extraField}
            ${modeSelect}
            ${valueField}
            ${actionCell}
          </div>`;
}

function formatWeaponTeamBuffBrief(buff) {
  const cat = BUFF_CATS[buff.category]?.label || buff.category;
  const val =
    buff.mode === 'stack'
      ? `${buff.perStack || buff.value}%/层`
      : `${buff.value}%`;
  const type = buff.damageType
    ? buff.damageType === '效应'
      ? `·效应·${normalizeBuffEffectType(buff.effectType)}`
      : `·${buff.damageType}`
    : '';
  return `${cat}${type} ${val}`;
}

function formatCompositeEffectsBrief(buff) {
  return (buff?.effects || [])
    .map((fx) => {
      const zone = BUFF_CATS[fx.zone]?.label || fx.zone || '';
      const el = fx.element ? `·${fx.element}` : '';
      const dt = fx.damageType ? `·${fx.damageType}` : '';
      const gate = Math.max(0, Number(fx.minStacks) || 0) > 0 ? `≥${fx.minStacks}层` : '';
      const onlyIds = Array.isArray(fx.onlyCharacterIds) ? fx.onlyCharacterIds.filter(Boolean) : [];
      const onlyHint = onlyIds.length
        ? onlyIds.map(String).includes(String(REBECCA_CHAR_ID))
          ? '仅丽贝卡'
          : `仅角色${onlyIds.join('/')}`
        : '';
      const suffix = [gate, onlyHint].filter(Boolean).join('·');
      if (fx.valueMode === 'fixed') {
        return `${zone}${el}${dt}+${Number(fx.value) || 0}%${suffix ? `(${suffix})` : ''}`;
      }
      const per = Number(fx.segments?.[0]?.perStack) || 0;
      return `${zone}${el}${dt}+${per}%/层${suffix ? `(${suffix})` : ''}`;
    })
    .filter(Boolean)
    .join('；');
}

function formatTeamBuffAssignBrief(buff) {
  if (isCompositeBuff(buff)) {
    const brief = formatCompositeEffectsBrief(buff);
    const stackHint =
      buff.mode === 'stack' ? `叠层×${buff.maxStacks || 3}` : '固定';
    return `复合·${stackHint}${brief ? ` · ${brief}` : ''}`;
  }
  const cat = BUFF_CATS[buff.category]?.label || buff.category;
  const val =
    buff.mode === 'stack'
      ? `${buff.perStack || buff.value}%/层×${buff.maxStacks || 5}`
      : `${buff.value}%`;
  const type = buff.damageType
    ? buff.damageType === '效应'
      ? `·效应·${normalizeBuffEffectType(buff.effectType)}`
      : `·${buff.damageType}`
    : buff.element
      ? `·${buff.element}`
      : GENERAL_TO_ELEMENT_BUFF_TAB[buff.category]
        ? `·${BUFF_ELEMENT_GENERAL}`
        : '';
  return `${cat}${type} ${val}`;
}

/** 全队 Buff 若全部效果都限定角色，返回这些角色 id；有任意不限效果则返回空（不全员打 ×） */
function getTeamBuffOnlyCharacterIds(buff) {
  if (!buff) return [];
  if (Array.isArray(buff.onlyCharacterIds) && buff.onlyCharacterIds.length) {
    return buff.onlyCharacterIds.map((id) => String(id || '').trim()).filter(Boolean);
  }
  if (!isCompositeBuff(buff)) return [];
  const effects = buff.effects || [];
  if (!effects.length) return [];
  if (effects.some((fx) => !(Array.isArray(fx.onlyCharacterIds) && fx.onlyCharacterIds.length))) {
    return [];
  }
  const set = new Set();
  effects.forEach((fx) => {
    (fx.onlyCharacterIds || []).forEach((id) => {
      const s = String(id || '').trim();
      if (s) set.add(s);
    });
  });
  return [...set];
}

function renderTeamCompositeBuffEditor(b) {
  const brief = formatCompositeEffectsBrief(b);
  const autoStack = isTeamFusionStackSyncBuff(b);
  const isTpl = isCharacterTemplateBuff(b);
  const modeHint = b.mode === 'fixed' ? '固定·勾选即生效' : `叠层·上限 ${b.maxStacks || 3}`;
  const nameReadonly = isTpl || isAutoGeneratedTeamBuff(b);
  const kindTag = renderTeamBuffAutoTag(b);
  const sourceKind = getTeamBuffEntrySourceKind(b);
  const stackCtrl = isStackBuff(b) ? renderTeamBuffStackIndicator(b) : '';
  return `
          <div class="buff-item buff-entry composite-buff-editor${isStackBuff(b) ? ' is-stack' : ''}" data-buff-row="${b.id}" data-source="${escapeHtml(sourceKind)}">
            ${renderBuffEntryHeaderHtml(b, {
                scope: 'team',
                nameAttr: 'data-team-buff-name',
                buffId: b.id,
                readonly: nameReadonly,
              })}
            <div class="buff-entry-controls">
              ${stackCtrl}
              <span class="hint buff-entry-mode-hint">${escapeHtml(modeHint)}</span>
              ${kindTag ? `<span class="buff-entry-kind">${kindTag}</span>` : ''}
            </div>
            <p class="hint composite-hint" title="${escapeHtml(brief)}">${escapeHtml(brief || '暂无效果')}</p>
            <p class="hint composite-hint">分配矩阵只改这一条即可覆盖全部效果。${autoStack ? (isLupaC3FullStackUnlocked(b) ? '露帕≥3链：层数固定满层（额外效果全额，不受热熔人数限制）。' : '层数随队内热熔角色数自动同步；露帕≥3链时固定满层。') : ''}${isTpl ? '细则由角色 Buff 模板维护。' : '可在角色 Buff 模板用复合编辑器细调。'}</p>
          </div>`;
}

function formatTeamBuffMatrixSourceHint(buff) {
  if (buff.weaponTeamBuff) {
    const holder = state.members[buff.weaponSourceMemberIndex];
    return holder ? `来自 ${holder.name || `角色${(buff.weaponSourceMemberIndex || 0) + 1}`}` : '武器';
  }
  if (buff.echoSetTeamBuff) {
    const holder = state.members[buff.echoSetSourceMember];
    const setDef = findEchoSetDef(buff.echoSetSourceId);
    const setName = setDef?.name ? ` · ${setDef.name}` : '';
    return holder
      ? `套装${setName} · ${holder.name || `角色${(buff.echoSetSourceMember || 0) + 1}`}`
      : `套装${setName}`;
  }
  if (buff.echoMainTeamBuff) {
    const holder = state.members[buff.echoMainSourceMember];
    return holder ? `声骸 · ${holder.name || `角色${(buff.echoMainSourceMember || 0) + 1}`}` : '声骸';
  }
  const src = getTeamBuffSourceMemberIndex(buff);
  if (src != null) {
    const holder = state.members[src];
    return holder ? `来自 ${holder.name || `角色${src + 1}`}` : `角色${src + 1}`;
  }
  return '全队来源';
}

/**
 * —— 全队 Buff 分配 UI 重构（分步）——
 *
 * 现状：`renderTeamBuffAssignMatrix` 用双行表头 HTML table
 *   列 = 来源角色分组 → Buff；行 = 接收角色 0/1/2；格内 ✓勾选 / ×固定无效 / —空列
 *
 * 目标布局（勿一次做完，按步推进）：
 *   1) 抽离单元格状态与来源分组视图模型
 *   2) 状态指示器：`renderBuffCell`（status active/disabled/none/stackable）
 *   3) 来源角色卡片 `.buff-source-card` + `.buff-grid` 替换 table
 *   4) 叠层：badge + 点击 cell 弹出叠层设置小面板（毛玻璃，点外关闭）
 *
 * 事件契约（重构时必须保留）：
 *   - data-team-buff-assign + data-member-index  → 覆盖勾选
 *   - data-team-buff-assign-stack + data-member-index → 角色叠层
 *   - data-team-buff-focus → 跳转 Buff 来源编辑
 */

/** BuffCell 状态：可勾选 / 固定无效 / 无关 / 可叠层 */
/** @typedef {'active'|'disabled'|'none'|'stackable'} BuffCellStatus */

const BUFF_CELL_ICON_CHECK = `<svg class="buff-cell__icon" viewBox="0 0 12 12" aria-hidden="true" focusable="false"><path fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" d="M2.5 6.2 5 8.7 9.5 3.5"/></svg>`;
const BUFF_CELL_ICON_LOCK = `<svg class="buff-cell__icon buff-cell__icon--lock" viewBox="0 0 12 12" aria-hidden="true" focusable="false"><path fill="currentColor" d="M6 1.6A2.2 2.2 0 0 0 3.8 3.8V5H3.2A1.2 1.2 0 0 0 2 6.2v3.6A1.2 1.2 0 0 0 3.2 11h5.6A1.2 1.2 0 0 0 10 9.8V6.2A1.2 1.2 0 0 0 8.8 5H8.2V3.8A2.2 2.2 0 0 0 6 1.6Zm0 1.2c.55 0 1 .45 1 1V5H5V3.8c0-.55.45-1 1-1Z"/></svg>`;
/** 可叠层提示：层数为 0 时显示，告知用户可点开设置 */
const BUFF_CELL_ICON_STACK = `<svg class="buff-cell__stack-hint" width="14" height="14" viewBox="0 0 14 14" aria-hidden="true" focusable="false"><path d="M2 4h10M2 7h10M2 10h10" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/></svg>`;

function fillBuffCellStackBadge(badge, stackCount) {
  if (!badge) return;
  const n = Math.max(0, normalizeStackInput(stackCount));
  badge.classList.toggle('is-zero', n <= 0);
  badge.classList.toggle('is-stacked', n > 0);
  if (n > 0) {
    badge.textContent = `x${n}`;
  } else {
    badge.innerHTML = BUFF_CELL_ICON_STACK;
  }
}

/**
 * BuffCell — 全队分配格子状态指示器（替代 ✓ / × / -）
 * @param {{
 *   status: BuffCellStatus,
 *   checked?: boolean,
 *   stackCount?: number,
 *   maxStacks?: number,
 *   autoStack?: boolean,
 *   buffId?: string,
 *   memberIndex?: number,
 *   title?: string,
 * }} props
 */
function renderBuffCell(props) {
  const status = props?.status || 'none';
  const checked = !!props?.checked;
  const stackCount = Math.max(0, Number(props?.stackCount) || 0);
  const maxStacks = Math.max(1, Number(props?.maxStacks) || 5);
  const autoStack = !!props?.autoStack;
  const buffId = props?.buffId != null ? String(props.buffId) : '';
  const memberIndex = props?.memberIndex;
  const title = String(props?.title || '');

  if (status === 'none') {
    return `<span class="buff-cell buff-cell--none" aria-hidden="true" title=""><span class="buff-cell__dot"></span></span>`;
  }

  if (status === 'disabled') {
    const tip = title || '该buff对当前角色固定不生效';
    return `<span class="buff-cell buff-cell--disabled" title="${escapeHtml(tip)}" role="img" aria-label="${escapeHtml(tip)}"><span class="buff-cell__dot">${BUFF_CELL_ICON_LOCK}</span></span>`;
  }

  const checkedClass = checked ? ' is-checked' : '';
  const miAttr = memberIndex != null && Number.isFinite(Number(memberIndex)) ? ` data-member-index="${Number(memberIndex)}"` : '';
  const assignAttr = buffId ? ` data-team-buff-assign="${escapeHtml(buffId)}"` : '';

  if (status === 'stackable') {
    // canStack ≡ status==='stackable'（由 isStackBuff / mode:stack 推导，无需额外字段）
    const tip = title || '点圆点开关覆盖；点右侧叠层标识打开设置';
    const autoAttr = autoStack ? ' data-tba-auto-stack="1"' : '';
    const stackedClass = stackCount > 0 ? ' is-stacked' : ' is-zero';
    const badgeInner = stackCount > 0 ? `x${stackCount}` : BUFF_CELL_ICON_STACK;
    const stackTip = stackCount > 0 ? `点击查看叠层设置（当前 x${stackCount}）` : '点击查看叠层设置';
    console.log('[BuffCell] 渲染角标:', buffId, stackCount);
    return `<span class="buff-cell buff-cell--stackable${checkedClass}${autoStack ? ' is-auto-stack' : ''}" title="${escapeHtml(tip)}">
      <label class="buff-cell__toggle" title="开关：是否覆盖到该角色">
        <input type="checkbox" class="buff-cell__input"${assignAttr}${miAttr} ${checked ? 'checked' : ''} />
        <span class="buff-cell__dot" aria-hidden="true">${BUFF_CELL_ICON_CHECK}</span>
      </label>
      <button type="button" class="buff-cell__badge-hit" data-tba-stack-open="${escapeHtml(buffId)}"${miAttr} data-tba-max-stacks="${maxStacks}"${autoAttr} title="${escapeHtml(stackTip)}" aria-label="${escapeHtml(stackTip)}">
        <span class="buff-cell__badge${stackedClass}" data-tba-stack-badge aria-hidden="true">${badgeInner}</span>
      </button>
    </span>`;
  }

  return `<label class="buff-cell buff-cell--active${checkedClass}" title="${escapeHtml(title)}">
    <input type="checkbox" class="buff-cell__input"${assignAttr}${miAttr} ${checked ? 'checked' : ''} />
    <span class="buff-cell__dot" aria-hidden="true">${BUFF_CELL_ICON_CHECK}</span>
  </label>`;
}

/** @typedef {'active'|'inactive'|'locked'|'empty'} TeamBuffAssignCellKind */

/**
 * 统一解析「某 Buff × 某接收角色」格子语义（供表格与后续卡片共用）
 * @returns {{
 *   kind: TeamBuffAssignCellKind,
 *   lockedReason?: string,
 *   checked?: boolean,
 *   isStack?: boolean,
 *   stacks?: number,
 *   autoStack?: boolean,
 *   stackTitle?: string,
 *   brief?: string,
 * }}
 */
function resolveTeamBuffAssignCellState(b, mi) {
  const m = state.members[mi];
  if (!m || !b) return { kind: 'empty' };

  const srcIdx = getTeamBuffSourceMemberIndex(b);
  if (
    (b.excludeSource || isNextMemberOnlyBuff(b)) &&
    srcIdx === mi &&
    !(typeof isRococoFlatAtkBuff === 'function' && isRococoFlatAtkBuff(b)) &&
    !(typeof isSpecialDefaultSyncBuffSource === 'function' && isSpecialDefaultSyncBuffSource(b))
  ) {
    return { kind: 'locked', lockedReason: '对来源角色不生效', brief: formatTeamBuffAssignBrief(b) };
  }

  const onlyIds = getTeamBuffOnlyCharacterIds(b);
  if (onlyIds.length) {
    const charId = String(m?.characterId || '').trim();
    if (!charId || !onlyIds.includes(charId)) {
      return { kind: 'locked', lockedReason: '仅指定角色生效', brief: formatTeamBuffAssignBrief(b) };
    }
  }

  if (isCompositeBuff(b) && (b.effects || []).length) {
    const anyAllowed = (b.effects || []).some((fx) => compositeEffectMeetsTargetFilters(fx, m));
    if (!anyAllowed) {
      return { kind: 'locked', lockedReason: '本角色不满足效果限定', brief: formatTeamBuffAssignBrief(b) };
    }
  }

  const excluded = new Set(m.excludedTeamBuffIds || []);
  const checked = !excluded.has(b.id);
  const brief = formatTeamBuffAssignBrief(b);
  const base = {
    kind: checked ? 'active' : 'inactive',
    checked,
    brief,
    isStack: isStackBuff(b),
  };

  if (!base.isStack) return base;

  const stacks = readTeamBuffAssignStackCount(b, mi);
  const autoStack =
    (typeof isTeamFusionStackSyncBuff === 'function' && isTeamFusionStackSyncBuff(b)) ||
    (typeof isEchoSetHarmonyAmpAtkBuff === 'function' && isEchoSetHarmonyAmpAtkBuff(b));
  return {
    ...base,
    stacks,
    autoStack,
    maxStacks: Math.max(1, Number(b.maxStacks) || 5),
    stackTitle: autoStack
    ? '自动同步层数（只读）'
      : '本角色层数（写入该角色全局默认，计算中可再调）',
  };
}

/**
 * 读取「全队 Buff × 接收角色」叠层数（角标 / 面板同源）
 * 优先：角色镜像 buff 的 id → 稳定镜像 id(tm_*) → 全队 shared 层数
 */
function readTeamBuffAssignStackCount(b, mi) {
  const m = state.members[mi];
  if (!m || !b) return 0;
  if (isTongzouLayerLinkedBuff(b)) {
    if (TONGZOU_ALWAYS_LINK_KEYS.has(String(b.templateKey || ''))) {
      return Math.min(getTongzouLinkedStacks(b, m), Number(b.maxStacks) || 4);
    }
    const mirror = (m.buffs || []).find((x) => x.teamSourceId === b.id);
    const explicit = mirror && m.globalBuffStacks?.[mirror.id];
    if (explicit !== undefined && explicit !== '') return normalizeStackInput(explicit);
    return getTongzouLinkedStacks(b, m);
  }
  const shared = ensureTeamSharedBuffs();
  const mirrorId = makeTeamMirrorBuffId(b.id);
  const mirror = (m.buffs || []).find((x) => x.teamSourceId === b.id);
  const map = m.globalBuffStacks || {};
  let stacks = 0;
  if (mirror && map[mirror.id] !== undefined && map[mirror.id] !== '') {
    stacks = normalizeStackInput(map[mirror.id]);
  } else if (map[mirrorId] !== undefined && map[mirrorId] !== '') {
    stacks = normalizeStackInput(map[mirrorId]);
  } else if (shared.globalBuffStacks?.[b.id] !== undefined && shared.globalBuffStacks[b.id] !== '') {
    stacks = normalizeStackInput(shared.globalBuffStacks[b.id]);
  }
  if (typeof window !== 'undefined' && window.__TBA_DEBUG__) {
    console.log('[TBA] readStack', {
      buffId: b.id,
      mi,
      mirrorId: mirror?.id || null,
      stableId: mirrorId,
      stacks,
      memberMap: { ...(map || {}) },
      shared: shared.globalBuffStacks?.[b.id],
    });
  }
  return stacks;
}

/**
 * 就地刷新角标数字（与全局 state 同源；用 dataset 匹配避免 id 特殊字符选择器失败）
 * @param {string} buffId
 * @param {number|string} memberIndex
 * @param {number} stackCount
 * @param {{ silent?: boolean }} [opts]
 */
function updateTeamBuffAssignStackBadge(buffId, memberIndex, stackCount, opts = {}) {
  const id = String(buffId || '');
  const mi = String(memberIndex);
  if (!id || mi === '' || mi === 'NaN') return false;
  const n = Math.max(0, normalizeStackInput(stackCount));
  let updated = 0;
  document.querySelectorAll('.buff-cell__badge-hit[data-tba-stack-open]').forEach((btn) => {
    if (String(btn.dataset.tbaStackOpen) !== id) return;
    if (String(btn.dataset.memberIndex) !== mi) return;
    const badge = btn.querySelector('[data-tba-stack-badge], .buff-cell__badge');
    if (!badge) return;
    fillBuffCellStackBadge(badge, n);
    const tip = n > 0 ? `点击查看叠层设置（当前 x${n}）` : '点击查看叠层设置';
    btn.setAttribute('title', tip);
    btn.setAttribute('aria-label', tip);
    if (!opts.silent) {
      badge.classList.remove('is-bump');
      void badge.offsetWidth;
      badge.classList.add('is-bump');
    }
    updated += 1;
  });
  // 同步 Buff 来源面板叠层 badge
  document.querySelectorAll('.stack-indicator[data-tba-stack-open]').forEach((btn) => {
    if (String(btn.dataset.tbaStackOpen) !== id) return;
    if (String(btn.dataset.memberIndex) !== mi) return;
    const countEl = btn.querySelector('[data-stack-count]');
    if (countEl) countEl.textContent = `x${n}`;
    const tip = btn.dataset.tbaAutoStack === '1'
      ? '自动同步层数（只读）'
      : n > 0
        ? `点击调整叠层（当前 x${n}，作用于角色${Number(mi) + 1}）`
        : `点击设置叠层（作用于角色${Number(mi) + 1}）`;
    btn.setAttribute('title', tip);
    btn.setAttribute('aria-label', tip);
    if (!opts.silent) {
      btn.classList.remove('is-bump');
      void btn.offsetWidth;
      btn.classList.add('is-bump');
    }
    updated += 1;
  });
  if (!updated) {
    console.warn('[BuffCell] 角标DOM未找到，无法更新:', id, mi, n);
  }
  return updated > 0;
}

/**
 * 来源角色视图模型：卡片布局直接消费此结构
 * @returns {Array<{
 *   key: string,
 *   sourceIndex: number|null,
 *   label: string,
 *   memberIndex: number|null,
 *   buffs: object[],
 *   placeholder: boolean,
 *   accentKey: string,
 *   colSpan: number,
 * }>}
 */
function buildTeamBuffAssignSourceCards(teamBuffs) {
  return buildTeamBuffAssignGroups(teamBuffs).map((g) => {
    const sourceIndex = /^src(\d)$/.exec(g.key);
    const memberIndex = sourceIndex ? Number(sourceIndex[1]) : null;
    return {
      key: g.key,
      sourceIndex: memberIndex,
      memberIndex,
      label: g.label,
      buffs: g.buffs || [],
      placeholder: !!g.placeholder,
      colSpan: g.colSpan ?? Math.max(1, (g.buffs || []).length),
      accentKey: memberIndex == null ? 'orphan' : `member-${memberIndex}`,
    };
  });
}

/** 与角色页签同色的来源卡片主题条 */
const TEAM_BUFF_ASSIGN_ACCENT = {
  0: '#5b9fd4',
  1: '#98c379',
  2: '#e5c07b',
  orphan: 'rgba(255,255,255,0.28)',
};

/** 分配卡片折叠态（会话内，不入库） */
let _teamBuffAssignUi = null;
function ensureTeamBuffAssignUi() {
  if (!_teamBuffAssignUi) _teamBuffAssignUi = { collapsed: Object.create(null) };
  return _teamBuffAssignUi;
}

function teamBuffAssignAccentColor(memberIndex) {
  if (memberIndex == null || memberIndex < 0 || memberIndex > 2) return TEAM_BUFF_ASSIGN_ACCENT.orphan;
  return TEAM_BUFF_ASSIGN_ACCENT[memberIndex] || TEAM_BUFF_ASSIGN_ACCENT.orphan;
}

/** 卡片 body 左侧：接收角色行标签（纯头像，名称仅 title） */
function renderTeamBuffAssignRecvRowLabel(mi) {
  const m = state.members[mi];
  const charDef = m?.characterId ? findCharSkillDef(m.characterId) : null;
  const portrait = charDef
    ? renderCharAvatarCard(charDef, { plain: true })
    : `<div class="char-avatar-card is-plain"><span class="char-avatar-fallback" style="display:flex;background:linear-gradient(135deg,#3a4a5c,#2a3544)">?</span></div>`;
  const name = m?.name || charDef?.name || `角色${mi + 1}`;
  return `<div class="buff-grid__recv" title="${escapeHtml(name)}">${portrait}</div>`;
}

/** Buff 列头（可点击跳转来源编辑；过长省略，title 显示全名） */
function renderTeamBuffAssignBuffHead(b) {
  const shortName = teamBuffAssignShortName(b);
  const displayName = formatBuffDisplayName(b, { scope: 'team' });
  const brief = formatTeamBuffAssignBrief(b);
  const hit = typeof renderBuffGameTextHitAttrs === 'function' ? renderBuffGameTextHitAttrs(b) : '';
  const info = typeof getBuffGameTextInfo === 'function' ? getBuffGameTextInfo(b) : null;
  const ui = typeof ensureBuffGameTextUi === 'function' ? ensureBuffGameTextUi() : null;
  const suppressNativeDetail = !!(info?.hasText || (ui?.editMode && info?.canEdit));
  // 有原文悬停时彻底去掉原生 title，避免白色系统提示与 WcTooltip 叠层
  const titleAttr = suppressNativeDetail
    ? ''
    : ` title="${escapeHtml(`${displayName || shortName}${brief ? ` · ${brief}` : ''}（点击跳转到来源编辑）`)}"`;
  const nameHtml = hit
    ? `<span class="buff-game-text-hit"${hit}>${escapeHtml(shortName)}</span>`
    : escapeHtml(shortName);
  return `<div class="buff-grid__buff-head is-clickable" data-team-buff-focus="${b.id}"${titleAttr} role="button" tabindex="0">${nameHtml}</div>`;
}

/** 单个来源角色卡片 */
function renderBuffSourceCard(card, worksheet = false) {
  const ui = ensureTeamBuffAssignUi();
  const mi = card.memberIndex;
  const accent = teamBuffAssignAccentColor(mi);
  const buffCount = (card.buffs || []).length;
  const viewHidden = worksheet && mi != null && String(mi) !== String(window.__WC.buffCheckView?.selected || '0') ? ' hidden' : '';
  const isEmpty = !!(card.placeholder || !buffCount);

  let headerPortrait = '';
  if (mi != null) {
    const m = state.members[mi];
    const charDef = m?.characterId ? findCharSkillDef(m.characterId) : null;
    headerPortrait = charDef
      ? renderCharAvatarCard(charDef, { plain: true })
      : `<div class="char-avatar-card is-plain"><span class="char-avatar-fallback" style="display:flex;background:linear-gradient(135deg,#3a4a5c,#2a3544)">?</span></div>`;
  } else {
    headerPortrait = `<div class="char-avatar-card is-plain"><span class="char-avatar-fallback" style="display:flex;background:linear-gradient(135deg,#3a4a5c,#2a3544)">?</span></div>`;
  }

  // 无 Buff：紧凑单行，不渲染 body，不抢视觉焦点
  if (isEmpty) {
    const hoverLift = isTbaCardPointerHover(card.key);
    return `
      <div class="buff-source-card is-empty${hoverLift ? ' is-hover-lift is-hover-lift-snap' : ''}" data-tba-card="${escapeHtml(card.key)}"${viewHidden} style="--tba-accent:${accent}" title="该来源暂无全队 Buff">
        <div class="card-header">
          <div class="card-header__identity">
            <span class="card-header__avatar">${headerPortrait}</span>
            <span class="card-header__title">${escapeHtml(card.label)}</span>
            <span class="card-header__empty-tag">暂无Buff</span>
          </div>
        </div>
      </div>`;
  }

  const collapsed = !!ui.collapsed[card.key];
  const hoverLift = isTbaCardPointerHover(card.key);
  const cols = Math.max(1, buffCount);
  const heads = worksheet ? '' : card.buffs.map((b) => renderTeamBuffAssignBuffHead(b)).join('');
  // 左侧固定接收列 + 右侧可横滑 Buff 区：行高由 CSS 变量对齐
  const fixedLabels = worksheet ? '' : [0, 1, 2]
    .map((recv) => `<div class="label">${renderTeamBuffAssignRecvRowLabel(recv)}</div>`)
    .join('');
  const scrollRows = worksheet ? '' : [0, 1, 2]
    .map((recv) =>
      card.buffs
        .map((b) => `<div class="buff-grid__cell">${renderTeamBuffAssignReceiverToggle(b, recv)}</div>`)
        .join('')
    )
    .join('');

  const worksheetHtml = worksheet ? '<table class="local-buff-table"><thead><tr><th scope="col">来源 / 效果</th>' +
    [0, 1, 2].map(recv => '<th scope="col" aria-label="' + escapeHtml(state.members[recv]?.name || '队员 ' + (recv + 1)) + '">' + renderTeamBuffAssignRecvRowLabel(recv) + '</th>').join('') + '</tr></thead><tbody>' +
    card.buffs.map(buff => {
      const cells = [0, 1, 2].map(recv => renderTeamBuffAssignReceiverToggle(buff, recv));
      const brief = [0, 1, 2].map(recv => resolveTeamBuffAssignCellState(buff, recv)?.brief).find(Boolean) || '';
      return '<tr><th scope="row">' + renderTeamBuffAssignBuffHead(buff) + (brief ? '<small>' + escapeHtml(brief) + '</small>' : '') + '</th>' +
        cells.map(cell => '<td><div class="buff-grid__cell">' + cell + '</div></td>').join('') + '</tr>';
    }).join('') + '</tbody></table>' : '';

  return `
    <div class="buff-source-card${collapsed ? ' is-collapsed' : ''}${hoverLift ? ' is-hover-lift is-hover-lift-snap' : ''}" data-tba-card="${escapeHtml(card.key)}"${viewHidden} style="--tba-accent:${accent}">
      <div class="card-header">
        <div class="card-header__identity">
          <span class="card-header__avatar">${headerPortrait}</span>
          <span class="card-header__title">${escapeHtml(card.label)}</span>
          <span class="card-header__count">${buffCount}</span>
        </div>
        <button type="button" class="card-header__toggle" data-tba-collapse="${escapeHtml(card.key)}" aria-expanded="${collapsed ? 'false' : 'true'}" title="${collapsed ? '展开' : '折叠'}">
          <span class="card-header__chevron" aria-hidden="true"></span>
        </button>
      </div>
      <div class="card-body">
        ${worksheet ? worksheetHtml : `        <div class="fixed-label-col">
          <div class="label-header"><span class="hint">接收</span></div>
          ${fixedLabels}
        </div>
        <div class="scrollable-buff-shell">
          <button type="button" class="scrollable-buff-arrow scrollable-buff-arrow--prev" data-tba-hscroll="-1" aria-label="向左滚动" hidden>‹</button>
          <div class="scrollable-buff-area" data-tba-hscroll-area>
            <div class="buff-grid" style="--buff-cols:${cols}">
              ${heads}
              ${scrollRows}
            </div>
          </div>
          <button type="button" class="scrollable-buff-arrow scrollable-buff-arrow--next" data-tba-hscroll="1" aria-label="向右滚动" hidden>›</button>
        </div>`}
      </div>
    </div>`;
}

/** Buff 来源卡悬停抬起：记录指针进入，重绘时无动画贴回抬起态 */
function getTbaCardHoverKeys() {
  if (typeof window === 'undefined') return null;
  if (!(window.__tbaCardHoverKeys instanceof Set)) window.__tbaCardHoverKeys = new Set();
  return window.__tbaCardHoverKeys;
}

function isTbaCardPointerHover(cardKey) {
  const key = String(cardKey || '');
  if (!key) return false;
  return !!getTbaCardHoverKeys()?.has(key);
}

function clearTbaCardHoverLiftSnap() {
  if (typeof document === 'undefined') return;
  document.querySelectorAll('.buff-source-card.is-hover-lift-snap').forEach((card) => {
    card.classList.remove('is-hover-lift-snap');
  });
}

function ensureTbaCardHoverLiftUx() {
  if (typeof document === 'undefined' || document.documentElement.dataset.tbaCardHoverUx === '1') return;
  document.documentElement.dataset.tbaCardHoverUx = '1';
  const keys = getTbaCardHoverKeys();

  document.addEventListener(
    'pointerover',
    (e) => {
      const card = e.target?.closest?.('.buff-source-card[data-tba-card]');
      if (!card) return;
      const from = e.relatedTarget;
      if (from instanceof Node && card.contains(from)) return;
      const key = card.dataset.tbaCard;
      if (!key) return;
      keys.add(key);
      card.classList.add('is-hover-lift');
      card.classList.remove('is-hover-lift-snap');
    },
    true
  );

  document.addEventListener(
    'pointerout',
    (e) => {
      const card = e.target?.closest?.('.buff-source-card[data-tba-card]');
      if (!card) return;
      const to = e.relatedTarget;
      if (to instanceof Node && card.contains(to)) return;
      const key = card.dataset.tbaCard;
      if (key) keys.delete(key);
      card.classList.remove('is-hover-lift', 'is-hover-lift-snap');
    },
    true
  );
}

/** Buff 横滑区：自定义滚动条显隐 + 左右箭头（委托绑定一次） */
function ensureScrollableBuffAreaUx() {
  if (typeof document === 'undefined' || document.documentElement.dataset.tbaHscrollUx === '1') return;
  document.documentElement.dataset.tbaHscrollUx = '1';

  const HIDE_DELAY_MS = 1500;
  const hideTimers = new WeakMap();

  function showScrollUi(area) {
    if (!area) return;
    const shell = area.closest('.scrollable-buff-shell');
    const t = hideTimers.get(area);
    if (t) {
      clearTimeout(t);
      hideTimers.delete(area);
    }
    area.classList.add('is-scroll-ui-visible');
    shell?.classList.add('is-scroll-ui-visible');
  }

  function scheduleHideScrollUi(area) {
    if (!area) return;
    const shell = area.closest('.scrollable-buff-shell');
    const prev = hideTimers.get(area);
    if (prev) clearTimeout(prev);
    hideTimers.set(
      area,
      setTimeout(() => {
        area.classList.remove('is-scroll-ui-visible');
        shell?.classList.remove('is-scroll-ui-visible');
        hideTimers.delete(area);
      }, HIDE_DELAY_MS)
    );
  }

  function getBuffScrollStep(area) {
    const head = area?.querySelector?.('.buff-grid__buff-head');
    const grid = area?.querySelector?.('.buff-grid');
    const gap = parseFloat(grid ? getComputedStyle(grid).columnGap : 24) || 24;
    return Math.max(80, (head?.offsetWidth || 100) + gap);
  }

  function syncScrollableBuffShell(shell) {
    if (!shell) return;
    const area = shell.querySelector('.scrollable-buff-area');
    const prev = shell.querySelector('.scrollable-buff-arrow--prev');
    const next = shell.querySelector('.scrollable-buff-arrow--next');
    if (!area || !prev || !next) return;
    const max = Math.max(0, area.scrollWidth - area.clientWidth);
    const canScroll = max > 2;
    shell.classList.toggle('is-scrollable', canScroll);
    if (!canScroll) {
      prev.hidden = true;
      next.hidden = true;
      return;
    }
    const left = area.scrollLeft;
    prev.hidden = left <= 2;
    next.hidden = left >= max - 2;
  }

  window.syncScrollableBuffAreas = function syncScrollableBuffAreas() {
    document.querySelectorAll('.scrollable-buff-shell').forEach(syncScrollableBuffShell);
  };

  document.addEventListener(
    'pointerenter',
    (e) => {
      const shell = e.target?.closest?.('.scrollable-buff-shell');
      if (!shell) return;
      const area = shell.querySelector('.scrollable-buff-area');
      if (area) showScrollUi(area);
    },
    true
  );
  document.addEventListener(
    'pointerleave',
    (e) => {
      const shell = e.target?.closest?.('.scrollable-buff-shell');
      if (!shell || shell.contains(e.relatedTarget)) return;
      const area = shell.querySelector('.scrollable-buff-area');
      if (area) scheduleHideScrollUi(area);
    },
    true
  );
  document.addEventListener(
    'scroll',
    (e) => {
      const area = e.target;
      if (!(area instanceof Element) || !area.classList.contains('scrollable-buff-area')) return;
      showScrollUi(area);
      syncScrollableBuffShell(area.closest('.scrollable-buff-shell'));
    },
    true
  );
  document.addEventListener('click', (e) => {
    const btn = e.target?.closest?.('[data-tba-hscroll]');
    if (!btn) return;
    const shell = btn.closest('.scrollable-buff-shell');
    const area = shell?.querySelector?.('.scrollable-buff-area');
    if (!area) return;
    e.preventDefault();
    const dir = Number(btn.dataset.tbaHscroll) || 0;
    area.scrollBy({ left: dir * getBuffScrollStep(area), behavior: 'smooth' });
    showScrollUi(area);
  });
  window.addEventListener('resize', () => {
    if (typeof window.syncScrollableBuffAreas === 'function') window.syncScrollableBuffAreas();
  });
}

function refreshScrollableBuffAreas() {
  ensureScrollableBuffAreaUx();
  ensureTbaCardHoverLiftUx();
  requestAnimationFrame(() => {
    if (typeof window.syncScrollableBuffAreas === 'function') window.syncScrollableBuffAreas();
    clearTbaCardHoverLiftSnap();
  });
}

function renderTeamBuffAssignMatrix(worksheet = false) {
  // 分配区仍含莫宁偏谐等面板同步 Buff，便于按角色开关覆盖
  const teamBuffs = ensureTeamSharedBuffs().buffs.filter((b) => !isConvergenceBuffCategory(b.category));
  if (!teamBuffs.length) return '';
  const cards = buildTeamBuffAssignSourceCards(teamBuffs);

  return `
    <div class="weapon-team-buff-matrix">
      <div class="weapon-team-buff-matrix-title">全队 Buff 分配</div>
      <p class="hint" style="margin:0 0 0.45rem">按来源角色分卡：左侧为接收角色，列为各全队 Buff。圆点勾选表示覆盖；锁表示固定不生效。可叠层 Buff 点 cell（角标旁）打开叠层设置，点圆点仍可开关覆盖。</p>
      <div class="buff-source-board">
        ${cards.map((c) => renderBuffSourceCard(c, worksheet)).join('')}
      </div>
    </div>`;
}

/** 将 resolveTeamBuffAssignCellState → BuffCell props */
function teamBuffAssignCellToBuffCellProps(b, mi, cell) {
  if (!cell || cell.kind === 'empty') {
    return { status: 'none' };
  }
  if (cell.kind === 'locked') {
    return {
      status: 'disabled',
      title: '该buff对当前角色固定不生效',
    };
  }
  const tipParts = [cell.brief || ''];
  if (cell.isStack && cell.stackTitle) tipParts.push(cell.stackTitle);
  return {
    status: cell.isStack ? 'stackable' : 'active',
    checked: !!cell.checked,
    stackCount: cell.stacks ?? 0,
    maxStacks: cell.maxStacks ?? 5,
    autoStack: !!cell.autoStack,
    buffId: b.id,
    memberIndex: mi,
    title: tipParts.filter(Boolean).join(' · '),
  };
}

/** 全队分配矩阵：某接收角色对某 Buff — 使用 BuffCell 状态指示器 */
function renderTeamBuffAssignReceiverToggle(b, mi) {
  const cell = resolveTeamBuffAssignCellState(b, mi);
  return renderBuffCell(teamBuffAssignCellToBuffCellProps(b, mi, cell));
}

/**
 * 写入某接收角色对某全队叠层 Buff 的层数（与角标读取同源）
 * 同时写入：稳定镜像 id、shared 层数、角色侧镜像 id（含 stackSync 组）
 * @returns {boolean}
 */
function applyTeamBuffAssignStackValue(memberIdx, teamBuffId, rawValue, opts = {}) {
  const member = state.members[memberIdx];
  const shared = ensureTeamSharedBuffs();
  const sharedBuff = (shared.buffs || []).find((x) => x.id === teamBuffId);
  if (!member || !sharedBuff || !isStackBuff(sharedBuff)) return false;
  const mirrorForDefault = (member.buffs || []).find((buff) => buff.teamSourceId === teamBuffId);
  if (!opts.confirmed && !isTeamFusionStackSyncBuff(sharedBuff) && !isEchoSetHarmonyAmpAtkBuff(sharedBuff) && mirrorForDefault && typeof window.__WC.changeInitialStackDefault === 'function') {
    const input = document.createElement('input');
    const popover = document.getElementById('tbaStackPopover');
    if (popover && !popover.hidden) closeTbaStackPopover({ discard: true, committed: true });
    void window.__WC.changeInitialStackDefault(member, mirrorForDefault, rawValue, input,
      (value) => applyTeamBuffAssignStackValue(memberIdx, teamBuffId, value, { confirmed: true }))
      .catch((error) => { console.error(error); window.__WC.renderMain(); });
    return false;
  }
  if (
    (typeof isTeamFusionStackSyncBuff === 'function' && isTeamFusionStackSyncBuff(sharedBuff)) ||
    (typeof isEchoSetHarmonyAmpAtkBuff === 'function' && isEchoSetHarmonyAmpAtkBuff(sharedBuff))
  ) {
    return false;
  }
  if (!member.globalBuffStacks) member.globalBuffStacks = {};
  if (!shared.globalBuffStacks) shared.globalBuffStacks = {};
  const suomingC2Tongzou = String(sharedBuff.templateKey || '') === 'suoming_c2_outro_critdmg_stack';
  const tongzouBase = suomingC2Tongzou
    ? (member.buffs || []).find(isTongzouSharedGainBuff)
    : null;
  if (suomingC2Tongzou && !tongzouBase) return false;
  const next = suomingC2Tongzou
    ? Math.min(4, normalizeStackInput(rawValue))
    : normalizeStackInput(rawValue);
  const prev =
    typeof readTeamBuffAssignStackCount === 'function'
      ? readTeamBuffAssignStackCount(sharedBuff, memberIdx)
      : undefined;
  const mirrorId = makeTeamMirrorBuffId(teamBuffId);

  // 同奏层数只写当前接收角色；普通全队 Buff 仍写共享层数。
  member.globalBuffStacks[mirrorId] = next;
  const memberScopedTongzou =
    isTongzouSharedGainBuff(sharedBuff) || isTongzouLayerLinkedBuff(sharedBuff);
  if (!memberScopedTongzou) shared.globalBuffStacks[teamBuffId] = next;

  const mirror = (member.buffs || []).find((b) => b.teamSourceId === teamBuffId);
  if (mirror) {
    // 显式写 mirror.id，避免仅写 tm_* 后读路径仍命中旧 0
    member.globalBuffStacks[mirror.id] = next;
    if (!memberScopedTongzou && typeof writeStackMapForSyncGroup === 'function') {
      writeStackMapForSyncGroup(member, mirror, member.globalBuffStacks, next);
    }
  }

  // 这条暴伤挂在接收者身上：玩家改它时，写回该接收者自己的同奏层数。
  // 原同奏 5/6 层只让暴伤按 4 层计算；未实际改动暴伤时不把本体压回 4 层。
  if (suomingC2Tongzou && next !== prev) {
    const baseId = makeTeamMirrorBuffId(TONGZOU_SHARED_GAIN_ID);
    member.globalBuffStacks[tongzouBase.id] = next;
    member.globalBuffStacks[baseId] = next;
  }

  console.log('[应用叠层]', {
    buffId: teamBuffId,
    memberIdx,
    prev,
    next,
    mirrorId,
    mirrorBuffId: mirror?.id || null,
    memberStacks: { ...member.globalBuffStacks },
    sharedStacks: shared.globalBuffStacks[teamBuffId],
    badgeShouldShow: next > 0,
  });

  if (typeof isFeixueXuexiuStackSyncBuff === 'function' && isFeixueXuexiuStackSyncBuff(sharedBuff)) {
    // 绯雪：全队雪锈层数同步写入个人雪锈（个人为主源），再整体同步镜像与特殊技能
    const personalSnow = (member.buffs || []).find(
      (b) => String(b.templateKey || '') === FEIXUE_XUEXIU_KEY
    );
    if (personalSnow) {
      if (!member.globalBuffStacks) member.globalBuffStacks = {};
      member.globalBuffStacks[personalSnow.id] = next;
    }
    syncFeixueXuexiuLinkedBuffs();
  }
  if (memberScopedTongzou) syncTongzouLinkedStacksToMembers();
  if (typeof persistCycleEditingIfEnabled === 'function') persistCycleEditingIfEnabled(member);
  return true;
}

/** 叠层设置小面板（单例，挂 body） */
function ensureTbaStackPopover() {
  let el = document.getElementById('tbaStackPopover');
  if (el && (!el.querySelector('[data-tba-stack-slider]') || !el.querySelector('[data-tba-stack-close-hint]'))) {
    el.remove();
    el = null;
  }
  if (el) return el;
  el = document.createElement('div');
  el.id = 'tbaStackPopover';
  el.className = 'tba-stack-popover';
  el.hidden = true;
  el.setAttribute('role', 'dialog');
  el.setAttribute('aria-label', '叠层设置');
  el.innerHTML = `
    <div class="tba-stack-popover__title">叠层设置</div>
    <div class="tba-stack-popover__progress">
      <div class="tba-stack-popover__bar" aria-hidden="true"><i data-tba-stack-bar></i></div>
      <span class="tba-stack-popover__ratio" data-tba-stack-ratio>0/1</span>
    </div>
    <div class="tba-stack-popover__stepper">
      <button type="button" class="tba-stack-popover__btn" data-tba-stack-delta="-1" aria-label="减少">−</button>
      <input type="number" class="tba-stack-popover__value" data-tba-stack-value min="0" step="1" />
      <button type="button" class="tba-stack-popover__btn" data-tba-stack-delta="1" aria-label="增加">+</button>
    </div>
    <input type="range" class="tba-stack-popover__slider" data-tba-stack-slider min="0" max="1" step="1" aria-label="叠层滑块" />
    <p class="tba-stack-popover__hint hint" data-tba-stack-hint hidden></p>
    <button type="button" class="tba-stack-popover__apply" data-tba-stack-apply>应用</button>
    <p class="tba-stack-popover__hint hint" data-tba-stack-close-hint>关闭面板也会保存当前层数</p>
  `;
  document.body.appendChild(el);
  return el;
}

function normalizeTbaStackPopoverValue(el, value) {
  const buff = ensureTeamSharedBuffs().buffs.find((b) => b.id === el.dataset.buffId);
  const next = Math.max(0, normalizeStackInput(value, buff));
  return String(buff?.templateKey || '') === 'suoming_c2_outro_critdmg_stack'
    ? Math.min(4, next)
    : next;
}

function syncTbaStackPopoverView(value, maxStacks, opts = {}) {
  const el = ensureTbaStackPopover();
  const max = Math.max(1, Number(maxStacks) || Number(el.dataset.maxStacks) || 1);
  const v = normalizeTbaStackPopoverValue(el, value);
  const input = el.querySelector('[data-tba-stack-value]');
  const slider = el.querySelector('[data-tba-stack-slider]');
  const ratio = el.querySelector('[data-tba-stack-ratio]');
  const bar = el.querySelector('[data-tba-stack-bar]');
  if (input) input.value = String(v);
  if (slider) {
    slider.max = String(max);
    slider.value = String(Math.min(v, max));
  }
  if (ratio) ratio.textContent = `${v}/${max}`;
  if (bar) {
    const pct = Math.max(0, Math.min(100, (v / max) * 100));
    bar.style.width = `${pct}%`;
  }
  el.dataset.draft = String(v);

  // 面板改层时同步预览卡片角标（关闭面板会自动保存草稿）
  if (opts.previewBadge && el.dataset.buffId && el.dataset.autoStack !== '1') {
    console.log('[叠层面板] 修改层数:', el.dataset.buffId, v);
    updateTeamBuffAssignStackBadge(el.dataset.buffId, el.dataset.memberIndex, v, {
      silent: !!opts.silentBadge,
    });
  }
}

function positionTbaStackPopover(anchor) {
  const el = ensureTbaStackPopover();
  const rect = anchor.getBoundingClientRect();
  const pad = 8;
  const width = 220;
  el.style.width = `${width}px`;
  el.hidden = false;
  const h = el.offsetHeight || 160;
  let left = rect.left + rect.width / 2 - width / 2;
  let top = rect.bottom + 6;
  left = Math.max(pad, Math.min(left, window.innerWidth - width - pad));
  if (top + h + pad > window.innerHeight) {
    top = Math.max(pad, rect.top - h - 6);
  }
  el.style.left = `${Math.round(left)}px`;
  el.style.top = `${Math.round(top)}px`;
}

/**
 * 关闭叠层面板。
 * 默认：把当前草稿写入 state（选层即保存）；opts.discard 才回滚预览。
 * @returns {{ committed?: boolean, stacks?: number }|undefined}
 */
function closeTbaStackPopover(opts = {}) {
  const el = document.getElementById('tbaStackPopover');
  if (!el) return undefined;
  const buffId = el.dataset.buffId;
  const memberIndex = parseInt(el.dataset.memberIndex, 10);
  const alreadyCommitted = el.dataset.committing === '1' || !!opts.committed;
  let result;

  if (!alreadyCommitted && !opts.discard && el.dataset.autoStack !== '1' && buffId && Number.isFinite(memberIndex)) {
    // 关闭即保存：解决「改了层数但没点应用 → 回滚成默认图标」
    const input = el.querySelector('[data-tba-stack-value]');
    const rawInput = input?.value;
    const next = normalizeTbaStackPopoverValue(el,
      rawInput !== undefined && rawInput !== '' ? rawInput : el.dataset.draft ?? 0
    );
    el.dataset.committing = '1';
    console.log('[叠层面板] 关闭时自动保存层数:', buffId, next);
    if (applyTeamBuffAssignStackValue(memberIndex, buffId, next)) {
      updateTeamBuffAssignStackBadge(buffId, memberIndex, next);
      if (typeof saveState === 'function') void Promise.resolve(saveState()).catch(() => {});
      else if (typeof scheduleSave === 'function') scheduleSave();
      result = { committed: true, buffId, memberIndex, stacks: next };
    }
  } else if (opts.discard && !alreadyCommitted && buffId && Number.isFinite(memberIndex)) {
    const sharedBuff = ensureTeamSharedBuffs().buffs.find((x) => x.id === buffId);
    if (sharedBuff) {
      const restored = readTeamBuffAssignStackCount(sharedBuff, memberIndex);
      console.log('[叠层面板] 丢弃草稿，角标回滚:', buffId, restored);
      updateTeamBuffAssignStackBadge(buffId, memberIndex, restored, { silent: true });
    }
  }

  el.hidden = true;
  delete el.dataset.buffId;
  delete el.dataset.memberIndex;
  delete el.dataset.maxStacks;
  delete el.dataset.autoStack;
  delete el.dataset.draft;
  delete el.dataset.committing;
  return result;
}

function closeTbaStackPopoverIfOutside(target) {
  const el = document.getElementById('tbaStackPopover');
  if (!el || el.hidden) return undefined;
  // 点「应用」由专门分支处理
  if (target?.closest?.('[data-tba-stack-apply]')) return undefined;
  if (el.contains(target)) return undefined;
  const openAnchor = target?.closest?.('[data-tba-stack-open]');
  // 同一角标再次点击：留给 open 做开关（open 内 close 会自动保存）
  if (
    openAnchor &&
    openAnchor.dataset.tbaStackOpen === el.dataset.buffId &&
    String(openAnchor.dataset.memberIndex) === String(el.dataset.memberIndex)
  ) {
    return undefined;
  }
  return closeTbaStackPopover();
}

function openTbaStackPopover(anchor) {
  const buffId = anchor?.dataset?.tbaStackOpen || '';
  const memberIndex = parseInt(anchor?.dataset?.memberIndex, 10);
  if (!buffId || !Number.isFinite(memberIndex)) return;
  const existing = document.getElementById('tbaStackPopover');
  if (
    existing &&
    !existing.hidden &&
    existing.dataset.buffId === buffId &&
    existing.dataset.memberIndex === String(memberIndex)
  ) {
    closeTbaStackPopover();
    return;
  }
  const sharedBuff = ensureTeamSharedBuffs().buffs.find((x) => x.id === buffId);
  if (!sharedBuff || !isStackBuff(sharedBuff)) return;

  const cell = resolveTeamBuffAssignCellState(sharedBuff, memberIndex);
  const maxStacks = Math.max(1, Number(anchor.dataset.tbaMaxStacks) || cell.maxStacks || sharedBuff.maxStacks || 5);
  const autoStack = anchor.dataset.tbaAutoStack === '1' || !!cell.autoStack;
  const stacks = cell.stacks ?? 0;

  const el = ensureTbaStackPopover();
  el.dataset.buffId = buffId;
  el.dataset.memberIndex = String(memberIndex);
  el.dataset.maxStacks = String(maxStacks);
  el.dataset.autoStack = autoStack ? '1' : '0';

  const hint = el.querySelector('[data-tba-stack-hint]');
  const closeHint = el.querySelector('[data-tba-stack-close-hint]');
  const applyBtn = el.querySelector('[data-tba-stack-apply]');
  const steppers = el.querySelectorAll('[data-tba-stack-delta], [data-tba-stack-value], [data-tba-stack-slider]');
  if (autoStack) {
    if (hint) {
      hint.hidden = false;
      hint.textContent = '自动同步层数（只读）';
    }
    if (closeHint) closeHint.hidden = true;
    if (applyBtn) applyBtn.hidden = true;
    steppers.forEach((node) => {
      if (node.matches('input[type="number"]')) node.readOnly = true;
      else node.disabled = true;
    });
  } else {
    if (hint) {
      hint.hidden = true;
      hint.textContent = '';
    }
    if (closeHint) closeHint.hidden = false;
    if (applyBtn) applyBtn.hidden = false;
    steppers.forEach((node) => {
      if (node.matches('input[type="number"]')) node.readOnly = false;
      else node.disabled = false;
    });
  }

  syncTbaStackPopoverView(stacks, maxStacks);
  positionTbaStackPopover(anchor);
  requestAnimationFrame(() => {
    if (!autoStack) el.querySelector('[data-tba-stack-value]')?.focus();
  });
}

function adjustTbaStackPopoverDraft(delta) {
  const el = ensureTbaStackPopover();
  if (el.hidden || el.dataset.autoStack === '1') return;
  const max = Math.max(1, Number(el.dataset.maxStacks) || 5);
  const input = el.querySelector('[data-tba-stack-value]');
  const cur = normalizeStackInput(input?.value ?? el.dataset.draft ?? 0);
  const next = Math.max(0, cur + Number(delta || 0));
  syncTbaStackPopoverView(next, max, { previewBadge: true });
  if (input) input.value = el.dataset.draft;
}

function commitTbaStackPopover() {
  const el = ensureTbaStackPopover();
  if (el.hidden || el.dataset.autoStack === '1') return false;
  const buffId = el.dataset.buffId;
  const memberIndex = parseInt(el.dataset.memberIndex, 10);
  const input = el.querySelector('[data-tba-stack-value]');
  // 以 draft 为准（预览同源）；input 空串时勿当成 0 覆盖已预览层数
  const rawInput = input?.value;
  const rawDraft = el.dataset.draft;
  const next = normalizeTbaStackPopoverValue(el,
    rawInput !== undefined && rawInput !== '' ? rawInput : rawDraft ?? 0
  );
  console.log('[应用前]', {
    buffId,
    memberIndex,
    stackCount: next,
    inputValue: rawInput,
    draft: rawDraft,
  });
  el.dataset.committing = '1';
  const ok = applyTeamBuffAssignStackValue(memberIndex, buffId, next);
  if (ok) {
    updateTeamBuffAssignStackBadge(buffId, memberIndex, next);
    console.log('[应用后] 角标应显示:', next > 0, `x${next}`);
    if (typeof saveState === 'function') {
      void Promise.resolve(saveState()).catch(() => {});
    } else if (typeof scheduleSave === 'function') {
      scheduleSave();
    }
    closeTbaStackPopover({ committed: true });
    return { buffId, memberIndex, stacks: next };
  }
  delete el.dataset.committing;
  closeTbaStackPopover({ discard: true });
  return false;
}

/** 延迟全量重绘，避免打断圆点/角标过渡动画 */
function scheduleTeamBuffAssignRerender(delayMs) {
  const ms = Math.max(0, Number(delayMs) || 0);
  if (typeof window === 'undefined') return;
  // 立即抓取横向滚动，避免延迟期间或重绘后丢失
  if (typeof captureMainScrollState === 'function') {
    window.__tbaAssignScrollSaved = captureMainScrollState();
  }
  clearTimeout(window.__tbaAssignRenderTimer);
  window.__tbaAssignRenderTimer = setTimeout(() => {
    const saved = window.__tbaAssignScrollSaved;
    window.__tbaAssignScrollSaved = null;
    if (typeof renderMain === 'function') renderMain(saved);
    else if (typeof render === 'function') render(saved ? { scrollSaved: saved } : undefined);
    if (typeof refreshScrollableBuffAreas === 'function') refreshScrollableBuffAreas();
    // 箭头显隐刷新后再次写回 scrollLeft（布局可能刚变）
    if (saved?.tbaHScroll && typeof restoreMainScrollState === 'function') {
      requestAnimationFrame(() => restoreMainScrollState(saved));
    }
    // 重绘后去掉 snap，下次真正滑入卡片时再播抬起过渡
    requestAnimationFrame(() => {
      if (typeof clearTbaCardHoverLiftSnap === 'function') clearTbaCardHoverLiftSnap();
    });
  }, ms);
}

function teamBuffAssignShortName(b) {
  const raw = String(b?.name || '全队Buff');
  if (isEchoManagedBuff(b)) {
    const body = getEchoBuffSimplifiedBody(b) || stripManagedBuffSourcePrefixes(raw);
    return `【声骸】${body}`;
  }
  const base = stripManagedBuffSourcePrefixes(raw);
  if (b?.weaponTeamBuff || /^\[武器\]/.test(raw) || /^【武器】/.test(raw)) return `【武器】${base}`;
  if (typeof isCharacterTemplateBuff === 'function' && isCharacterTemplateBuff(b)) {
    return `【本体】${base}`;
  }
  return base || '全队Buff';
}

function renderTeamBuffAssignMemberAvatar(mi) {
  const m = state.members[mi];
  const charDef = m?.characterId ? findCharSkillDef(m.characterId) : null;
  const portrait = charDef
    ? renderCharAvatarCard(charDef)
    : `<div class="char-avatar-card"><span class="char-avatar-fallback" style="display:flex;background:linear-gradient(135deg,#3a4a5c,#2a3544)">?</span></div>`;
  const name = m?.name || charDef?.name || `角色${mi + 1}`;
  return `
    <div class="team-buff-assign-avatar" title="${escapeHtml(name)}">
      ${portrait}
      <span class="team-buff-assign-avatar-name">${escapeHtml(name)}</span>
    </div>`;
}

/**
 * 表头分组：[{ key, label, buffs }]
 * 来源角色 0/1/2 + 无归属；无 Buff 的来源角色仍占 1 列占位
 */
function buildTeamBuffAssignGroups(teamBuffs) {
  const groups = [
    { key: 'src0', label: '', buffs: [] },
    { key: 'src1', label: '', buffs: [] },
    { key: 'src2', label: '', buffs: [] },
  ];
  [0, 1, 2].forEach((i) => {
    const m = state.members[i];
    const name = m?.name || `角色${i + 1}`;
    groups[i].label = `角色${i + 1} · ${name}`;
  });
  const orphan = { key: 'orphan', label: '无归属 / 其他来源', buffs: [] };
  teamBuffs.forEach((b) => {
    const src = getTeamBuffSourceMemberIndex(b);
    if (src != null && src >= 0 && src <= 2) groups[src].buffs.push(b);
    else orphan.buffs.push(b);
  });
  const out = groups.map((g) => ({
    ...g,
    // 无 Buff 时第二行放一列「—」占位，保持三角色来源列始终可见
    colSpan: Math.max(1, g.buffs.length),
    placeholder: g.buffs.length === 0,
  }));
  if (orphan.buffs.length) {
    out.push({
      ...orphan,
      colSpan: orphan.buffs.length,
      placeholder: false,
    });
  }
  return out;
}

/** 为全队 Buff 选中对应编辑页签（大类 + 子类） */
function resolveTeamBuffEditorTab(buff) {
  if (!buff) return null;
  for (const [gk, g] of Object.entries(TEAM_BUFF_TAB_GROUPS)) {
    for (const cat of g.cats || []) {
      if (buffBelongsToEditorTab(buff, cat)) return { group: gk, tab: cat };
    }
  }
  return {
    group: getBuffGroupForCategory(buff.category, TEAM_BUFF_TAB_GROUPS),
    tab: buff.category,
  };
}

/** 点击分配表表头后，切到该 Buff 来源编辑行并滚动高亮 */
function focusTeamBuffEditorRow(teamBuffId, opts = {}) {
  const shared = ensureTeamSharedBuffs();
  const b = (shared.buffs || []).find((x) => x.id === teamBuffId);
  if (!b || isConvergenceBuffCategory(b.category)) return false;
  const resolved = resolveTeamBuffEditorTab(b);
  if (resolved) {
    shared.activeBuffGroup = resolved.group;
    shared.activeBuffTab = resolved.tab;
  }
  shared.expanded = true;
  shared._pendingFocusBuffId = teamBuffId;
  if (opts.skipRender) return true;
  if (typeof refreshOpenBuffEditors === 'function') refreshOpenBuffEditors();
  else if (typeof renderMain === 'function') renderMain();
  return true;
}

function applyPendingTeamBuffEditorFocus() {
  const shared = ensureTeamSharedBuffs();
  const id = shared._pendingFocusBuffId;
  if (!id) return;
  delete shared._pendingFocusBuffId;
  requestAnimationFrame(() => {
    const list = document.querySelectorAll('.team-shared-buff-section [data-buff-row]');
    let el = null;
    list.forEach((node) => {
      if (node.getAttribute('data-buff-row') === String(id)) el = node;
    });
    if (!el) return;
    el.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    el.classList.add('buff-row-focus');
    setTimeout(() => el.classList.remove('buff-row-focus'), 1400);
  });
}

/** 自动同步层数（只读）的全队叠层 Buff：露帕荣光（按队内热熔人数）、声骸套装谐幅攻击。
 *  绯雪【雪锈】已改为各角色独立层数，不在此列。 */
function isAutoSyncedTeamStackBuff(b) {
  return (
    !!(typeof isTeamFusionStackSyncBuff === 'function' && isTeamFusionStackSyncBuff(b)) ||
    !!(typeof isEchoSetHarmonyAmpAtkBuff === 'function' && isEchoSetHarmonyAmpAtkBuff(b))
  );
}

function renderTeamSharedBuffPanel(worksheet = false) {
  const shared = ensureTeamSharedBuffs();
  syncMemberBuffTabs(shared, TEAM_BUFF_TAB_GROUPS);
  const inspect = typeof ensureCheckInspectState === 'function' ? ensureCheckInspectState() : null;
  const sourceExpanded = !!(inspect && inspect.teamSourceExpanded);
  const group = TEAM_BUFF_TAB_GROUPS[shared.activeBuffGroup] || TEAM_BUFF_TAB_GROUPS.bonus;
  const groupCats = group.cats;
  const tabBuffs = shared.buffs.filter(
    (b) =>
      !isConvergenceBuffCategory(b.category) &&
      !isHiddenPanelSyncedBuff(b) &&
      buffBelongsToEditorTab(b, shared.activeBuffTab)
  );
  const showBuffType = isTypedBuffCategory(shared.activeBuffTab);
  const showDefenseKind = isDefenseBuffCategory(shared.activeBuffTab);
  const listHtml = tabBuffs.length
    ? tabBuffs.map((b) => renderBuffEditorRow(b, { scope: 'team', showBuffType, showDefenseKind })).join('')
    : '<span class="hint">暂无全队来源，添加后将自动同步到 3 个角色 Buff 库</span>';

  const secTitle =
    typeof renderSetupSecTitle === 'function'
      ? (label) => renderSetupSecTitle(label)
      : (label) => `<div class="setup-sec-title"><span class="setup-sec-mark" aria-hidden="true"></span><span>${escapeHtml(label)}</span></div>`;

  return `
    <section class="team-shared-buff-section buff-check-team-card">
      <div class="buff-check-team-card-head">
        <i data-lucide="users" class="buff-check-team-icon" aria-hidden="true"></i>
        <span class="buff-check-team-title">${worksheet ? '提供的全队 Buff' : '全队<span class="nav-term">Buff</span>'}</span>
        <span class="hint buff-check-team-hint" title="点击 Buff 名可跳转到来源编辑；可叠层 Buff 点 cell 打开叠层设置">分配覆盖 · 叠层点角标旁打开</span>
      </div>
      <div class="team-shared-buff-body">
        <div class="buff-check-block">
          ${secTitle('全队Buff分配')}
          <div class="buff-check-matrix-wrap">${renderTeamBuffAssignMatrix(worksheet)}</div>
        </div>
        <div class="buff-check-block buff-check-source-block">
          <div class="buff-check-source-head">
            ${secTitle(worksheet ? '公共来源管理' : 'Buff来源')}
            <button type="button" class="buff-check-source-toggle" data-team-buff-source-toggle aria-expanded="${sourceExpanded ? 'true' : 'false'}">${sourceExpanded ? '收起' : '展开详细'}</button>
            <span class="buff-check-source-hint">若有 buff 未添加，请在展开详细，手动添加 buff，然后向我们反馈缺失的 buff</span>
          </div>
          ${sourceExpanded ? '<div class="buff-check-source-panel">' : '<div class="buff-check-source-panel is-collapsed">'}
            <div class="buff-group-tabs buff-check-group-tabs buff-group-tabs--scroll category-tabs" role="tablist" aria-label="Buff一级分类">
          ${Object.entries(TEAM_BUFF_TAB_GROUPS)
            .map(
              ([gk, g]) =>
                    `<button type="button" class="buff-group-tab category-tab ${shared.activeBuffGroup === gk ? 'active' : ''}" data-team-buff-group-tab="${gk}">${g.label}</button>`
            )
            .join('')}
        </div>
        ${renderBuffSubTabs(shared.activeBuffTab, groupCats, 'data-team-buff-tab')}
        <div class="buff-list" data-team-buff-editor-list>${listHtml}</div>
            <div class="buff-source-footer">
              <details class="help-text buff-source-help">
                <summary class="help-text__summary">
                  <span class="help-text__summary-text">每条可选手填来源角色</span>
                  <span class="help-text__q" title="查看完整说明" aria-hidden="true">?</span>
                </summary>
                <div class="help-text__body">
                  <p>每条可选手填「来源角色」；武器/套装/声骸自动生成的 Buff 会锁定来源。叠层层数在覆盖表中按角色独立保存；来源页叠层 badge 也可直接调整。</p>
        ${
          ELEMENT_TYPED_BUFF_CATS.has(shared.activeBuffTab)
                      ? `<p><strong>${escapeHtml(BUFF_CATS[shared.activeBuffTab].label)}</strong>可选具体属性，或选<strong>泛用</strong>（全伤害生效）。</p>`
            : ''
        }
        ${
          shared.activeBuffTab === 'extraVulnerability'
                      ? '<p><strong>额外易伤区</strong>为独立乘区（易伤区2），在易伤区1之后再乘算。</p>'
                      : ''
                  }
                  ${
                    shared.activeBuffTab === 'harmonyBreakAmp'
                      ? '<p><strong>谐度破坏增幅</strong>为点数；同步到各角色后计入总和。</p>'
                      : ''
                  }
      </div>
              </details>
              <button class="add-buff-btn" data-add-team-buff type="button">+ 添加${escapeHtml(BUFF_CATS[shared.activeBuffTab].label)}</button>
            </div>
          </div>
        </div>
      </div>
    </section>`;
}

function createTeamState() {
  return {
    sidebarTab: 'build',
    team: {
      axisDuration: 20,
      monsterRes: 20,
      monsterLevel: 100,
      activeIndex: 0,
      viewMode: 'member',
      sharedBuffs: defaultTeamSharedBuffs(),
    },
    members: [createMemberWithDefaults(0), createEmptyMember(1), createEmptyMember(2)],
    specialSkills: defaultSpecialSkillsState(),
    teamResults: { total: 0, dps: 0, breakdown: [] },
    schemeDraft: { name: '未命名方案', author: '' },
    exportCardDraft: {
      axisName: '未命名轴',
      axisLength: 20,
      difficulty: '',
      performance: '',
      axisKind: '',
      shareCode: '（网页上线后生成）',
    },
    refVideoUrl: '',
    calcNotes: '',
    charPickerElement: 'all',
    charPickerRank5Only: false,
    charPickerPreviewId: null,
    weaponPickerSearch: '',
    weaponPickerPreviewId: null,
    weaponPickerPreviewRefinement: 1,
    weaponPickerSort: 'atk',
    weaponPickerGroupCollapsed: { r5: false, r4: false, other: false },
    buildModal: null,
    /** setup=配装；buff=Buff检查；axis=编轴；calc=计算；check=检查 */
    workspacePhase: 'setup',
    /** 编轴页仅时间可视化（旧字段保留兼容存档） */
    axisTimeViz: true,
    /** 时间可视化合并点选：{ active, memberIndex } */
    axisMergePick: null,
    /** tabs=方案A；columns=方案B（三栏同屏，逻辑不变只改布局） */
    setupLayout: 'tabs',
    buffDrawer: { open: false, width: 400 },
    checkInspect: defaultCheckInspectState(),
    charBuffTplUi: defaultCharBuffTplUi(),
    /** 导出页：用户手动确认保存的链/精配置快照（对照表） */
    exportConfigSnapshots: [],
    /** Buff 游戏原文案：编辑模式 / 悬停展示 */
    buffGameTextUi: { editMode: false },
  };
}

function ensureBuffGameTextUi() {
  if (!state.buffGameTextUi || typeof state.buffGameTextUi !== 'object') {
    state.buffGameTextUi = { editMode: false };
  }
  state.buffGameTextUi.editMode = !!state.buffGameTextUi.editMode;
  return state.buffGameTextUi;
}

function defaultCheckInspectState() {
  return {
    zoneId: 'all',
    focusBuffId: null,
    teamCollapsed: false,
    personalCollapsed: false,
    teamSourceExpanded: false,
    ctxMenu: null,
    verifyPaintHeld: false,
  };
}

function ensureCheckInspectState() {
  if (!state.checkInspect) state.checkInspect = defaultCheckInspectState();
  const c = state.checkInspect;
  // 旧版「双暴 / 复合」乘区已拆分或取消
  if (c.zoneId === 'crit' || c.zoneId === 'composite') c.zoneId = 'all';
  const known =
    c.zoneId === 'all' || BUFF_DAMAGE_ZONE_GROUPS.some((z) => z.id === c.zoneId);
  if (!known) c.zoneId = 'all';
  if (c.focusBuffId != null) c.focusBuffId = String(c.focusBuffId);
  c.teamCollapsed = !!c.teamCollapsed;
  c.personalCollapsed = !!c.personalCollapsed;
  c.teamSourceExpanded = !!c.teamSourceExpanded;
  if (c.ctxMenu && typeof c.ctxMenu !== 'object') c.ctxMenu = null;
  return c;
}

function normalizeWorkspacePhase(phase) {
  // 旧存档「编轴」页 = 现「计算」页（时间线/Buff）
  if (phase === 'rotation') return 'calc';
  if (
    phase === 'buff' ||
    phase === 'axis' ||
    phase === 'calc' ||
    phase === 'check' ||
    phase === 'overview' ||
    phase === 'export' ||
    phase === 'template'
  ) {
    return phase;
  }
  return 'setup';
}

function normalizeSetupLayout(layout) {
  return layout === 'columns' ? 'columns' : 'tabs';
}

function getWorkspacePhase() {
  if (isSpecialView()) return 'calc';
  return normalizeWorkspacePhase(state.workspacePhase);
}

function isAxisWorkspacePhase(phase) {
  return normalizeWorkspacePhase(phase || getWorkspacePhase()) === 'axis';
}

function isCalcWorkspacePhase(phase) {
  return normalizeWorkspacePhase(phase || getWorkspacePhase()) === 'calc';
}

function getSetupLayout() {
  return normalizeSetupLayout(state.setupLayout);
}

function setWorkspacePhase(phase) {
  const prev = normalizeWorkspacePhase(state.workspacePhase);
  state.workspacePhase = normalizeWorkspacePhase(phase);
  // 特殊技能只挂在计算页；离开计算时退出特殊视图，避免其他阶段主区仍被特殊技能占住
  if (state.workspacePhase !== 'calc' && state.team?.viewMode === 'special') {
    state.team.viewMode = 'member';
  }
  if (state.workspacePhase !== 'axis' && state.axisMergePick) {
    state.axisMergePick = null;
  }
  if (state.workspacePhase === 'axis' && prev !== 'axis') {
    if (typeof ensureAllMembersAxisOffsets === 'function') {
      ensureAllMembersAxisOffsets();
    }
  }
  const tplUi = ensureCharBuffTplUi();
  if (state.workspacePhase === 'template') {
    tplUi.open = true;
    if (!tplUi.characterId) {
      const member = getActiveMember();
      if (member?.characterId) tplUi.characterId = String(member.characterId);
    }
    if (tplUi.characterId) getCharBuffTplDraft();
    state.buildModal = null;
    state.buffDrawer = { ...(state.buffDrawer || { open: false, width: 400 }), open: false };
  } else {
    tplUi.open = false;
    if (state.workspacePhase === 'setup') state.buildModal = null;
  }
  if (state.workspacePhase !== 'calc' && state.workspacePhase !== 'template') {
    state.buffDrawer = { ...(state.buffDrawer || { open: false, width: 400 }), open: false };
  }
  // 编轴与计算时间线分离：进入计算/检查不再自动入轴，需在计算页手动「入轴」
  if (state.workspacePhase === 'check' || state.workspacePhase === 'export') {
    const member = getActiveMember();
    if (member) {
      // 仅自动关掉类型不匹配的指定 Buff；勿 restoreMatches，否则会清掉检查矩阵的单技能勾选
      syncMemberSkillsTypedBuffAutoMatch(member, { restoreMatches: false });
      persistCycleEditingIfEnabled(member);
    }
    if (state.workspacePhase === 'export' && typeof computeAll === 'function') {
      computeAll();
    }
  } else {
    const inspect = ensureCheckInspectState();
    inspect.focusBuffId = null;
  }
}

const state = createTeamState();
let replaceCatalogTargetId = null;

function cloneBuffsWithNewIds(buffs, globalBuffActive, globalBuffStacks) {
  const idMap = {};
  const newBuffs = (buffs || []).map((b) => {
    const newId = genId();
    idMap[b.id] = newId;
    if (b?.category === 'composite') {
      return normalizeBuff({
        ...b,
        id: newId,
        effects: (b.effects || []).map((e) => ({
          ...e,
          id: genId(),
          segments: (e.segments || []).map((s) => ({ ...s })),
          skillNames: [...(e.skillNames || [])],
          catalogIds: [...(e.catalogIds || [])],
        })),
      });
    }
    return {
      ...b,
      id: newId,
      damageType: b.damageType || '',
      defenseKind: b.defenseKind || (DEFENSE_BUFF_CATS.has(b.category) ? 'pen' : ''),
    };
  });
  const newActive = {};
  Object.entries(globalBuffActive || {}).forEach(([oldId, val]) => {
    if (idMap[oldId] !== undefined) newActive[idMap[oldId]] = val;
  });
  const newStacks = {};
  Object.entries(globalBuffStacks || {}).forEach(([oldId, val]) => {
    if (idMap[oldId] !== undefined) newStacks[idMap[oldId]] = val;
  });
  return { buffs: newBuffs, globalBuffActive: newActive, globalBuffStacks: newStacks, idMap };
}

function clearMemberBuffStackOverrides(member) {
  member.rotationCatalog.forEach((item) => {
    item.stackLayers = {};
  });
  const cfg = normalizeCycleConfig(member.cycleConfig);
  cfg.rounds.forEach((round) => {
    Object.keys(round.catalogStacks || {}).forEach((catalogId) => {
      round.catalogStacks[catalogId] = {};
    });
  });
  member.cycleConfig = cfg;
  member.phases.forEach((phase) => {
    phase.buffActive = {};
    phase.buffStacks = {};
    (phase.skills || []).forEach((skill) => {
      skill.buffActive = {};
      skill.buffStacks = {};
      skill.frozenBuffActive = {};
      skill.frozenBuffStacks = {};
      (skill.hits || []).forEach((hit) => {
        hit.buffActive = {};
        hit.buffStacks = {};
        hit.frozenBuffActive = {};
        hit.frozenBuffStacks = {};
      });
    });
  });
}

function copyMemberPanelAndBuffs(sourceIndex, targetIndex) {
  if (sourceIndex === targetIndex) return false;
  const source = state.members[sourceIndex];
  const target = state.members[targetIndex];
  if (!source || !target) return false;
  ensureMemberUiState(source);
  ensureMemberUiState(target);

  target.char = cloneCharPanelForCopy(source.char);
  const sourceBuffs = source.buffs.filter((b) => !b.teamSourceId);
  const cloned = cloneBuffsWithNewIds(sourceBuffs, source.globalBuffActive, source.globalBuffStacks);
  target.buffs = cloned.buffs;
  target.globalBuffActive = cloned.globalBuffActive;
  target.globalBuffStacks = cloned.globalBuffStacks;
  target.activeBuffTab = source.activeBuffTab;
  target.activeBuffGroup = source.activeBuffGroup || getBuffGroupForCategory(source.activeBuffTab);
  target.charStatExpanded = {
    atkPercent: !!source.charStatExpanded?.atkPercent,
    critRate: !!source.charStatExpanded?.critRate,
    critDmg: !!source.charStatExpanded?.critDmg,
  };
  target.excludedTeamBuffIds = [...(source.excludedTeamBuffIds || [])];
  target.manuallyExcludedTeamBuffIds = [...(source.manuallyExcludedTeamBuffIds || [])];
  syncEchoLoadout(target);
  if (target.weaponSelection?.id) syncWeaponToMember(target, { silent: true });
  if (typeof syncCharBranchPanelSources === 'function') syncCharBranchPanelSources(target);
  if (typeof syncMoningOffsetHarmonyEffToAllPanels === 'function') {
    syncMoningOffsetHarmonyEffToAllPanels();
  }
  if (typeof syncRococoFlatAtkToAllPanels === 'function') {
    syncRococoFlatAtkToAllPanels();
  }
  if (typeof syncJingranHpFlatAtkPanel === 'function') syncJingranHpFlatAtkPanel(target);
  if (typeof syncBrantErFlatAtkPanelPreview === 'function') syncBrantErFlatAtkPanelPreview(target);
  target.seeded = true;

  clearMemberBuffStackOverrides(target);
  normalizeMemberBuffKeys(target);
  syncTeamBuffsToMembers();
  return true;
}

function isProtectedPanelSource(item) {
  if (
    isEchoPanelSource(item) ||
    isWeaponPanelSource(item) ||
    isCharDefPanelSource(item) ||
    isCharKitPanelSource(item) ||
    isLockedCharPanelBaseSource(item)
  ) {
    return true;
  }
  // normalize 后可能丢掉 locked：仍按固定托管名排除，避免复制带入孤儿行
  const name = String(item?.name || '').trim();
  if (typeof ECHO_SOURCE_NAME !== 'undefined' && name === ECHO_SOURCE_NAME) return true;
  if (name.startsWith('[武器副词条]') || name.startsWith('[武器被动]')) return true;
  if (name === '分支' || name === '1链' || name === '莫宁' || name === '莫宁·2链' || name === '阳变阴合') {
    return true;
  }
  if (/（默认）$/.test(name)) return true;
  return false;
}

/** 角色本体谐幅写入面板来源（不进个人 Buff 列表，避免重复展示） */
function upsertCharDefHarmonyBreakAmpSource(char, opts = {}) {
  if (!char) return;
  const key = charStatSourcesKey('harmonyBreakAmp');
  const list = Array.isArray(char[key]) ? char[key] : [];
  const others = list.filter((s) => {
    if (isCharDefPanelSource(s)) return false;
    // normalize 可能塞入的空「来源1」占位，有本体属性时清掉
    if (String(s?.name || '').trim() === '来源1' && !(Number(s?.value) || 0)) return false;
    return true;
  });
  const val = Number(opts.value) || 0;
  if (val <= 0) {
    char[key] = others;
    return;
  }
  others.unshift({
    id: CHAR_DEF_HARMONY_BREAK_AMP_SOURCE_ID,
    name: opts.name || '角色本体属性·谐度破坏增幅',
    value: val,
    locked: true,
  });
  char[key] = others;
}

function syncInnateHarmonyBreakAmpBuff(member, charDef) {
  if (!member) return;
  if (!Array.isArray(member.buffs)) member.buffs = [];
  if (!member.globalBuffActive) member.globalBuffActive = {};
  // 旧版写在个人 Buff：迁出到面板并清引用
  const innateBuffs = member.buffs.filter(isInnateHarmonyBuff);
  innateBuffs.forEach((b) => {
    member.buffs = member.buffs.filter((x) => x.id !== b.id);
    purgeMemberBuffReferences(member, b.id);
  });
  const val = Number(charDef?.harmonyBreakAmp) || 0;
  const name = charDef?.name
    ? `${charDef.name}·本体属性·谐度破坏增幅`
    : '角色本体属性·谐度破坏增幅';
  if (!member.char) member.char = createMemberCharDefaults();
  upsertCharDefHarmonyBreakAmpSource(member.char, { value: val, name });
}

/** 集谐模态系统 Buff 游戏原文案（按角色/模态区分；未录入返回空串） */
function convergenceModeGameText(member) {
  if (!member) return '';
  const cid = String(member.characterId || '');
  const mode = member.combatMode || '';
  let roleName = '';
  if (cid === MONING_CHAR_ID && mode === 'convergenceResponse') roleName = '莫宁';
  else if (cid === LINNEI_CHAR_ID && mode === 'convergence') roleName = '琳奈';
  else if (cid === LUHESI_CHAR_ID && mode === 'convergence') roleName = '陆·赫斯';
  else if (cid === DANIA_CHAR_ID && mode === 'convergence') roleName = '达妮娅';
  else if (cid === QINGXIAO_CHAR_ID && mode === 'convergence') roleName = '清宵';
  if (!roleName) return '';
  const base =
      '响应【集谐·干涉】：目标每有一层【集谐·干涉】可使' + roleName + '对其造成的最终伤害提升，' +
      roleName + '的每点谐度破坏增幅计入0.12%的最终伤害提升。' +
      roleName + '处于编队中时，目标的【集谐·干涉】层数上限增加1层。';
    if (cid === QINGXIAO_CHAR_ID && (Number(member.resonanceUnlocked) || 0) >= 6) {
      return base + '\n6链时响应效果提升20%：每点谐度破坏增幅计入0.144%。';
    }
  return base;
}

function ensureConvergenceModeBuff(member) {
  if (!member) return;
  if (!Array.isArray(member.buffs)) member.buffs = [];
  if (!member.globalBuffActive) member.globalBuffActive = {};
  if (!member.globalBuffStacks) member.globalBuffStacks = {};
  member.convergenceMode = !!member.convergenceMode;
  // 清宵 6链：响应【集谐·干涉】效果提升20%（每点谐度破坏增幅 0.12% → 0.144%）
  const qxC6Vuln =
    String(member.characterId || '') === QINGXIAO_CHAR_ID &&
    (Number(member.resonanceUnlocked) || 0) >= 6
      ? CONVERGENCE_DEFAULT_VULN * 1.2
      : CONVERGENCE_DEFAULT_VULN;
  let b = member.buffs.find(isSystemConvergenceBuff);
  if (!member.convergenceMode) {
    if (b) {
      const id = b.id;
      member.buffs = member.buffs.filter((x) => x.id !== id);
      purgeMemberBuffReferences(member, id);
    }
    // 清理旧手填集谐（不再计入、也不再展示）
    const legacy = member.buffs.filter(
      (x) => isConvergenceBuffCategory(x.category) && !isSystemConvergenceBuff(x)
    );
    legacy.forEach((x) => purgeMemberBuffReferences(member, x.id));
    member.buffs = member.buffs.filter(
      (x) => !isConvergenceBuffCategory(x.category) || isSystemConvergenceBuff(x)
    );
    return;
  }
  if (!b) {
    b = normalizeBuff({
      id: genId(),
      category: 'convergence',
      name: isConvergenceLikeCombatMode(member.combatMode)
        ? `${getCombatModeLabel(member.combatMode)}模态`
        : '集谐模态',
      mode: 'stack',
      value: 0,
      maxStacks: 99,
      sourceTag: CONVERGENCE_MODE_SOURCE_TAG,
      convergenceVuln: qxC6Vuln,
      gameText: convergenceModeGameText(member),
    });
    member.buffs.push(b);
  } else {
    b.name = isConvergenceLikeCombatMode(member.combatMode)
      ? `${getCombatModeLabel(member.combatMode)}模态`
      : '集谐模态';
    b.category = 'convergence';
    b.mode = 'stack';
    b.sourceTag = CONVERGENCE_MODE_SOURCE_TAG;
    b.convergenceVuln = qxC6Vuln;
    const gt = convergenceModeGameText(member);
    if (gt) b.gameText = gt;
  }
  if (member.globalBuffActive[b.id] === undefined) member.globalBuffActive[b.id] = true;
  if (member.globalBuffStacks[b.id] === undefined) member.globalBuffStacks[b.id] = 0;
  // 开启模态时一并清掉旧手填集谐
  const legacyOn = member.buffs.filter(
    (x) => isConvergenceBuffCategory(x.category) && !isSystemConvergenceBuff(x)
  );
  legacyOn.forEach((x) => purgeMemberBuffReferences(member, x.id));
  member.buffs = member.buffs.filter(
    (x) => !isConvergenceBuffCategory(x.category) || isSystemConvergenceBuff(x)
  );
}

function syncSpecialCharHarmonyBreakAmpFromRoster(index, specialChar) {
  const member = state.members?.[index];
  if (!member || !specialChar) return;
  specialChar.harmonyBreakAmp = getMemberHarmonyBreakAmpTotal(member);
}

/** 处决谐幅保留角色面板和未镜像来源，已镜像 Buff 按本技能覆盖结算。 */
function getSpecialSkillHarmonyBreakAmp(item, context) {
  const rosterIdx = getSpecialSkillRosterIndex(item);
  const specialChar = getSpecialSkillCharacter(item);
  // 全队来源沿用原有特殊角色的面板基准，同时替换其中已计入的可镜像来源。
  const baseIdx = rosterIdx >= 0 ? rosterIdx : state.specialSkills.characters.indexOf(specialChar);
  const roster = state.members?.[baseIdx] || null;
  const total = roster ? getMemberHarmonyBreakAmpTotal(roster) : Number(specialChar?.harmonyBreakAmp) || 0;
  const W = window.__WC;
  const resolved = context || W?.resolveSpecialSkillContext?.(item);
  if (!resolved?.member || !W?.sumActiveBuffs) return total;
  const mirrored = (resolved.member.buffs || []).filter(b => !isInnateHarmonyBuff(b) &&
    (isHarmonyBreakAmpBuff(b) || (isCompositeBuff(b) &&
      (b.effects || []).some(fx => fx?.zone === 'harmonyBreakAmp'))));
  // 来源被特殊角色排除后镜像会消失，扣除集合必须独立于当前镜像。
  const originals = (roster?.buffs || []).filter(b => !isInnateHarmonyBuff(b) &&
    (isHarmonyBreakAmpBuff(b) || (isCompositeBuff(b) &&
      (b.effects || []).some(fx => fx?.zone === 'harmonyBreakAmp'))) &&
    ((b.teamSourceId ? isSpecialEffectBuffSource(b) : shouldSyncPersonalBuffToSpecial(b)) ||
      mirrored.some(m => m.teamSourceId ? b.teamSourceId === m.teamSourceId :
        m.personalSourceId ? b.id === m.personalSourceId : b.id === m.id))); 
  const skillName = String(item?.name || '').trim();
  const unit = skillName ? { name: skillName, librarySkillName: skillName, libraryName: skillName } : null;
  const previous = roster ? W.sumActiveBuffs(roster.globalBuffActive || {}, 'harmonyBreakAmp', '',
    originals, roster.globalBuffStacks || {}, { member: roster, ignoreType: true }) : 0;
  const selected = W.sumActiveBuffs(resolved.active || {}, 'harmonyBreakAmp', '', mirrored,
    resolved.stacks || {}, { member: resolved.member, parentSkill: unit, unit, ignoreType: true });
  return total - previous + selected;
}

function resyncMemberHarmonyBreakAmpToSpecial(member) {
  ensureSpecialSkillsState();
  let idx = getMemberIndex(member || getActiveMember());
  if (idx < 0 && member?.id) {
    idx = state.specialSkills.characters.findIndex((c) => c?.id === member.id);
  }
  if (idx < 0) return;
  syncSpecialCharHarmonyBreakAmpFromRoster(idx, state.specialSkills.characters[idx]);
}

function syncInnateHarmonyBreakAmpFromCharDb() {
  if (!charSkillDb?.characters?.length) return;
  ensureSpecialSkillsState();
  state.members.forEach((m, idx) => {
    if (!m?.characterId || !m.char) return;
    const charDef = findCharSkillDef(m.characterId);
    if (!charDef) return;
    syncInnateHarmonyBreakAmpBuff(m, charDef);
    syncMemberCombatModeState(m);
    syncSpecialCharHarmonyBreakAmpFromRoster(idx, state.specialSkills.characters[idx]);
  });
}

/**
 * 全队 Buff 是否镜像进特殊技能库。
 * 绯雪全队【雪锈】霜渐效应：只进绯雪 / 洛瑟菈 / 穗穗槽；选「全队」来源时仍可读。
 */
function isSpecialTeamBuffMirror(source, specialCharIndex) {
  if (!isSpecialEffectBuffSource(source)) return false;
  const key = String(source?.templateKey || '');
  if (key === FEIXUE_XUEXIU_TEAM_KEY || key === FEIXUE_XUEXIU_KEY) {
    if (!Number.isFinite(specialCharIndex)) return true;
    const charId = String(state.members?.[specialCharIndex]?.characterId || '');
    if (key === FEIXUE_XUEXIU_KEY) return charId === FEIXUE_CHAR_ID;
    return typeof isFeixueXuexiuTeamRecipientCharId === 'function'
      ? isFeixueXuexiuTeamRecipientCharId(charId)
      : charId === FEIXUE_CHAR_ID;
  }
  if (
    key === CARTETHYIA_XIANHUA_SHENQUAN_KEY ||
    key === CARTETHYIA_XIANHUA_SHENQUAN_LEGACY_KEY ||
    (typeof isCartethyiaXianhuaShenquanBuff === 'function' &&
      isCartethyiaXianhuaShenquanBuff(source))
  ) {
    if (!Number.isFinite(specialCharIndex)) return true;
    return String(state.members?.[specialCharIndex]?.characterId || '') === CARTETHYIA_CHAR_ID;
  }
  if (
    key === XIAKONG_OUTRO_WIND_EROSION_KEY ||
    key === XIAKONG_OUTRO_WIND_EROSION_LEGACY_KEY ||
    (typeof isXiakongOutroWindErosionBuff === 'function' &&
      isXiakongOutroWindErosionBuff(source))
  ) {
    if (!Number.isFinite(specialCharIndex)) return true;
    return String(state.members?.[specialCharIndex]?.characterId || '') === CARTETHYIA_CHAR_ID;
  }
  return true;
}

/** 武器 / 声骸 / 全队同步镜像 / 角色模板等自动来源，清空手填时保留 */
function isAutoOrSyncedMemberBuff(buff) {
  if (!buff) return false;
  if (buff.teamSourceId) return true;
  if (isProtectedSystemBuff(buff)) return true;
  if (isCharacterTemplateBuff(buff)) return true;
  if (isWeaponGeneratedBuff(buff)) return true;
  if (isEchoSetGeneratedBuff(buff)) return true;
  if (isEchoMainGeneratedBuff(buff)) return true;
  return false;
}

function isManualMemberBuff(buff) {
  return !isAutoOrSyncedMemberBuff(buff);
}

/** 清空当前角色手填面板来源与手填 Buff；保留武器/声骸/角色本体及全队同步 Buff */
function clearMemberManualSources(member) {
  if (!member?.char) return false;
  ensureMemberUiState(member, { light: true });
  const memberIdx = getMemberIndex(member);

  Object.keys(CHAR_STATS).forEach((statKey) => {
    const sourcesKey = charStatSourcesKey(statKey);
    const kept = (member.char[sourcesKey] || []).filter(isProtectedPanelSource);
    if (statKey === 'energyRegenPct') {
      member.char[sourcesKey] = ensureEnergyRegenBaseSource(kept);
      return;
    }
    if (statKey === 'offsetHarmonyEffPct') {
      member.char[sourcesKey] = ensureOffsetHarmonyEffBaseSource(kept);
      return;
    }
    if (!kept.length) {
      const entry = { id: genId(), name: '来源1', value: 0 };
      if (statKey === 'typeDmgBonus') entry.damageType = '';
      member.char[sourcesKey] = [entry];
    } else {
      member.char[sourcesKey] = kept;
    }
  });

  const removeIds = new Set((member.buffs || []).filter(isManualMemberBuff).map((b) => b.id));
  if (removeIds.size) {
    member.buffs = (member.buffs || []).filter((b) => !removeIds.has(b.id));
    removeIds.forEach((id) => purgeMemberBuffReferences(member, id));
  }

  if (memberIdx >= 0) purgeManualTeamBuffsFromMemberIndex(memberIdx);

  syncEchoLoadout(member);
  syncTeamBuffsToMembers();
  normalizeMemberBuffKeys(member);
  return true;
}

function seedMemberFrom(prev, target) {
  target.char = cloneCharForMember(prev.char);
  const prevBuffs = prev.buffs.filter((b) => !b.teamSourceId);
  const cloned = cloneBuffsWithNewIds(prevBuffs, prev.globalBuffActive, prev.globalBuffStacks);
  target.buffs = cloned.buffs;
  target.globalBuffActive = cloned.globalBuffActive;
  target.globalBuffStacks = cloned.globalBuffStacks;
  target.activeBuffTab = prev.activeBuffTab;
  target.activeBuffGroup = prev.activeBuffGroup || getBuffGroupForCategory(prev.activeBuffTab);
  target.cycleConfig = normalizeCycleConfig(prev.cycleConfig);
  target.echoConfig = normalizeEchoConfig(JSON.parse(JSON.stringify(prev.echoConfig || defaultEchoConfig('43311'))));
  target.charStatExpanded = { atkPercent: false, critRate: false, critDmg: false };
  target.seeded = true;
  clearMemberBuffStackOverrides(target);
  syncTeamBuffsToMembers();
}

function switchMember(index) {
  if (index < 0 || index > 2) return;
  switchToMemberView(index);
  const member = getActiveMember();
  // 三列配装各自独立：不再从上一槽位复制面板/Buff（否则角色2会看起来像角色1的拷贝）
  if (!member.seeded) member.seeded = true;
  normalizeMemberBuffKeys(member);
  syncTeamBuffsToMembers();
}

/** 换角色时清掉个人侧残留 Buff，仅保留全队镜像（随后由模板/武器重新写入） */
function stripPersonalBuffsKeepTeamMirrors(member) {
  if (!member) return;
  const remove = (member.buffs || []).filter((b) => !b.teamSourceId);
  remove.forEach((b) => purgeMemberBuffReferences(member, b.id, { allRounds: true }));
  member.buffs = (member.buffs || []).filter((b) => !!b.teamSourceId);
}

function normalizePhasesData(phases) {
  return (phases || []).map((p) => ({
    ...p,
    locked: !!p.locked,
    buffStacks: { ...(p.buffStacks || {}) },
    buffActiveSig: Array.isArray(p.buffActiveSig) ? p.buffActiveSig.map((x) => ({ ...x })) : [],
    buffStacksSig: Array.isArray(p.buffStacksSig) ? p.buffStacksSig.map((x) => ({ ...x })) : [],
    skills: (p.skills || []).map((raw) => {
      const s = stripSkillRuntimeFields({ ...raw });
      return {
        ...s,
        locked: !!s.locked,
        multCount: normalizeMultCount(s.multCount),
        energyRegen: normalizeEnergyRegen(s.energyRegen),
        multComponents: normalizeMultComponents(s.multComponents),
        buffStacks: { ...(s.buffStacks || {}) },
        buffActiveSig: Array.isArray(s.buffActiveSig) ? s.buffActiveSig.map((x) => ({ ...x })) : [],
        buffStacksSig: Array.isArray(s.buffStacksSig) ? s.buffStacksSig.map((x) => ({ ...x })) : [],
        frozenBuffActive: { ...(s.frozenBuffActive || {}) },
        frozenBuffStacks: { ...(s.frozenBuffStacks || {}) },
        hits: (s.hits || []).map((h) => ({
          ...h,
          multCount: normalizeMultCount(h.multCount),
          energyRegen: normalizeEnergyRegen(h.energyRegen),
          multLocked: !!h.multLocked,
          buffStacks: { ...(h.buffStacks || {}) },
          buffActiveSig: Array.isArray(h.buffActiveSig) ? h.buffActiveSig.map((x) => ({ ...x })) : [],
          buffStacksSig: Array.isArray(h.buffStacksSig) ? h.buffStacksSig.map((x) => ({ ...x })) : [],
          frozenBuffActive: { ...(h.frozenBuffActive || {}) },
          frozenBuffStacks: { ...(h.frozenBuffStacks || {}) },
        })),
      };
    }),
  }));
}

function memberFromV1Data(data) {
  const defaults = createMemberWithDefaults(0);
  const char = normalizeChar({ ...defaults.char, ...(data.char || {}) });
  delete char.monsterRes;
  delete char.monsterLevel;
  return {
    id: genId(),
    name: '角色1',
    seeded: true,
    char,
    buffs: Array.isArray(data.buffs)
      ? data.buffs.map((b) => normalizeBuff({
          ...b,
          damageType: b.damageType || '',
          defenseKind: b.defenseKind || (DEFENSE_BUFF_CATS.has(b.category) ? 'pen' : ''),
        }))
      : defaults.buffs,
    globalBuffActive: { ...(data.globalBuffActive || {}) },
    globalBuffStacks: { ...(data.globalBuffStacks || {}) },
    activeBuffTab: data.activeBuffTab || 'generalBonus',
    rotationCollapsed: !!data.rotationCollapsed,
    paletteCollapsed: !!data.paletteCollapsed,
    rotationCatalog: Array.isArray(data.rotationCatalog) ? data.rotationCatalog : defaults.rotationCatalog,
    phases: Array.isArray(data.phases) ? normalizePhasesData(data.phases) : defaults.phases,
    echoConfig: defaults.echoConfig,
    results: { total: 0, phases: {}, dps: 0 },
    charStatExpanded: { atkPercent: false, critRate: false, critDmg: false },
  };
}

function serializeMember(member) {
  // 导出前已 flush 各轮；此处禁止再 syncEcho，避免多轮被当前实况串写
  ensureMemberUiState(member, { force: true, skipEchoSync: true });
  if (member.cycleConfig?.enabled) saveActiveRoundSnapshot(member);
  const cycleRoundIdx = member.cycleConfig?.enabled ? readActiveCycleRoundIndex(member) : 0;
  const cycleRound = member.cycleConfig?.enabled ? member.cycleConfig.rounds?.[cycleRoundIdx] : null;
  const phasesSource =
    member.cycleConfig?.enabled && cycleRound?.phases ? cycleRound.phases : member.phases;
  const charSource = member.cycleConfig?.enabled && cycleRound?.char ? cycleRound.char : member.char;
  const catalogSource =
    member.cycleConfig?.enabled && cycleRound?.rotationCatalog
      ? cycleRound.rotationCatalog
      : member.rotationCatalog;
  const char = { ...charSource };
  Object.keys(CHAR_STATS).forEach((statKey) => {
    const sourcesKey = charStatSourcesKey(statKey);
    char[sourcesKey] = (char[sourcesKey] || []).map((item) => ({ ...item }));
  });
  const cfg = member.cycleConfig || defaultCycleConfig();
  return {
    id: member.id,
    name: member.name,
    effectHintExtras: { ...(member.effectHintExtras || {}) },
    skillLevelSettings: member.skillLevelSettings ? JSON.parse(JSON.stringify(member.skillLevelSettings)) : undefined,
    seeded: !!member.seeded,
    char,
    charStatExpanded: { ...member.charStatExpanded },
    buffs: cloneBuffsSnapshot(member.buffs),
    globalBuffActive: { ...member.globalBuffActive },
    globalBuffStacks: { ...member.globalBuffStacks },
    chainBuffStates: cloneChainBuffStates(member.chainBuffStates),
    excludedTeamBuffIds: [...(member.excludedTeamBuffIds || [])],
    manuallyExcludedTeamBuffIds: [...(member.manuallyExcludedTeamBuffIds || [])],
    activeBuffTab: member.activeBuffTab,
    activeBuffGroup: member.activeBuffGroup,
    cycleConfig: {
      enabled: !!cfg.enabled,
      count: cfg.count,
      activeRound: cfg.activeRound,
      rounds: (cfg.rounds || []).map(serializeCycleRound),
    },
    rotationCollapsed: !!member.rotationCollapsed,
    paletteCollapsed: !!member.paletteCollapsed,
    showMultDetail: !!member.showMultDetail,
    multCheckMode: !!member.multCheckMode,
    multCheckZone: member.multCheckZone || null,
    panelStatMode: member.panelStatMode === 'hpDef' ? 'hpDef' : 'atk',
    characterId: member.characterId || member.nanokaCharId || null,
    resonanceUnlocked: normalizeResonanceUnlocked(member.resonanceUnlocked),
    resonanceDmgByChain: { ...ensureResonanceDmgByChain(member) },
    weaponRefDmgByRank: { ...ensureWeaponRefDmgByRank(member) },
    convergenceMode: !!member.convergenceMode,
    combatMode: member.combatMode || null,
    brantLifeMode: normalizeBrantLifeMode(member.brantLifeMode),
    skillPalette: (member.skillPalette || []).map((p) => ({ ...p })),
    resonanceAxis: !cfg.enabled && member.resonanceAxis
      ? cloneResonanceAxis(member.resonanceAxis)
      : undefined,
    rotationCatalog: catalogSource.map((c) => ({
      ...c,
      stackLayers: { ...(c.stackLayers || {}) },
    })),
    echoConfig: {
      layout: member.echoConfig?.layout || '43311',
      mainSlotIndex: Number.isInteger(member.echoConfig?.mainSlotIndex) ? member.echoConfig.mainSlotIndex : 0,
      setLoadout: (member.echoConfig?.setLoadout || defaultEchoSetLoadout()).map((entry) => ({
        setId: entry.setId || null,
        count: Number(entry.count) || 0,
        echoId: entry.echoId || null,
      })),
      // PROBE_FIX_ECHO_FIDELITY：与 V2 字段清单同源（原来手写一份、漏了 noMain2）
      slots: (member.echoConfig?.slots || defaultEchoConfig('43311').slots).map(mapV2EchoSlot),
    },
    echoSubTemplateId: member.echoSubTemplateId || '',
    echoActiveSlot: Number.isInteger(member.echoActiveSlot) ? member.echoActiveSlot : null,
    echoExpandedSetEntry: Number.isInteger(member.echoExpandedSetEntry) ? member.echoExpandedSetEntry : null,
    echoLoadoutCollapsed: !!member.echoLoadoutCollapsed,
    weaponSelection: normalizeWeaponSelection(member.weaponSelection),
    checkBuffVerified: { ...(member.checkBuffVerified || {}) },
    phases: phasesSource.map((p) => ({
      id: p.id,
      name: p.name,
      collapsed: !!p.collapsed,
      locked: !!p.locked,
      combatMode: normalizePhoebeOverrideCombatMode(p.combatMode),
      buffMode: p.buffMode,
      buffActive: { ...p.buffActive },
      buffStacks: { ...p.buffStacks },
      buffActiveSig:
        p.buffMode === 'custom' ? captureBuffActiveSigEntries(p.buffActive, member) : [],
      buffStacksSig:
        p.buffMode === 'custom' ? captureBuffStacksSigEntries(p.buffStacks, member) : [],
      skills: p.skills.map((s) => serializeSkill(s, member)),
    })),
  };
}

function rebuildUidCounter() {
  const ids = [];
  state.members.forEach((member) => {
    ids.push(member.id);
    member.buffs.forEach((b) => ids.push(b.id));
    (member.cycleConfig?.rounds || []).forEach((round) => {
      (round.buffs || []).forEach((b) => ids.push(b.id));
      (round.phases || []).forEach((p) => {
        ids.push(p.id);
        (p.skills || []).forEach((s) => {
          ids.push(s.id);
          (s.hits || []).forEach((h) => ids.push(h.id));
        });
      });
      (round.rotationCatalog || []).forEach((c) => ids.push(c.id));
    });
    Object.keys(CHAR_STATS).forEach((statKey) => {
      (member.char[charStatSourcesKey(statKey)] || []).forEach((item) => ids.push(item.id));
    });
    member.rotationCatalog.forEach((c) => ids.push(c.id));
    (member.skillPalette || []).forEach((p) => ids.push(p.id));
    member.phases.forEach((p) => {
      ids.push(p.id);
      p.skills.forEach((s) => {
        ids.push(s.id);
        (s.hits || []).forEach((h) => ids.push(h.id));
      });
    });
  });
  (state.specialSkills?.characters || []).forEach((c) => {
    ids.push(c.id);
    (c.buffs || []).forEach((b) => ids.push(b.id));
  });
  (state.specialSkills?.items || []).forEach((item) => ids.push(item.id));
  const shared = state.team?.sharedBuffs;
  if (shared?.buffs) shared.buffs.forEach((b) => ids.push(b.id));
  const nums = ids
    .map((id) => parseInt(String(id).replace('id_', ''), 10))
    .filter((n) => Number.isFinite(n));
  uid = Math.max((nums.length ? Math.max(...nums) : 0) + 1, (typeof GENID_FLOOR === "number" ? GENID_FLOOR : 1));
}

function serializeSkill(skill, member) {
  const buffMember = member || { buffs: [] };
  const skillActiveSig =
    skill.buffMode === 'custom' ? captureBuffActiveSigEntries(skill.buffActive, buffMember) : [];
  const skillStacksSig =
    skill.buffMode === 'custom' ? captureBuffStacksSigEntries(skill.buffStacks, buffMember) : [];
  return {
    id: skill.id,
    ...(skill.roundSyncKey ? { roundSyncKey: skill.roundSyncKey } : {}),
    timelineMultOverride: skill.timelineMultOverride === true,
    multComponents: normalizeMultComponents(skill.multComponents),
    name: skill.name,
    catalogId: skill.catalogId || null,
    baseMult: skill.baseMult,
    multCount: normalizeMultCount(skill.multCount),
    damageType: skill.damageType || '',
    scaleStat: skill.scaleStat === 'hp' || skill.scaleStat === 'def' ? skill.scaleStat : 'atk',
    fixedDamage: !!skill.fixedDamage || isFixedDamageByName(skill.name),
    energyRegen: normalizeEnergyRegen(skill.energyRegen),
    split: !!skill.split,
    buffMode: skill.buffMode,
    buffActive: { ...skill.buffActive },
    buffStacks: { ...skill.buffStacks },
    explicitBuffStackIds: [...(skill.explicitBuffStackIds || [])],
    buffActiveSig: skillActiveSig,
    buffStacksSig: skillStacksSig,
    expanded: !!skill.expanded,
    locked: !!skill.locked,
    frozenBuffActive: { ...(skill.frozenBuffActive || {}) },
    frozenBuffStacks: { ...(skill.frozenBuffStacks || {}) },
    brantLifeMode:
      skill.brantLifeMode === BRANT_LIFE_PLAY || skill.brantLifeMode === BRANT_LIFE_MY
        ? skill.brantLifeMode
        : '',
    combatMode: normalizePhoebeOverrideCombatMode(skill.combatMode),
    hits: (skill.hits || []).map((h) => ({
      id: h.id,
      ...(h.roundSyncKey ? { roundSyncKey: h.roundSyncKey } : {}),
      name: h.name,
      baseMult: h.baseMult,
      multCount: normalizeMultCount(h.multCount),
      energyRegen: normalizeEnergyRegen(h.energyRegen),
      buffMode: h.buffMode,
      buffActive: { ...h.buffActive },
      buffStacks: { ...h.buffStacks },
      explicitBuffStackIds: [...(h.explicitBuffStackIds || [])],
      buffActiveSig:
        h.buffMode === 'custom' ? captureBuffActiveSigEntries(h.buffActive, buffMember) : [],
      buffStacksSig:
        h.buffMode === 'custom' ? captureBuffStacksSigEntries(h.buffStacks, buffMember) : [],
      expanded: !!h.expanded,
      frozenBuffActive: { ...(h.frozenBuffActive || {}) },
      frozenBuffStacks: { ...(h.frozenBuffStacks || {}) },
      damageType: h.damageType || '',
      scaleStat: h.scaleStat === 'hp' || h.scaleStat === 'def' ? h.scaleStat : skill.scaleStat === 'hp' || skill.scaleStat === 'def' ? skill.scaleStat : 'atk',
      fixedDamage: !!h.fixedDamage || !!skill.fixedDamage || isFixedDamageByName(h.name) || isFixedDamageByName(skill.name),
    })),
  };
}

function scheduleSave() {
  clearTimeout(saveTimer);
  if (configWorkspaceOperation.deferSave()) { saveTimer = null; return; }
  saveTimer = setTimeout(saveState, autoSaveDelayMs);
}

/** 页面关闭前尽量刷出挂起的自动保存（同步兜底，避免异步 IDB 来不及落盘） */
if (typeof window !== 'undefined' && !window.__tbaBeforeUnloadSaveBound) {
  window.__tbaBeforeUnloadSaveBound = true;
  window.addEventListener('beforeunload', () => {
    try {
      if (saveTimer || configWorkspaceOperation.active) {
        clearTimeout(saveTimer);
        saveTimer = null;
        if (typeof saveStateSyncForUnload === 'function') saveStateSyncForUnload();
      } else if (!lastSavePersisted) {
        // 直接 saveState() 后立即刷新/关页：IDB 写入在途，同步补一份 localStorage 网
        if (typeof saveStateSyncForUnload === 'function') saveStateSyncForUnload();
      }
    } catch {
      /* ignore */
    }
  });
}

function buildWorkspacePayload() {
  flushAllMemberPanelsBeforePersist();
  return {
    version: 2,
    sidebarTab: getSidebarTab(),
    team: { ...state.team },
    members: state.members.map(serializeMember),
    specialSkills: {
      characters: (state.specialSkills?.characters || []).map(serializeSpecialCharacter),
      activeCharacterIndex: state.specialSkills?.activeCharacterIndex ?? 0,
      items: (state.specialSkills?.items || []).map(serializeSpecialSkillItem),
    },
    schemeDraft: { ...(state.schemeDraft || { name: '未命名方案', author: '' }) },
    exportCardDraft: {
      axisName: String(state.exportCardDraft?.axisName || state.schemeDraft?.name || '未命名轴'),
      // 轴长与全队轴长同步（多轮=轮次总长）：不再信任历史手填值
      axisLength:
        typeof getTeamResultsDuration === 'function'
          ? getTeamResultsDuration()
          : Number(state.team?.axisDuration) || 20,
      difficulty: String(state.exportCardDraft?.difficulty || ''),
      performance: String(
        state.exportCardDraft?.performance || state.exportCardDraft?.stability || ''
      ),
      axisKind: normalizeAxisKind(state.exportCardDraft?.axisKind),
      shareCode: String(state.exportCardDraft?.shareCode || '（网页上线后生成）'),
    },
    refVideoUrl: state.refVideoUrl || '',
    calcNotes: state.calcNotes || '',
    charPickerElement: state.charPickerElement || 'all',
    charPickerRank5Only: !!state.charPickerRank5Only,
    weaponPickerSearch: state.weaponPickerSearch || '',
    workspacePhase: normalizeWorkspacePhase(state.workspacePhase),
    axisTimeViz: !!state.axisTimeViz,
    setupLayout: getSetupLayout(),
    buffDrawer: {
      open: !!state.buffDrawer?.open,
      width: Math.max(300, Math.min(640, Number(state.buffDrawer?.width) || 400)),
    },
    checkInspect: (() => {
      const c = { ...ensureCheckInspectState() };
      delete c.ctxMenu;
      delete c.verifyPaintHeld;
      return c;
    })(),
    exportConfigSnapshots: normalizeExportConfigSnapshots(state.exportConfigSnapshots),
    skillNamingTemplates: ensureSkillNamingTemplates().map((t) => ({
      ...t,
      overrides: { ...(t.overrides || {}) },
    })),
    buffGameTextUi: { editMode: !!ensureBuffGameTextUi().editMode },
    echoSubSimUi: serializeEchoSubSimUiForPersist(),
  };
}

function serializeEchoSubSimUiForPersist() {
  const ui = state.echoSubSimUi;
  if (!ui || typeof ui !== 'object') return undefined;
  return {
    memberIndex: Number.isInteger(ui.memberIndex) ? ui.memberIndex : 0,
    dirty: !!ui.dirty,
    configStale: !!ui.configStale,
    charId: String(ui.charId || ''),
    baselineFingerprint: String(ui.baselineFingerprint || ''),
    _memberPinned: !!ui._memberPinned,
    subs: Array.isArray(ui.subs)
      ? ui.subs.map((s) => ({
          key: String(s.key || ''),
          slotIndex: Number(s.slotIndex) || 0,
          subIndex: Number(s.subIndex) || 0,
          cost: Number(s.cost) || 0,
          id: String(s.id || ''),
          value: Number(s.value) || 0,
          damageType: String(s.damageType || ''),
        }))
      : null,
    mains: Array.isArray(ui.mains)
      ? ui.mains.map((m) => ({
          key: String(m.key || ''),
          slotIndex: Number(m.slotIndex) || 0,
          cost: Number(m.cost) || 0,
          id: String(m.id || ''),
          value: Number(m.value) || 0,
          panelTarget: String(m.panelTarget || ''),
          element: String(m.element || ''),
          label: String(m.label || ''),
          needsElement: !!m.needsElement,
        }))
      : null,
    savedPlans: Array.isArray(ui.savedPlans)
      ? ui.savedPlans.slice(0, 30).map((p) => ({
          id: String(p.id || ''),
          savedAt: Number(p.savedAt) || 0,
          memberIndex: Number.isInteger(p.memberIndex) ? p.memberIndex : 0,
          memberName: String(p.memberName || ''),
          characterId: String(p.characterId || ''),
          baseDamage: Number(p.baseDamage) || 0,
          simDamage: Number(p.simDamage) || 0,
          changePct: Number(p.changePct) || 0,
          changes: Array.isArray(p.changes)
            ? p.changes.map((c) => ({
                kind: String(c.kind || ''),
                text: String(c.text || ''),
              }))
            : [],
        }))
      : [],
  };
}

