  const bEmpty = b === undefined || b === null || (typeof b === 'object' && b !== null && Object.keys(b).length === 0);
  if (aEmpty || bEmpty) return aEmpty && bEmpty;
  if (typeof a !== typeof b) return false;
  if (typeof a !== 'object') return a === b;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) { if (a.length !== b.length) return false; return a.every((x, i) => __usEqual(x, b[i])); }
