const CFG_SNAP_MAX_ROWS = 12;
const CFG_SNAP_LS_PREFIX = 'cfg-snap-ls:';
const CFG_SNAP_LS_MAX = 2 * 1024 * 1024;
/** V2 基底锚点独立存档键：锚点完整工作区单独落盘，刷新/导入后仍可恢复 */
const CFG_SNAP_ANCHOR_KEY = '__cfg_anchor_v2__';
/** PROBE_FIX_ANCHOR_IDENTITY：基底身份旁挂键。与工作区存档分开存，老构建读不到它、也不会被它污染。 */
const CFG_ANCHOR_META_KEY = '__cfg_anchor_meta_v1__';
