/** 链精配置计算规则版本：引擎/数据规则变化（会影响已保存行数值）时递增；
 *  用于标记旧行「数值基于旧规则」，提示用户刷新（见 getConfigSnapshotState）。 */
const CFG_RULES_VERSION = '20260820-r1';
/** 新 Excel 开关行 schema 版本（DSH 会签 v2，B1 起实施依据） */
const CFG_EXCEL_RULES_VERSION = '20260909-r1';

function chainExcelStableKeyNormalize(s) {
  return String(s || '')
    .trim()
    .replace(/[\s\u3000]+/g, ' ')
    .replace(/[（）()]/g, '')
    .replace(/[：:]/g, '_');
}

function chainExcelPhaseKey(phase, occurrence) {
  const id = String(phase && phase.id || '');
  return id ? `phase:${id}` : `phase:${chainExcelStableKeyNormalize(phase && phase.name)}#${occurrence || 1}`;
}

function chainExcelAxisKey(item, occurrence) {
  if (!item) return '';
  if (item.catalogId) return `catalog:${item.catalogId}${occurrence > 1 ? '#' + occurrence : ''}`;
  const stable = item.linkedSpecialSkillId
    ? `linked:${item.linkedSpecialSkillId}`
    : `custom:${chainExcelStableKeyNormalize(item.name || '')}`;
  return occurrence > 1 ? `${stable}#${occurrence}` : stable;
}

function chainExcelSkillKey(skill, occurrence) {
  if (!skill) return '';
  if (skill.catalogId) return `catalog:${skill.catalogId}${occurrence > 1 ? '#' + occurrence : ''}`;
  const base = `custom:${chainExcelStableKeyNormalize(skill.name || '')}`;
  return occurrence > 1 ? `${base}#${occurrence}` : base;
}

function chainExcelHitKey(skillKey, segmentIndex) {
  return `${skillKey}#hit:${Number(segmentIndex) || 1}`;
}

function chainExcelBuffKey(buff) {
  if (!buff) return '';
  if (buff.templateKey) return `tpl:${buff.templateKey}`;
  return `raw:${String(buff.category || '')}:${String(buff.zone || '')}:${chainExcelStableKeyNormalize(buff.name || '')}`;
}

function chainExcelLocalOverrideKey(parts) {
  return (parts || []).filter(Boolean).join('.');
}

/** B2 地基：buff id → 稳定 buffKey 映射（id→templateKey/raw 兜底） */
function chainExcelBuffIdToKeyMap(buffs) {
  const map = {};
  (buffs || []).forEach((b) => {
    if (!b || !b.id) return;
    map[String(b.id)] = chainExcelBuffKey(b);
  });
  return map;
}

/** 把按 buff 运行时 id 为键的开关/叠层图重键为 buffKey；未在 buffs 中查到的 id 保底 raw:<id> 并告警 */
function chainExcelRekeyBuffMap(origMap, idToKey, warnings, where) {
  const out = {};
  Object.entries(origMap || {}).forEach(([id, v]) => {
    const k = idToKey && idToKey[id];
    if (k) out[k] = v;
    else {
      const fallback = 'raw:' + id;
      if (!(fallback in out)) out[fallback] = v;
      else out[fallback] = v;
      if (warnings) warnings.push((where || '') + ' buff id 未在 buffs 命中 → ' + fallback);
    }
  });
  return out;
}

